var LB_GT=[{"t":"Khái quát","s":"Tổng quan luật biển quốc tế, nguồn, năm nguyên tắc cơ bản","pg":"tr.2–9","g":[{"h":"Câu hỏi định hướng chương I","lv":2,"b":[["p",72,"1. Biển có tầm quan trọng như thế nào đối với các quốc gia ven biển và các quốc gia liên quan, trong khu vực?",0],["p",72,"2. Cho biết tầm quan trọng của môn học Luật biển?",0],["p",72,"3. Luật biển quốc tế là gì? Luật biển quốc gia là gì? Liên hệ Luật biển Việt Nam?",0],["p",72,"4. Điểm khác biệt giữa Luật biển và Luật hàng hải?",0],["p",72,"5. Phân tích ngắn gọn nguồn của Luật biển quốc tế? Cho ví dụ? Liên hệ nguồn của luật biển Việt Nam?",0],["p",72,"6. Trình bày các phương tiện bổ trợ nguồn của luật biển quốc tế?",0],["p",72,"7. Trình bày các nguyên tắc cơ bản của luật biển quốc tế?",0]]},{"h":"Sơ đồ định hướng: Luật Biển 5 chương và Chương I","lv":2,"b":[["f","sd_lb5.svg",720,640,"Sơ đồ: Luật Biển gồm 5 chương, đi từ biết, hiểu đến vận dụng"],["f","sd_lbc1.svg",720,470,"Sơ đồ: Chương I Khái quát gồm khái niệm, nguồn, nguyên tắc"],["p",72,"Sơ đồ vẽ lại theo hình trong bài đăng nhóm lớp. Ở sơ đồ Chương I, phần nguyên tắc ghi bốn ý (tự do biển cả, công bằng, bảo vệ môi trường biển, Vùng là di sản chung của nhân loại); bài giảng ở dưới nêu năm nguyên tắc, nên đối chiếu khi ôn.",0]]},{"h":"","lv":0,"b":[["p",102,"LUẬT BIỂN QUỐC TẾ",2],["p",139,"Tổng quan về luật biển quốc tế",2],["p",102,"Các vùng biển đều quan trọng, mỗi vùng đều có vai trò của nó.",2]],"pg":[2,2]},{"h":"1. Sự hình thành của LBQT","lv":3,"b":[["p",103,"Trước thế kỷ XV, biển cả đã được use cho việc truyền đạo, thám hiểm và hàng hải.",2],["p",103,"Con người nhận thức được vai trò và tầm quan trọng của biển, nhưng cho đến thế kỷ XV chưa đặt ra vấn đề tranh giành quyền lực trên biển Từ thế kỷ XV, cùng với sự phát triển mạnh mẽ của kỹ thuật hàng hải và sự ý thức được tài nguyên trên biển k còn là vô tận, biển cả trở thành đối tượng chinh phục của các quốc gia Từ đó cần thiết phải có 1 hệ thống những nguyên tắc, quy phạm pháp luật hoàn chính nhằm đảm bảo và điều hòa lợi ích của các quốc gia … (nhưng chỉ là manh nha từ các học thuyết mang tính đối lập là thuyết “tự do biển cả” Mare Liberum, 1609 là để các nước đều bình đẳng trong việc khai thác biển nhưng chỉ có những nước cường quốc là được lợi cho nên chỉ được những quốc gia bảo thủ ủng hộ và “biển đóng” Mare Clausum, 1835 các quốc gia đều được tự xác lập vùng biển của mình và mỗi quốc gia có toàn quyền kiểm soát vùng biển đó và không ai được xâm phạm)",2],["p",103,"Các học thuyết",2],["p",85,"● Nguyên tắc Marie Liberum - tự do biển cả - được Hugo Grotius - luật gia Hà Lan đưa ra trong tác phẩm cùng tên năm 1609.",2],["p",85,"● Đối lập với quan điểm này là “biển đóng - Marie Clausum” của luật gia Anh John Selden đưa ra 1635.",2],["p",103,"Các hội nghị về Luật Biển Tính tập quán được hình thành",2],["p",85,"● Hội nghị luật biển lần thứ 1: 1958",2],["p",121,"○ Sau chiến tranh thế giới thứ 2, dưới sự bảo trợ của liên hợp quốc, hội nghị lần thứ 1 về luật biển được tổ chức tại Geneva",2],["p",175,"o Thông qua được 4 công ước:",2],["p",139,"§ CƯ về lãnh hải và vùng tiếp giáp lãnh hải , có hiệu lực ngày 10/9/1964, có 48 thành viên",2],["p",139,"§ CƯ về biển cả có hiệu lực 30/9/1964 có 59 thành viên",2],["p",139,"§ CƯ về đánh cá và bảo tồn cả tài nguyên sinh vật biển cả có hiệu lực 20/3/.1966 có 33 quốc gia thành viên",2],["p",139,"§ CƯ về thềm lục địa",3],["p",85,"● Hội nghị luật biển lần thứ 2 - Geneva năm 1960",3],["p",121,"○ Được tổ chức với nội dung là chiều rộng lãnh hải. Tuy nhiên hội nghị này k đạt được thỏa thuận (mở rộng lãnh hải => không được cho tàu biển tự do di chuyển nữa vì vấn đề chủ quyền dù là tuyến đường hình thành từ xưa đến nay => phải tìm đường mới)",3],["p",67,"Hội nghị luật biển lần thứ 3",3],["p",175,"o Sau 5 năm trù bị và 9 năm thương lượng của LHQ về luật biển đã thông qua một công ước mới về luật biển",3],["p",175,"o Văn bản cuối cùng này được coi như là hiến pháp về biển, những nước không tham gia kí kết nhưng vẫn coi nó như tập quán quốc tế (vd Mỹ)",3],["p",103,"Các nhân tố tác động",3],["p",85,"● Sự xuất hiện nhiều quốc gia mới giành được độc lập (họ yếu nhưng tiềm năng về biển cả rất lớn, luật biển lúc này bắt nguồn từ các nước yếu thế)",3],["p",85,"● Sự phát triển của khoa học kỹ thuật áp dụng trong lĩnh vực nghiên cứu và khai thác biển",3],["p",85,"● Nhiều hoạt động vận động trong việc triệu tập hội nghị biển:",3],["p",85,"● Tại phiên họp lần thứ 22 ĐHĐ LHQ 17/8/1967. Đại sứ Malta A.Pardo đã đưa ra quan điểm coi vùng đáy biển (aka VÙNG) nằm ngoài vùng tài phán QG là di sản chung của nhân loại cấm chạy đua vũ trang, tập trận.",3],["p",85,"● Sáng kiến thiết lập vùng đặc quyền kinh tế rộng 200 hải lý của các quốc gia châu Phi đưa ra tại hội nghị khu vực các quốc gian châu Phi - Yabunde Kenia 1970",3],["p",85,"● - NQ 3015 ngày 18/12/1962 của Đại hội đồng LHQ tuyên bố về …",3],["p",85,"● - NQ 2749 ngày 17/12/1970: tuyên bố nguyên",3],["p",85,"● - NQ của Đại hội có tầm ảnh hưởng lớn nhưng không có tính chất bắt buộc",3],["p",85,"● NQ của Hội đồng bảo an có tính bắt buộc",3],["p",139,"Các phán quyết của tòa án",3],["p",121,"○ Vụ eo biển Corfou",3],["p",121,"○ Vụ ngư trường Anh - Na Uy ngày 18/12/1951 xác nhận tính hợp pháp của đường cơ sở thẳng (xác định kiểu mới - giúp cho các quốc có cơ sở mới cho việc xác định đường cơ sở)",3],["p",121,"○ Vụ thềm lục địa biển Bắc ngày 20/2/1969 xác định bản chất pháp lý của thềm lục địa là sự kéo dài tự nhiên của lục địa ra biển và nguyên lý “đất thống trị biển”",3],["p",85,"● Hội nghị luật biển lần 3",4],["p",85,"- Văn bản cuối cùng của công ước đã được ký vào ngày 10/12/192 tạ Montego - Bay (Jamaica) bởi 117 quốc gia và thực thể (trong đó có VN) bao gồm 17 phần 320 điều khoản.",4],["p",85,"- Công ước có hiệu lực sau 12 tháng kể từ ngày đưa vào lưu chiếu văn bản phê chuẩn hay tham gia thứ 60.",4],["p",85,"- 16/11/1993 Guyana là nước thứ 60 phê chuẩn CƯ do đó CƯ có hiệu lực từ 16/11/1994.",4],["p",85,"- QHVN phê chuẩn ngày 23/6/1994 nộp lưu chiếu LHQ 25/7/1995",4]],"pg":[2,4]},{"h":"2. Khái niệm luật biển","lv":3,"b":[["p",85,"- Là một ngành luật độc lập trong hệ thống pháp luật quốc tế, bao gồm các nguyên tắc, quy phạm pháp lý do chính các chủ thể của luật quốc tế thỏa thuận xây dựng nên nhằm điều chỉnh các quan hệ nảy sinh giữa các chủ thể trong hoạt động khai thác, sử dụng, quản lí và BVMT",4],["p",103,"Nguồn của LBQT",4],["p",72,"Nguồn của Luật biển quốc tế:",4],["p",126,"• Điều ước quốc tế: song phương/đa phương",4],["p",162,"✓ Công ước LHQ về Luật biển 1982",4],["p",85,"⇒ Đóng vai trò vô cùng quan trọng ( gần như là hiến pháp về luật biển)",4],["p",85,"⇒ Vd: các nước asian đều là thành viên công ước 1982, kỳ riêng các điều ước với nhau thì có cần các điều ước đó cao hơn công ước LHQ 1982 hay không hay là thấp hơn? -> nếu không trái nhau thì k đặt ra về hiệu lực, còn nếu trái nhau thì dùng điều ước quốc tế riêng vì bản chất LQT là thỏa thuận , vì đối với thỏa thuận có đặc thù riêng vì thế nên nó không làm suy giảm luật biển 1982.",4],["p",103,"Vd: nguyên tắc công bằng 1982. Nhưung các nước cảm thấy không thấy công bằng khi khai thác tài gnuyeen trước đó nếu chia đều ra thì k công bằng cho nên những trường hợp đuqt song phương, đa phương thì chưa chắc công ước 1982 có hiệu lực cao hơn mà điều ước ký riêgn có thể được cao hơn ( vì ưu tiên tính thỏa thuận giữa các nước hơn)",4],["p",162,"✓ Hiệp định VN-TQN 2000",4],["p",162,"✓ Hiệp định phân định ranh giới trên biển VN-TL",4],["p",126,"• Tập quán quốc tế: được công nhận, được tồn tại, phát sinh trong việc áp dụng công ước 1982 về luật biển tọa ra nhận thức chung thống nhất, hoặc là ...",4],["p",102,"Vd: vùng nước lịch sử công ước không quy định nó chỉ nêu ra nhưng không quy định cụ thể, thì tập quán từ đó dựa vào công ước 1982 thì giai thích để tạo ra nhận thức chung thống nhất",4],["p",126,"• Nguồn bổ trợ khác: phán quyết của trọng tài/tòa án quốc tế; nghị",5],["p",144,"quyết, học thuyết; nghị quyết tổ chứuc liên chính phủ; hành vi",5],["p",144,"đơn phương 1 quốc gia : không có hiệu lực bắt buộc nhưung có",5],["p",144,"giá trị rất quan trọng",5],["p",162,"Vd: án lệ : làm sáng tỏ rất nhiều vấn đề trong luật biển;",5],["p",102,"Nguồn bộ trợ khác với điều ước quốc tế",5],["p",162,"Nếu điều ước tập quán có giá trị bắt buộc: k thực hiện vi",5],["p",126,"phạm",5],["p",162,"Còn nguồn bộ trợ thì có giá trị tham khảo, không thực hiện",5],["p",126,"cũng không sao .nếu thấy hợp lý áp dụng theo , không thì thôi",5],["p",72,"Nguồn của Luật biển Việt Nam",5],["p",126,"• VBQPPL về biển: Luật Biển Việt Nam; Luật Biên giới quốc gia; Luật",5],["p",144,"Tài nguyên, môi tường, biển và hải đảo",5]],"pg":[4,5]},{"h":"III, Các nguyên tắc cơ bản của Luật Biển","lv":2,"b":[],"pg":[5,5]},{"h":"(1) Nguyên tắc đất thống trị biển (The Land dominates the Sea)","lv":3,"b":[["p",90,"- Nội dung nguyên tắc: Chỉ có QG nào có lãnh thổ đất liền tiếp giáp với biển",5],["p",108,"mới được quyền thiết lập các vùng biển thuộc chủ quyền của mình (nội thủy",5],["p",108,"và lãnh hải) và các vùng biển thuộc quyền chủ quyền, quyền tài phán của",5],["p",108,"mình (vùng tiếp giáp lãnh hải, đặc quyền kinh tế, thềm lục địa)",5],["p",90,"- Cspl: Đ 2, Đ76 .",5],["p",126,"Đề cao nước tiếp giáp với biển, nó tiếp giác với biển bao nhiêu thì được",5],["p",90,"hưởng phần biển là bấy nhiêu",5],["p",90,"- Chủ quyền của quốc gia đối với lãnh thổ chi phối chế độ pháp lý của các",5],["p",108,"vùng biển kế cận ( lãnh hải và thêm lục địa)",5],["p",90,"- Lãnh hải: sự mở rộng chủ quyền lãnh thổ đến một vùng biển tiếp liền.",5],["p",126,"Xác định lãnh hải: xác định đường bờ biển, 12 hải lý..",5],["p",90,"- Thềm lục địa đ 76, 77 : sự kéo dài tự nhiên của lãnh thổ đất liền xuống biển",5],["p",126,"Phân chia thềm lục đia: phải dựa vào nguyên tắc này chứ không được",6],["p",90,"chia đều cho các nước",6],["p",126,"Vd: campuchia tiếp giác với đường bờ biển ngắn hơn việt nam thì biển",6],["p",90,"của nó ngắn hơn của vn",6],["p",90,"- Theo Đ 121 UNCLOS về chế độ pháp lý của đảo cũng thuộc nguyên tắc",6],["p",108,"trên.",6],["p",90,"- Là nguyên tắc đặc thù, tức là: xuất phát từ chủ quyền lãnh thổ ở vùng đất",6],["p",108,"tiếp giáp với biển, các quốc gia mới có quyền xác lập các vùng lãnh thổ",6],["p",108,"quốc gia trên biển gồm nội thủy, vùng nước quần đảo và lãnh hải.",6],["p",90,"- Được UNCLOS ghi nhận và cụ thể hóa tại Điều 2 và khoản 1 Điều 76.",6],["p",90,"- Chủ quyền quốc gia đối với các vùng lãnh thổ trên biển sẽ giảm dần khi tiến",6],["p",108,"dần ra ngoài đại dương.",6],["p",90,"- Đối với các quốc gia không có biển thì chỉ được hưởng một số quyền như:",6],["p",126,"✓ Quyền quá cảnh ra biển",6],["p",126,"✓ Quyền đánh bắt cá dư trong vùng đặc quyền kinh tế các quốc gia",6],["p",144,"trong cùng khu vực hoặc ở biển quốc tế, vùng đáy đại dương",6],["p",126,"✓ Các quyền tự do khác",6],["p",126,"- Tự do hàng hải",6],["p",126,"- Tự do hàng không",6],["p",126,"- Đặt dây cáp và ống dẫn ngầm",6],["p",126,"- NCKH về biển (2) Nguyên tắc tự do biển cả ( chỉ áp dụng với biển nằm ngoài giới hạn thẩm quyền tài phán của các nước)",6],["p",85,"● Cspl: Phần VII: biển cả Đ86, 87, 90, 112, 116",6],["p",90,"- Nội dung nguyên tắc:",6],["p",108,"+ Tất cả quốc gia đều có quyền tự do trong việc khai thác và use đối với",6],["p",126,"biển cả vì mục đích hòa bình",6],["p",108,"+ Biển cả được để ngỏ cho tất cả các QG có biển hay không có biển được tự do, bình đẳng khai thác, sử dụng vào các mục đích hòa bình.",6],["p",126,"(Đ 87 UNCLOS 1982)",7],["p",108,"+ Không một quốc gia nào có quyền đưa ra đòi hỏi về chủ quyền đối với",7],["p",126,"biển cả",7],["p",90,"- Lưu ý: mục đích là phải mục đích hòa bình, nếu quốc gia mà chống lại",7],["p",108,"mục đích hòa bình ( ví dụ mang vũ khí, tập trận trên biển quốc tế) thì sẽ vi",7],["p",108,"phạm.",7],["p",90,"- Mọi quốc gia thì đều được khai thác ở đây",7],["p",90,"- Đây là lãnh thỏ chung của tất cả quốc gia, không có biển, có biển, tiếp",7],["p",108,"giáp cũng cso quyền ở đây . họ cũng có quyền đầu tư ở đây, bình đẳng với",7],["p",108,"tất cả các nước, đèeu có chung địa vị pháp lý.",7],["p",126,"Biển cả là lãnh thổ chung của cộng đồng quốc tế -> không một quốc",7],["p",90,"gia nào đưa ra đòi hỏi chủ quyền chung",7],["p",126,"Một tàu thuyền mà nó đi trnee biển quốc tế, nó chịu quyền tài phán của",7],["p",90,"tàu mà nước nó mang quốc tịch",7],["p",126,"Tàu chiến của các nước thì có quyền khám xét truy đuổi mà nó có nghi",7],["p",90,"phạm ( k treo cờ, nghi ngờ bán ma túy, cướp biển)",7],["p",126,"Vd: nhật bản có nhiều tàu ra biển để khai thác cá voi, đánh bắt xa bờ",7],["p",90,"- Là nguyên tắc cổ điển và cơ bản của luật biển quốc tế",7],["p",90,"- Là cơ sở pháp lý",7],["p",126,"✓ Xác định và thiết lập chế độ pháp lý của các vùng biển khác nhau.",7],["p",126,"✓ Giải quyết các vấn đề liên quan đến khai thác tài nguyên thiên nhiên ở",7],["p",144,"thềm lục địa, đáy biển và vùng đặc quyền kinh tế.",7],["p",126,"✓ Điều chỉnh pháp lý với các hoạt động khai thác tài nguyên thiên nhiên",7],["p",144,"ở biển cả và vùng đáy đại dương.",7],["p",102,"(?) Phương tiện hoạt động ngoài vùng biển quốc tế mang quôc stịch của quốc gia có được xem là lãnh thổ di động hay không?",7],["p",102,"Có. Nếu là lãnh thổ di động thì có phải với mọi trg hợp không được quyền",8]],"pg":[5,8]},{"h":"(3) Nguyên tắc bảo vệ và giữ gìn môi trường biển","lv":3,"b":[["p",90,"- Nội dung nguyên tắc: Tất cả các quốc gia có biển và không có biển đều phải",8],["p",108,"có nghĩa vụ bảo vệ và gìn giữ môi trường biển (Đ 192, 193 UNCLOS 1982)",8]],"pg":[8,8]},{"h":"(4) Nguyên tắc công bằng","lv":3,"b":[["p",90,"- Nội dung nguyên tắc: Bảo đảm sự công bằng về quyền và nghĩa vụ giữa các",8],["p",108,"QG trong các quan hệ liên quan đến biển.",8],["p",90,"- Thể hiện trong nhiều quy định của UNCLOS:",8],["p",126,"o Công bằng giữa QG có biển và không có biển",8],["p",126,"o Công bằng trong sử dụng biển quốc tế",8],["p",126,"o Công bằng trong quản lý, khai thác, phân chia tài nguyên của vùng",8],["p",126,"o Công bằng trong phân định biển giữa các quốc gia",8]],"pg":[8,8]},{"h":"(5) Nguyên tắc vùng (đáy đại dương) là di sản chung của nhân loại","lv":3,"b":[["p",102,"Phần vùng: là toàn bộ đáy biển, lòng đát dưới đáy biển dưới đại dương nằm ngoài các vùng biển thuộc quyền tài phán giữa các nước",8],["p",90,"- Nội dung nguyên tắc: Đáy đại dương và tài nguyên thiên nhiên ở đó là di sản",8],["p",108,"chung của tất cả QG, không thuộc quyền sở hữu của bất kỳ QG hay tổ chức",8],["p",108,"quốc tế nào. (Đ 136-142 UNCLOS 1982)",8],["p",90,"- Không một quốc gia nào được quyền đòi hỏi thực hiện chủ quyền hoặc các",8],["p",108,"quyền thuộc chủ quyền đối với vùng hoặc tài nguyên của vùng",8],["p",90,"- Toàn thể loài người ( đại diện là cơ quan quyền lực vùng) là có tất cả các",8],["p",108,"quyền đối với tài nguyên của vùng.",8],["p",90,"- Các hoạt động trong vùng phải được thực hiện vì mục đích của toàn thể loài",8],["p",108,"người.",8],["p",126,"Xác lập chủ quyền chỗ này là vi phạm",8],["p",126,"Mục dích phải được sử dụng lợi ích toàn bộ loại người",8],["p",126,"Việc khai thác phải đảm bảo của toàn bộ loại người",8],["p",126,"Công ước 1982 thành lập ra cơ quan quyền lực vùng, đại diện cho nhân",9],["p",90,"loại, trong việc khai thác, quản lý, sử dụng tài nguyên trong vùng=> Mọi hoạt",9],["p",90,"động trong vùng phải đặt dưới sử quan lý chặt chẽ của cơ quan quyền lực cùng",9],["p",90,"này, hoạt động vì mục đích của toàn thể loại người này.",9],["p",126,"Cơ quan này đặc biệt: chỉ đại diện toàn thể nhân loại, cơ quan chịu trách",9],["p",90,"nhiệm giám sát, quản lý các hoạt động trong vùng",9],["p",85,"● ? Phương tiện hoạt động ngoài vùng biển quốc tế mang quốc tịch của quốc gia có được xem là lãnh thổ di động hay không?",9],["p",85,"ð Có. Nếu là lãnh thổ di động thì có phải với mọi trg hợp không được quyền",9],["t","Luật biển quốc tế và luật hàng hải quốc tế khác nhau ở:",[["","Luật hàng hải","Luật biển"],["Chủ thể","Thương nhân mua bán, vận tải hàng hóa (tính chất tư)","Quan hệ mang tính chất công"],["Quan hệ","Quan hệ hàng hải tư, việc đi lại gắn với hợp đồng ký kết","Quan hệ hàng hải công, tức chỉ có việc đi lại thông thường"],["Phạm vi điều chỉnh","Điều chỉnh về chủ quyền quốc gia và cả việc di chuyển trên tuyến đường biển","Chỉ có việc di chuyển"]]]],"pg":[8,9]}]},{"t":"Chủ quyền","s":"Nội thủy và lãnh hải (đường cơ sở, đi qua không gây hại, tài phán); đảo, quần đảo","pg":"tr.10–24, 56–58","g":[{"h":"Sơ đồ tóm tắt chương","lv":2,"b":[["f","sd_lbmc.svg",720,380,"Mặt cắt các vùng biển từ đường cơ sở ra biển cả (không theo tỷ lệ)"],["f","sd_lb2.svg",720,271,"Sơ đồ: vùng biển thuộc chủ quyền quốc gia"],["p",72,"Sơ đồ tự lập từ bài giảng và UNCLOS 1982, chưa đối chiếu toàn văn.",0]]},{"h":"","lv":0,"b":[["i","lb10_1.jpg",10,1031,610]],"pg":[10,10]},{"h":"1. VÙNG NỘI THỦY","lv":2,"b":[],"pg":[10,10]},{"h":"a. Khái niệm","lv":3,"b":[["p",139,"Nội thủy là vùng nước biển nằm phía trong đường cơ sở, tiếp liền với bờ biển quốc gia ven biển (Điều 8 UNCLOS 1982)",10],["p",139,"Khoản 2 Đ8:",10]],"pg":[10,10]},{"h":"b. Đường cơ sở","lv":3,"b":[["p",85,"● Là cột mốc pháp lý được các quốc gia vạch ra để xác định chiều rộng các vùng biển thuộc chủ quyền và quyền chủ quyền",10],["p",85,"● Có 2 cách xác định đường cơ sở",10],["p",121,"○ Đường cơ sở thông thường: điều 5, 6 UNCLOS 1982",10],["p",157,"■ Đường cơ sở thông thường là ngấn nước thủy triều xuống thấp nhất dọc theo bờ biển của quốc gia ven biển (5)",10],["p",157,"■ Đường cơ sở thông thường ở các đảo bằng san hô hoặc có đá ngầm ven bờ bao quanh là ngấn nước thủy triều xuống thấp nhất ở bờ phía ngoài của các mỏm đá (6)",10],["p",157,"■ Cách xác định dễ nhưng có nhiều nhược điểm",10],["p",121,"○ Đường cơ sở thẳng: Điều 7 UNCLOS 1982",10],["p",157,"■ Được áp dụng đầu tiên bởi Na Uy, từ vụ ngư trường Anh Na Uy",10],["p",108,"Ở nơi nào bờ biển bị khoét sâu và lồi lõm (từ 3 vùng lõm sâu trở lên lõm sâu rõ rệt thì CD phải bằng một nửa AB. trong đó AB là đoạn nối giữa 2 điểm thủy triều xuống thấp nhất.",10],["p",73,"CD là đường thẳng vuông góc nỗi từ đường thằng AB đến điểm sát nhất của thủy triều) hoặc nếu có một chuỗi đảo nằm sát ngay và chạy dọc theo bờ biển (từ 24 hải lý trở xuống nếu đảo cách nhau, nếu có từ 3 đảo trở lên, cách bờ từ 24 hải lý trở xuống), phương pháp đường cơ sở thẳng nối liền các điểm thích hợp có thể được sử dụng để kẻ đường cơ sở dùng để tính chiều",10],["i","lb11_1.jpg",11,1093,1043],["p",73,"rộng lãnh hải.",11],["p",85,"● Tùy thuộc vào đặc điểm bờ biển của các vùng, có giá trị pháp lí như nhau",11],["p",121,"○ Thông thường: dễ xác định, phản ánh chính xác hình dạng của bờ biển nhưng các quốc gia không mở rộng đc phần nội thủy, dựa vào ngấn nước thủy triều xuống thấp nhất là dựa vào quốc gia tự tuyên bố cho nên k có sự kiểm soát về tính chính xác và trung thực.",11],["p",121,"○ Thẳng: 3 trường hợp được áp dụng (bờ biển bị khoét sâu và lồi lõm / có một chuỗi đảo nằm sát và chạy dọc theo bờ biển / bờ biển cực kì không ổn định khi có sự hiện diện của các châu thổ)",11],["p",98,"“Khoét sâu và lồi lõm”: tức là có 3 vùng lõm sâu trở lên, các vùng lõm k được cách quá xa (khoảng cách giữa chiều sâu của vùng lõm đó phải bằng ít nhất ½ khoảng cách giữa hai điểm nhô ra)",11],["p",101,"“Chuỗi đảo” phải có từ 3 đảo trở lên, các đảo không được xa bờ quá 24 hải lý, các đảo k được cách nhau quá 24 hải lý và các đảo chắn ít nhất 50% đường bờ biển đi qua. Đảo nào k đáp ứng đủ điều kiện thì có đường cơ sở riêng do quốc gia có chủ quyền xác định.",11],["p",120,"Lưu ý K6 Đ7 UNCLOS",11],["p",139,"o Đường cơ sở của VN chỉ xác định được đến đến Cồn Cỏ, từ Cổn Cỏ kéo về phía bắc thì k đc xác định vì đã có đường phân định rõ với TQ.",11],["p",85,"● Đường cơ sở của quần đảo",12],["p",103,"Một quốc gia quần đảo có thể vạch các đường cơ sở thẳng của quần đảo nối liền các điểm ngoài cùng của các đảo xa nhất và các bãi đá lúc chìm lúc nổi của quần đảo (trừ khi trên đó có công trình luôn luôn nhô cao hơn mặt nước biển), với điều kiện là tuyến các đường cơ sở này bao lấy các đảo chủ yếu và xác lập một khu vực mà tỷ lệ diện tích nước đó với đất, kể cả vành đai san hô, phải ở giữa tỷ lệ số 1/1 và 9/1.",12],["p",103,"Vd : như là có thể 1 phần nước, 1 phần đất nhưng nhiều nhất thì 9 phần nước phải có 1 phần đất chứ không thể nào nhiều hơn (kiểu như 15 phần nước, 1 phần đất)",12],["p",103,"Người ta gọi đấy là vùng nước quần đảo chứ k gọi là nội thủy, và nó khác nhau kiểu nó có đường bờ biển quốc tế, vẫn có thể tự do ra vào được",12],["p",103,"Nếu có 1 đảo nhỏ mà nối lại được thì cái trong đấy mới gọi là nội thủy, bên ngoài vẫn là vùng nước quần đảo.",12],["p",103,"Ủy ban quốc tế giải thích về",12],["p",139,"- Đ47 UNCLOS: Tỷ lệ giữa nước với đất là 1/1 hoặc 9/1 (vd diện tích là 100km2 thì có ít nhất 50km2 nước và 50km2 đất hoặc 90km2 và 10km2 đất)",12],["i","lb12_1.jpg",12,811,627],["p",139,"- Bên trong đường cơ sở bao quanh các đảo được gọi là vùng nước quần đảo. Tàu thuyền đi qua không cần xin phép vì nó k phải là nội thủy mà đi qua không gây hại là được.",12],["p",139,"- Nếu bên trong có đảo hình bán nguyệt thì đảo đó có quyền vẽ vùng nội thủy của riêng nó theo Đ50 UNCLOS.",12],["q",102,"ĐIỀU 50. Hoạch định ranh giới nội thủy",12],["p",102,"Ở phía trong vùng nước quần đảo, quốc gia quần đảo có thể vạch những đường khép kín để hoạch định ranh giới nội thủy của mình theo đúng các Điều 9, 10, và 11.",12],["i","lb13_1.jpg",13,862,1472],["p",85,"● Xác định đường cơ sở khi có hoàn cảnh đặc biệt",13],["p",121,"○ Cửa sông Đ9 UNCLOS",13],["p",157,"■ Nếu một con sông đổ ra biển mà không tạo thành vụng thì đường cơ sở là một đường thẳng được kẻ ngay qua cửa sông nối liền các điểm ngoài cùng của ngấn nước triều thấp nhất ở hai bên bờ sông.",13],["p",157,"■ Như kiểu, con sông ra biển thì nó sẽ có 2 cái bờ, thì mình sẽ xác định đường cơ sở là đường nhô ra xa nhất của 2 bên bờ sông, để khép cái bờ sông lại.",13],["p",121,"○ Vịnh Đ10 UNCLOS",13],["p",157,"■ (đường cơ sở từ bờ bên này đến bờ bên kia không quá 24 hải lý, chiều sâu của vùng lõm để tạo thành vịnh được quy định theo UNCLOS và luật biển)",13],["p",157,"■ Trong Công ước, “Vịnh” (baie) cần được hiểu là một vùng lõm sâu rõ rệt vào đất liền mà chiều sâu của vùng lõm đó so sánh với chiều rộng ở ngoài cửa của nó đến mức là nước của vùng lõm đó được bờ biển bao quanh và vùng đó lõm sâu hơn là một sự uốn cong của bờ biển. Tuy nhiên, một vũng lõm chỉ được coi là một vịnh nếu như diện tích của nó ít nhất cũng bằng diện tích một nửa hình tròn có đường kính là đường thẳng kẻ ngang qua cửa vào của vùng lõm.",13],["p",157,"■ Nếu khoảng cách giữa các ngấn nước triều thấp nhất ở các điểm của cửa vào tự nhiên một vịnh không vượt quá 24 hải lý, thì đường phân giới có thể được vạch giữa hai ngấn nước triều thấp nhất này và vùng nước ở phía bên trong đường đó được coi là nội thủy.",13],["p",157,"■ Khi khoảng cách giữa các ngấn nước triều thấp nhất ở các điểm của cửa vào tự nhiên của một vịnh vượt quá 24 hải lý, thì được kẻ một đoạn đường cơ sở thẳng dài 24 hải lý ở phía trong vịnh, sao cho phía trong của nó có một diện tích nước tối đa.",13],["i","lb14_1.jpg",14,1096,1024],["p",157,"■ Nói chung thì vịnh nhỏ thì lấy hết, còn vịnh lớn thì chỉ lấy 24 hải lý thôi Vịnh lịch sử thì được lấy hết",14],["p",121,"○ Vịnh lịch sử",14],["p",157,"■ Trong đó vịnh lịch sử thì nó là vùng biển có cấu tạo địa lý đặc biệt, ăn sâu vào đất liền hoặc là 1 bộ phận gắn liền với lục địa, và nó ở cách xa tuyến đường hàng hải quốc tế, nó phải",14],["p",193,"● có ý nghĩa vai trò quan trọng về chiến lược, quốc phòng, an ninh, kinh tế,...",14],["p",193,"● đối với quốc gia ven biển (kiểu như là từ đó tới giờ họ đánh cá ở đấy hay chỗ này từ lâu đã thành lập khu thủy quân, lắp đặt vũ khí để đảm bảo an ninh quốc phòng.",14],["p",193,"● Cuối cùng về mặt lịch sử, quốc gia ven biển đã chiếm hữu, khai thác, use từ lâu đời mà k có nước nào phản đối",14],["p",157,"■ Đường cơ sở vịnh lịch sử: khoản 5 Điều 7: “Trong những trường hợp mà phương pháp kẻ đường cơ sở thẳng được áp dụng theo khoản 1, khi ấn định một số đoạn đường cơ sở có thể tính đến những lợi ích kinh tế riêng biệt của khu vực đó mà thực tế và tầm quan trọng của nó đã được một quá trình sử dụng lâu dài chứng minh rõ ràng.”",14],["p",121,"○ Cảng biển",14],["p",157,"■ Điều 11 UNCLOS 1982: Để ấn định ranh giới lãnh hải, các công trình thiết bị thường xuyên là bộ phận hữu cơ của một hệ thống cảng, nhô ra ngoài khơi xa nhất, được coi là thành phần của bờ biển. Các công trình thiết bị ở ngoài khơi xa bờ biển và các đảo nhân tạo không được coi là những công trình thiết bị cảng thường xuyên.",14],["p",157,"■ Nếu có bộ phận không nối trực tiếp với cảng thì không không được nối để tạo thành đường cơ sở",14],["i","lb15_1.jpg",15,1096,1094],["p",157,"■ (Nếu có cảng biển thì đường cơ sở có thể kéo dài hết cảng biển và được coi như là bộ phận hữu cơ của bờ biển, còn nếu k có cảng biển thì thôi.)",15],["p",121,"○ Vũng đậu tàu",15],["p",157,"■ Các vũng tàu được dùng thường xuyên vào việc xếp dỡ hàng hóa và làm khu neo tàu, bình thường nằm hoàn toàn hoặc một phần ở ngoài đường ranh giới bên ngoài của lãnh hải cũng được coi như là bộ phận của lãnh hải.",15],["p",157,"■ Nó không được vẽ đường cơ sở vào đấy Aka: Khu neo đậu tàu thuyền cx đc coi là công trình phục vụ cảng biển nhưng vẫn k đc coi là bộ phận thường xuyên của cảng và không được vẽ đường cơ sở bao luôn chỗ đậu của tàu thuyền ấy. K được coi là 1 vùng biển.",15],["p",121,"○ Bãi cạn lúc nổi lúc chìm (Điều 13)",15],["p",157,"■ “Bãi cạn lúc chìm lúc nổi” (haut-fonds découvrants) là những vùng đất nhô cao tự nhiên có biển bao quanh, khi thủy triều xuống thấp thì lộ ra, khi thủy triều lên cao thì bị ngập nước. Khi toàn bộ hay một phần bãi cạn đó ở cách lục địa hoặc một đảo một khoảng cách không vượt quá chiều rộng của lãnh hải, thì ngấn nước triều thấp nhất ở trên các bãi cạn này có thể được dùng làm đường cơ sở để tính chiều rộng của lãnh hải.( là vùng đất, công trình… nhô cao lên mặt nước biển, khi thủy triểu xuống thấp nhất thì lộ ra nhưng khi thủy triều lên cao thì bị ngập nước)",15],["p",157,"■ Khi các bãi cạn lúc chìm lúc nổi hoàn toàn ở cách lục địa hoặc một đảo một khoảng cách vượt quá chiều rộng của lãnh hải, thì chung không có lãnh hải riêng.",15],["p",157,"■ => không được xem là đường cơ sở trừ khi trên đó xây dựng 1 công trình thường xuyên nhô cao khỏi mặt nước biển (có thể là bất kỳ công trình gì, vd như hải đăng, đài quan sát, nhà giàn, etc.)",15],["p",85,"● Quy chế pháp lý của nội thủy",16],["p",121,"○ Tính chất chủ quyền Vùng nội thủy thuộc chủ quyền hoàn toàn, tuyệt đổi của quốc gia ven biển Mọi tàu thuyền muốn vào nội thủy đều phải xin phép trước (trừ 1 số trường hợp đặc biệt",16],["p",72,"trừ những trường hợp bất khả kháng như tàu găp các sự cố nghiêm trọng về kỹ thuât",16],["p",72,"không thể tiếp tục được hành trình hoăc các lý do ṿ ề thiên tai (đông đất, sóng thần,",16],["p",72,"bão, lốc...), hoăc các lý do nhân đạo (như cứu người bị bênh nan ỵ , cứu tàu thuyền",16],["p",72,"hoăc thủy đoàn của tàu khác gă p̣ nạn trên biển..) thì chỉ cần thông báo trước khi ṿ ào",16],["p",72,"nôi thủy.( k2 đ 27 NĐ 104/2012",16],["p",85,"- Mỗi tàu thuyền khác nhau thì đều có quy chế pháp lý khác nhau",16],["p",85,"- Phạm vi chủ quyền: Bao trùm cả lớp nước biển trong lòng đất dưới đáy biển và",16],["p",103,"vùng trời trên nội thủy",16],["p",85,"- Cơ sở pháp luật chủ yếu để thực thi chủ quyền: theo quy định của pháp luật quốc",16],["p",103,"gia ven biển phù hợp với luật quốc tế",16],["p",121,"○ Phân loại tàu thuyền",16],["i","lb16_1.jpg",16,1093,505],["p",85,"➢ Tàu dân sự",16],["p",121,"○ tàu dân sự nhà nước",16],["p",157,"■ tàu nhà nước mục đích thương mại (áp dụng giống như tàu dân sự tư nhân)",16],["p",157,"■ tàu nhà nước mục đích phi thương mại (thăm dò, thám hiểm, khai phá, thậm chí là tàu chiến…)",16],["p",121,"○ tàu dân sự tư nhân",16],["p",85,"➢ Tàu quân sự (Đ29 UNCLOS): được coi như quốc gia di động, sĩ quan hải quân chỉ huy được nằm trong danh sách chính thức của quân đội … có dáng vẻ đặc trưng",17],["p",85,"★ Quy chế của tàu quân sự",17],["p",121,"● Tàu quân sự được hưởng quyền bất khả xâm phạm và miễn trừ tuyệt đối về tư pháp trong nội thủy của quốc gia ven biển. ( Đ32 UNCLOUS)",17],["p",121,"● Trường hợp tàu quân sự nước ngoài vi phạm pháp luật quốc gia ven biển: điều 30 UNCLOUS, Đ 28 lb",17],["q",151,"ĐIỀU 30. Tàu chiến không tuân thủ các luật và quy định của quốc gia ven biển",17],["p",151,"Nếu một tàu chiến không tôn trọng các luật và quy định của quốc gia ven biển có liên quan đến việc đi qua trong lãnh hải và bất chấp yêu cầu phải tuân thủ các luật và quy định đó đã được thông báo cho họ, thì quốc gia ven biển có thể đòi chiếc tàu đó rời khỏi lãnh hải ngay lập tức.",17],["p",121,"● Trách nhiệm của quốc gia mà tàu quân sự vi phạm: Điều 31 của công ước",17],["q",151,"ĐIỀU 31. Trách nhiệm của quốc gia mà tàu mang cờ đối với hành động của một tàu chiến hay một tàu khác của Nhà nước",17],["p",151,"Quốc gia mà tàu mang cờ chịu trách nhiệm quốc tế về mọi tổn thất hoặc về mọi thiệt hại gây ra cho quốc gia ven biển do một tàu chiến hay bất kỳ tàu thuyền nào khác của Nhà nước dùng vào những mục đích không thương mại vi phạm các luật và quy định của quốc gia ven biển có liên quan đến việc đi qua lãnh hải hay vi phạm các quy định của Công ước hoặc các quy tắc khác của pháp luật quốc tế.",17],["p",94,"○ Quyền bất khả xâm phạm: có nghĩa là trong mọi trường hợp không được kiểm tra khám xét tàu quân sự",17],["p",94,"○ Miễn trừ tuyệt đối về tư pháp: có nghĩa là con tàu này có những hành vi vi phạm pl của nước ven biển cũng k thể bắt giữ, xét xử, bắt giam con tàu này (vd như tàu này đâm vào tàu dân sự => nếu chủ tàu cá có khởi kiện thì Tòa không thể thụ lý vụ án này) Nếu thủy thủ ra khỏi tàu và vi phạm pháp luật ở nước họ đặt chân tới, thì vẫn có thể bắt giữ, bắt giam và xử lý được Nếu họ vi phạm trên đất liền và họ chạy được lên tàu rồi thì sẽ không được bắt giữ và xử lý được",17],["p",94,"○ Có thể giải quyết bằng con đường ngoại giao bằng những phương pháp:",17],["p",94,"■ Có thể trục xuất con tàu đấy",17],["p",148,"■ Có thể yêu cầu quốc gian của con tàu đó bồi thường nếu có",17],["p",148,"■ Có thể yêu cầu quốc gia áp dụng chế tài đối với thủy thủ vi phạm ★ Quyền tài phán của quốc gia ven biển đối với tàu dân sự Giống như trên lãnh thổ đất liền của quốc gia (Nếu người trên tàu bị vi phạm thì vẫn bắt giam bắt giữ bình thường). Các tàu nước ngoài đến đây đều phải thực hiện pháp luật của quốc gia họ đến Nội thủy phải xin phép trước, vì lý do nhân đạo thì vừa đi vừa xin phép cx được vd như rủi ro thiên tai, gặp tai nạn ( k2 đ 27 NĐ 104/2012) Quyền tài phán Quyền tài phán dân sự : giống như trên lãnh thổ đất liên của quốc gia ( giống như người nước ngoài vi phạm trên đất liền)",18],["p",102,"Quyền tài phán hành chính",18],["p",64,"- Nghị định 162/2013/ND-CP quy định về xử phạt vi phạm hành chính trên các vùng biển, đảo và thềm lục địa… Quyền tài phán hình sự",18],["p",64,"- Tàu dân sự mục đích thương mại không được hưởng quyền miễn trừ như tàu quân sự. Cơ quan nhà nước có thẩm quyền của quốc gia ven biển có quyền khởi tố, điều tra, truy tố, xét xử các cá nhân có hành vi phạm tội trên tàu.",18],["p",64,"- Quyền bảo vệ của quốc gia ven biển: khoản 2 Điều 25 UNCLOS 1982",18],["p",64,"- Quyền hạn của các quốc gia có cảng: Điều 218 UNCLOS 1982",18],["p",64,"- Khoản 1 Điều 30 Luật Biển 2012",18],["p",102,"Ngoại lệ",18],["p",72,"Theo khoản 2 Điều 8 UNCLOS, có những vùng nội thủy mà tàu thuyền nước ngoài",18],["p",72,"được quyền đi qua không gây hại mà không cần xin phép. Đó là những vùng biển",18],["p",72,"mà trước đây chưa được coi là, nay do phương pháp vạch ĐCS thẳng mà trở thành",18],["p",72,"vùng nội thủy của quốc gia ven biển. Quy định này bảo vệ quyền và lợi ích chính",18],["p",72,"đáng của tàu thuyền nước ngoài.",18]],"pg":[10,18]},{"h":"2. VÙNG LÃNH HẢI","lv":2,"b":[],"pg":[18,18]},{"h":"2.1. Khái niệm","lv":3,"b":[["p",102,"Lãnh hải là vùng biển nằm phía ngoài nội thủy, có chiều rộng tối đa 12 hải lý tính từ đường cơ sở (điều 3 UNCLOS 1982)",18],["q",108,"ĐIỀU 3. Chiều rộng của lãnh hải",18],["p",108,"Mọi quốc gia đều có quyền ấn định chiều rộng lãnh hải của mình; chiều rộng này không vượt quá 12 hải lý kể từ đường cơ sở được vạch ra theo đúng Công ước.",18],["i","lb19_1.jpg",19,1039,506],["p",103,"2.2. Quy chế pháp lý: lãnh hải và nội thủy là 2 vùng biển thuộc chủ quyền của quốc gia ven biển. chủ quyền quốc gia của quốc gia đối với lãnh hải tương tự đối với nội thủy. 1) Quyền đi qua không gây hại của tàu thuyền nước ngoài",19],["p",121,"○ Tàu thuyền của tất cả các quốc gia có biển hay không có biển đều được quyền đi qua không gây hại trong lãnh hải",19],["q",128,"ĐIỀU 17. Quyền đi qua không gây hại",19],["p",128,"Với điều kiện phải chấp hành Công ước, tàu thuyền của tất cả các quốc gia, có biển hay không có biển, đều được hưởng quyền đi qua không gây hại trong lãnh hải.",19],["p",108,"Theo Điều 17 CU 1982 thì tàu thuyền các quốc gia có biển hay không có biển thì đều có quyền đi qua không qua không gây hại trong lãnh hải",19],["p",108,"Mở rộng ở tất cả các quốc gia ( không cần xin phép, không cần thủ tục hải quan xuất nhập cách)",19],["p",108,"Đi qua không gây hại: chỉ dùng để đi qua lại: phục vụ cho việc đi lại của ngành vận tại thôi, còn các hoạt động khác thì không được coi là đi qua không gây hại trừ bất khả kháng)",19],["p",102,"Bản chất của “đi qua không gây hại” (Passage inoffensif) => không xâm phạm đến trật tự, hòa bình, an ninh quốc gia ven biển (nó chỉ hoàn toàn phục vụ thuần túy cho việc đi lại thôi, là đi qua liên tục không dừng lại trừ các trường hợp bất khả kháng như tàu bị trục trặc hoặc cứu hộ, trong điều 19 có ghi “Mọi hoạt động khác không trực tiếp quan hệ đến việc đi qua” đều được coi là đi qua gây hại)",19],["p",64,"- Bản chất: không gây hại: theo quy định công ước: không xâm phạm trật tự, an ninh, hòa bình, quốc gia ven biển. việc đi lại chỉ thuần túy trong việc đi lại mà thôi chứ không đòi hỏi về quyền chủ quyền. đi qua liên tục, không dừng lại, nhanh chóng trừ tường ợp bất khả kháng ( cứu hộ, cứu nạn) . trong quá trình đi qua không có bất ký hành động nào gây ra ảnh hưởng đến quốc gia ven biển ( vd: Đ19; Giuơng lên bất ký thiết bị lạ ( có quyền yêu cầu giải thích -> nếu không giải thích được việc giương thiết bị này thì có quyền tịch thu)",19],["p",64,"- Vùng trờ phía trên lãnh hải : là của vùng trời quốc gia ( hoàn toàn tuyệt đối ) nên nếu muốn bay vào thì phải xin phép quốc gia . : không tồn tại đi qua không gây hại",20],["p",103,"Tàu ngầm cũng được quyền đi qua không gây hại trong trường hợp đi qua trong tư thế nổi và có cờ của quốc gia của nó",20],["q",108,"ĐIỀU 20. Tàu ngầm và các phương tiện đi ngầm khác",20],["p",108,"Ở trong lãnh hải, tàu ngầm và các phương tiện đi ngầm khác buộc phải đi nổi và phải treo cờ quốc tịch.",20],["p",67,"Điều 23 UNCLOUS: Tàu chở chất thải, chất phóng xạ thì sẽ được kiểm tra trước xem có đảm bảo hay không (mang theo các tài liệu cần thiết để có thể trình ngay cho quốc gia đó) và có tất cả các biện pháp để có thể ngăn chặn nếu xảy ra trường hợp không mong muốn.",20],["p",108,"Tàu chở chất phóng xạ, hạt nhân,….. ( mang tất cả tài liệu giấy tờ về chất phóng xạ, hạt nhân + hoạt động kiểm tra giám sát tàu….) => nếu nước ven biển cảm thấy chưa thực hiện việc kiểm tra thì có quyền từ chối cho tàu đi qua lại",20],["p",103,"Và chỉ được đi trong tuyến đường đã được bố trí phân luồng.",20],["q",73,"ĐIỀU 22. Các tuyến đường và cách bố trí phân chia luồng giao thông ở trong lãnh hải 2. Đặc biệt, đối với các tàu xi-teec (navires-citernes), các tàu có động cơ chạy bằng năng lượng hại nhân và các tàu chở các chất hay các nguyên liệu phóng xạ hoặc các chất khác vốn nguy hiểm hay độc hại, có thể bị bắt buộc chỉ được đi theo các tuyến đường này.",20],["p",102,"Đối tượng được hưởng quyền đi qua không gây hại?",20],["p",67,"Tất cả các loại tàu, mọi loài tàu đều được đi qua Nhưng trên thực tế , chia ra 3 trường hợp đối với tàu quân sự tùy vào từng nước :",20],["p",85,"● Được đi qua",20],["p",85,"● Hạn chế, không cho qua",20],["p",85,"● Yêu cầu, thông báo trước muốn vào phải xin phép. ví dụ như Trung Quốc => lý giải của các nước này thường là các tàu quân sự bản thân nó đã đe dọa hòa bình an ninh quốc gia nên nó đã trái với bản chất của luật này => nó phải ở nhóm khác. Ở Việt Nam thì phải được thông báo trước.",20],["p",102,"Bổ sung, lưu ý: Theo Công ước 1982, trong vùng lãnh hải, tàu thuyền được phép đi qua không gây hại, bao gồm cả tàu quân sự, tuy nhiên, tàu ngầm phải đi ở tư thế nổi và có cờ quốc gia. Sở dĩ phải đi nổi bởi vì đây là quyền đi qua không gây hại ở đây được hiểu là quyền đi qua không gây hại trên mặt nước Tàu xi – teec (navires-citernes), các tàu chạy bằng động cơ năng lượng hạt nhân và các tàu chở các chất hay các nguyên liệu phóng xạ hoặc các chất khác vốn có nguy hiểm hay động hại có thể bị bắt buộc di chuyển theo tuyến đường nhất định để đảm bảo an ninh cho quốc gia ven biển. Tuy nhiên, theo quy định của pháp luật Việt Nam, tàu quân sự nước ngoài phải thông báo cho cơ quan có thẩm quyền của Việt Nam trước khi thực hiện quyền đi qua không gây hại.",20],["p",67,"Suy ra, các phương tiện được đi qua không gây ở bộ phận nào của lãnh hải? => trên bề mặt nước biển của lãnh hải Chỉ được đi theo bề mặt nước biển của lãnh hải ( không được đi lại lung tung trên đó ) mà nước vne biển sẽ phân luồn hàng hải và tùa thuyền sẽ đi theo tuyến hàng hải cố định ( phao số bao nhiêu, )( tuyến đường ngắn nhất, an toàn nhất và dễ dàng kiểm soát nhất) => vì lãnh hải rất rộng, không thể kiểm soát được Không được lên vùng trời hoặc đáy biển phía dưới Quốc gia ven biển được quyền phân luồng hàng hải để các tàu đi theo (hướng dẫn hướng đi của tàu thuyền)",21],["p",67,"Đi qua không gây hải chỉ mang tính biển ? -> ( đúng ) vì chỉ đi trên bề mặt nước biển Khoản 1 Điều 22:",21],["p",108,"1. Quốc gia ven biển khi cần bảo đảm an toàn hàng hải có thể đòi hỏi tàu thuyền nước ngoài đi qua không gây hại trong lãnh hải của mình phải đi theo các tuyến đường do mình ấn định và phải tôn trọng các cách bố trí phân chia các luồng giao thông do mình quy định nhằm điều phối việc qua lại các tàu thuyền.",21],["p",102,"Phạm vi được hưởng quyền đi qua không gây hại: Đ19 Nếu trong điều 19 -> đầy là hành vi gây hại.",21],["p",67,"Điều 25: tạm thời đình chỉ không gây hại ( có thời điểm bắt đầu và kết thúc của lệnh tạm đình chỉ này )",21],["p",67,"Đình chỉ: phải bình đẳng, nếu lý do để đình chỉ tàu nước này thì lý do đó cũng phải đình chỉ cho tàu nước khác ( k3 đ 25UNCLOUS) 2) Quyền tài phán của nước ven biển",21],["p",102,"UNCLOUS phân chia tàu biển thành 2 loại",21],["p",64,"- Tàu chiến ( Đ29 UNCLOUS) và tàu nhà nước sử dụng mục đích phi thương mại",21],["p",64,"- Tàu nhà nước sử dụng mục đích thương mại và tàu thương mại của tư nhân Quốc gia ven biển có quyền tài phán đối với tàu không?",21],["p",103,"Tàu quân sự, tàu nhà nước phi thương mại được hưởng quyền bất khả xâm phạm và miễn trừ tuyệt đối về tư pháp. Mọi mâu thuẫn sẽ được giải quyết bằng con đường ngoại giao.",21],["q",108,"ĐIỀU 32. Các quyền miễn trừ của các tàu chiến và các tàu khác của Nhà nước dùng vào những mục đích không thương mại",22],["p",108,"Ngoài những ngoại lệ đã nêu ở Tiểu mục A và ở các Điều 30 và 31, không một quy định nào của Công ước đụng chạm đến các quyền miễn trừ mà các tàu chiến và các tàu khác của Nhà nước dùng vào những mục đích không thương mại được hưởng.",22],["p",103,"Quốc gia ven biển có quyền tài phán hình sự dân sự đối với các tàu dân sự, tàu nhà nước use vào mục đích thương mại tùy thuộc vào từng trường hợp qua lại của tàu thuyền tại lãnh hải Các hoạt động quản lý duy trì trật tự trong lãnh hải, quyền tài phán hành chính thì quốc gia ven biển sẽ đương nhiên có quyền",22],["p",102,"Quyền tài phán hình sự. Đ27 ( D30 LB)",22],["p",102,"Gạch chân K2 “đi qua lãnh hải, sau khi rời khỏi nội thủy”",22],["p",102,"Gạch chân K1 “đi qua lãnh hải”",22],["p",102,"Có 3 trường hợp tàu thuyền đi qua lãnh hải:",22],["p",85,"● Từ nội thủy đi qua lãnh hải để ra ngoài ( từ trong ra ngoài) => khoản 2 Đ27 : nội thủy ra lãnh hải rồi tiếp tục ra ngoài : quyền tài phán tuyệt đối ( từ trong ra ngoài)",22],["p",121,"○ Tàu đi qua lãnh hải sau khi rời khỏi nội thủy, vi phạm hình sự xảy ra ở lãnh hải => Có quyền giống như trên đất liền",22],["p",121,"○ Quốc gia được toàn quyền xử lý",22],["p",108,"Vd: đang trên lãnh hải mà thủy thủ trên tàu vi phạm thì quốc gia có toàn quyền xử lý ( áp dụng nhưu trên nội thủy, đất liên) => quyền tìa phán trọn ven và phải thông báo quốc gia mà thủy thủ, con tàu mang quốc tịch",22],["p",85,"● Từ ngoài đi qua lãnh hải để vào hoặc không vào nội thủy ( ngoài vào trong) => khoản 1 đ27",22],["p",121,"○ Tàu đi qua lãnh hải để vào hoặc không vào nội thủy, vi phạm hình sự xảy ra trong lãnh hải => có quyền tài phán trong 4 trường hợp:",22],["p",157,"■ Nếu hậu quả của vụ vi phạm đó mở rộng đến quốc gia ven biển;",22],["p",193,"● Vd như thủy thủ xô xát đánh nhau trên tàu thì nước ven biển đất không có quyền xử lý, nhưng nếu thủy thủ đó tách ra và chạy trốn bằng ca nô thì quốc gia ven biển có quyền bắt giữ (nếu không chứng minh thì không có quyền can thiệp)",22],["p",193,"● Vd: tàu nước ngoài đang đi trên tàu lãnh hải, 2 thủy thủ thực hiện hành vi cố ý gây thương tích, giết người nếu hành động này xảy ra trên nội bộ con tàu thì nước ven biển biết thì cũng k xử lý ; nêu shậu quả gây ra ảnh hưởng tới bên ngoài ( giết người vứt xác xuống biển, .. ) ảnh huyơngr ra bên ngoài thì ngước ven biển có quyền xư rlý",22],["p",193,"● Hoặc là sau khi thực hiện hành vi phạm tội nhưung tách ca nô để chạy thoát tội thì quốc gia ven biển có quyền tía phán",23],["p",193,"● Phải chứng minh hành vi phạm tội có hậu quả ảnh hưởng đến bên ngoài, mở rộng ra bên ngoài tàu",23],["p",157,"■ Nếu vị vi phạm có tính chất phá hoại hòa bình của đất nước hay trật tự trong lãnh hải;",23],["p",193,"● Nếu có các hành vi gây hại được quy định tại điều 19 thì được quyền tài phán",23],["p",157,"■ Nếu thuyền trưởng hay một viên chức ngoại giao hoặc một viên chức lãnh sự của quốc gia mà tàu mang cờ yêu cầu sự giúp đỡ của các nhà đương cục địa phương hoặc",23],["p",193,"● Vd: Nếu thuyền trưởng phát tính hiệu yêu cầu chính thức thì cảnh sát biển sẽ can thiệp",23],["p",193,"● Vd: nếu 2 thủy thủ ẩu đả, giết người trên tàu thuyền thì nếu thuyền trưởng phát tín hiệu cấp cứu thì tàu địa phương có quyền bắt giữ, tạm giam, tạm giữ (nếu k phát tín hiệu thì k có quyền tài phán) hoặc trường hợp cướp biển, cướp tàu trên biển và cơ quan địa phương nước ven biển được báo tín , thì nếu nước ven biển bắt được thì sẽ có quyền xử lý",23],["p",157,"■ Nếu các biện pháp này là cần thiết để trấn áp việc buôn lậu chất ma túy hay các chất kích thích.",23],["p",102,"Ngoài 4 trường hợp này ra thì nước con tàu mang quốc tịch xử lý ( có quyền tài phán)",23],["p",85,"● Đi ngang qua lãnh hải mà không qua nội thủy => các khoản còn lại",23],["p",121,"○ Tàu đi qua lãnh hải vào nội thủy , mà hành vi vi phạm không xảy ra ở lãnh hải => có thể bắt giữ và dẫn độ, hoặc lờ đi không biết",23],["p",121,"○ Tàu đi qua lãnh hải nhưng không vào nội thủy , mà hành vi vi phạm không xảy ra ở lãnh hải => không có quyền tài phán",23],["p",102,"Quyền tài phán dân sự Quyền tài phán về dân sự (Điều 28 UNCLOS) (Điều 31 Luật Biển Việt Nam)",23],["p",103,"Quốc gia chỉ có quyền tài phán dân sự đối với các Tàu đi qua lãnh hải sua khi rời khỏi nội thủy hoặc đang đậu trên lãnh hải Chỉ trường hợp này tòa án nước ven biển mới được quyền tài phán",23],["p",102,"Note: Quốc gia ven biển không được bắt một tàu nước ngoài đang đi qua lãnh hải phải dừng lại hay thay đổi hành trình của nó để thực hiện quyền tài phán dân sự của mình đối với một người ở trên con tàu đó. ( k1 đ28)",24],["p",108,"Vd: có vụ kiện giữa thủy thủ với người của nước ven biển mà tòa án của nước đó đang thụ lý giải quyết, nhiều lần triệu tập nhưng họ không đến thì tòa không thể cản trở con tàu đó để giải quyết vụ việc được, không được ảnh hưởng tới hành trình của con tàu",24],["p",111,"Vấn đề triệu tập thủy thủ: gửi theo con đường bihf thường, và thủy thủ có đến hay không. Chứ không có quyền bắt dừng lại hoặc thay đổi hành trình của con tàu",24]],"pg":[18,24]},{"h":"THỰC THỂ ĐẶC BIỆT TRÊN BIỂN","lv":2,"b":[],"pg":[56,56]},{"h":"1. ĐẢO VÀ QUẦN ĐẢO","lv":3,"b":[["p",103,"ĐẢO Điều 121 Đảo: là một vùng đất tự nhiên có nước bao bọc, khi thủy triều lên vùng đất này vẫn ở trên mặt nước.",56],["p",72,"Chế độ pháp lý: Điều 121 Đảo thì phải thường xuyên nhô cao hơn mặt nước. Bản chất của đảo là vùng đất, lãnh thổ vùng đất của quốc gia ( kể cả nó được cấu tạo bằng đá) . nhưng đảo lại có quan hệ mất thiết trong vùng biển . công ước 1982 không có quy định0 xác lập chủ quyền đối với các đảo mà chỉ quy định 2. Với điều kiện phải tuân thủ khoản 3, lãnh hải, vùng tiếp giáp, vùng đặc quyền về kinh tế và thềm lục địa của hòn đảo được hoạch định theo đúng các quy định của Công ước áp dụng cho các lãnh thổ đất liền khác. 3. Những hòn đảo đá nào không thích hợp cho con người đến ở hoặc cho một đời sống kinh tế riêng, thì không có vùng đặc quyền về kinh tế và thềm lục địa.”",56],["p",72,"Có lãnh hải, tiếp giáp lãnh hải cách xác định nó phù thì nó sẽ không có vùng đặc quyền kinh tế và thềm lục địa mà nó chỉ có vùng lãnh hải, tiếp giáp lãnh hải..",56],["p",67,"Đảo là phải thích hợp cho con người đến ở hoặc cho một đời sống kinh tế riêng Đời sống kinh tế riêng biệt thích hợp cho con người đến ở: ở trên đó đủ tài nguyên để con người sinh sống không phụ thuộc vào nguồn khác ( nguồn nưuosc ngọt, đất để trôgn cây, đa dạng sinh vật ...) -> tận dụng tài nguyên sẵn có trên đảo đủ để con người sinh sống mà không cần phải có sự phụ thuộc vào nơi khác.",56],["p",67,"Đảo thì đầy đủ quyền chủ quyền vùng biển Đá thì không, nó không có vùng đặc quyền kinh tế và thềm lục địa Bãi cạn lúc chìm lúc nôi: nó được coi không khác gì dấy biển mà chỉ là nó nông hơn nên khi nước cạn thì nó nổi lên xíu => không đương cơ sở đi qua trừ khi trên đó xây dựng một kiến trúc lúc nào cũng nổi lên trên ( xác định nội thủy thì phải xây dựng trên đó một kiên trúc lúc nào cũng nổi trên đó )",57]],"pg":[56,57]},{"h":"QUẦN ĐẢO","lv":2,"b":[["p",72,"“Quần đảo” là một tổng thể các đảo, kể cả các bộ phận của các đảo, các vùng nước tiếp liền và các thành phần tự nhiên khác có liên quan với nhau đến mức tạo thành về thực chất một thể thống nhất về địa lý, kinh tế và chính trị, hay được coi như thế về mặt lịch sử. (Điều 46 công ước )",57],["p",72,"Một số đảo không dính liền với nhau về mặt địa lý, cùng kinh tế, chính trị... nhưng nó gần nhau thì nó gộp chung lại với nhau tạo thành quần đảo Các đảo có sự nối liền với nhau ở các bãi cạn Quy chế pháp lý vùng nước quần đảo (Đ49 UNCLOS)",57],["i","lb57_1.jpg",57,848,644],["p",103,"Quốc gia quần đảo “Quốc gia quần đảo” là một quốc gia hoàn toàn được cấu thành bởi một hay nhiều",57],["p",103,"quần đảo và có khi bởi một số hòn đảo khác nữa (Điều 46)",57],["p",85,"Malaysia không đủ điều kiện được coi là quốc gia quần đảo, nó chỉ là bán đảo",57],["p",85,"Indo, đông timo, philipin,.. mới đủ điều kiện",57],["p",103,"Đường cơ sở quần đảo",57],["p",102,"Nối các điểm ngoài cùng của các đảo xa nhất.",57],["p",106,"Tỷ lệ vùng nước xác lập bởi các tuyến đường cơ sở so với diện tích đất: 1:1 – 9:1.",58],["p",106,"Chiều dài các đường cơ sở nối giữa hai đảo liền kề không vượt quá 100 hải lý.",58],["p",106,"3% tổng số các đường cơ sở không vượt quá 125 hải lý.",58],["p",106,"Tuyến các đường cơ sở không được tách quá xa đường bao quanh chung của quần đảo.",58],["p",102,"QG quần đảo chỉ có thể xác định ĐCS thẳng",58],["p",102,"(Điều 47)",58],["p",85,"- Nội thủy : đối với từng đảo,dựa vào đặc điểm của đảo: vịnh, cửa sông,... người ta",58],["p",103,"vẽ các đường giới hạn thì người ta sẽ vạch ra phần nội thủy đối với từng đảo. Và",58],["p",103,"phần nưuosc phía trong là nội thủy",58],["p",85,"- Lãnh hải",58],["p",85,"- Tiếp giáp lãnh hải",58],["p",85,"- Đặc quyền kinh tế",58],["p",85,"- Thềm lục địa",58],["p",85,"- (Điều 48, 50)",58],["p",102,"Máy bay đi qua vẫn phải xin phép chứ k như tàu thuyền là đi qua k cần xin chỉ cần k gây phương hại",58]],"pg":[57,58]}]},{"t":"Quyền chủ quyền","s":"Vùng tiếp giáp, đặc quyền kinh tế, thềm lục địa; đảo nhân tạo, công trình; đánh bắt cá và tài nguyên","pg":"tr.24–46, 58–61, 63–66","g":[{"h":"Sơ đồ tóm tắt chương","lv":2,"b":[["f","sd_lb3.svg",720,630,"Sơ đồ: vùng biển thuộc quyền chủ quyền và quyền tài phán"],["p",72,"Sơ đồ tự lập từ bài giảng và UNCLOS 1982, chưa đối chiếu toàn văn.",0]]},{"h":"","lv":0,"b":[["p",67,"Quốc gia ven biển sẽ đương nhiên có quyền hành chính Vùng tiếp giáp lãnh hải Ranh giới phái trong tiếp giáp lãnh hải là lãnh hải Cách xác định, vẽ đường cơ sở sau đó vẽ một đường cách đg cơ sỏ tối đa 12 hải lý.",24],["p",103,"Vậy đường tiếp giáp lãnh hải sẽ cách đường cơ sở 24 hải lý.",24],["p",103,"Các quốc gia chỉ có thể đơn phương xác định lãnh hải khi có có liên quan đến nước nào cả. Còn khi nào phân định thì k thể đơn phương.",24],["p",103,"Đ27: về vấn đề xảy ra hành vi phạm tội trên từng vùng nước.",24]],"pg":[24,24]},{"h":"3. VÙNG TIẾP GIÁP LÃNH HẢI","lv":2,"b":[["i","lb24_1.jpg",24,984,643]],"pg":[24,24]},{"h":"3.1. Quy chế pháp lý","lv":3,"b":[["p",85,"- Trên vùng tiếp giáp lãnh hải, quốc gia ven biển có quyền",24],["p",121,"+ Ngăn ngừa những vi phạm đối với các luật và quy định về hải quan, thuế khóa, y tế hay nhập cư trên lãnh thổ hay trên lãnh hải của mình",25],["p",121,"+ Trừng trị những vi phạm đối với các luật và quy định xảy ra trong lãnh thổ trên lãnh hải của mình Quốc gia chỉ có quyền ngăn ngừa vi phạm trên vùng tiếp giáp lãnh hải chứ k có quyền trừng trị, vậy chỉ có quốc gia mà tàu đó mang lá cờ mới có quyền đó. ĐIỀU 33.",25],["p",67,"Điều 33 UNCLOS 1982, “Vùng tiếp giáp: 1. Trong một vùng tiếp giáp với lãnh hải của mình, gọi là vùng tiếp giáp, QG ven biển có thể thi hành sự kiểm soát cần thiết, nhằm:",25],["p",103,"Ngăn ngừa những vi phạm đối với các luật và quy định về hải quan, thuế khoá, y tế, hay nhập cư trên lãnh thổ hay trên lãnh hải của mình.",25],["p",103,"Trừng trị những vi phạm đối với các luật và quy định nói trên xảy ra trong lãnh thổ hay trên lãnh hải của mình”. Thẩm quyền của quốc gia ven biển trong vùng tiếp giáp lãnh hải được coi là",25],["p",72,"quyền mang tính “cảnh sát” nhằm bảo vệ lãnh hải và nội thủy.",25],["p",103,"Quyền truy đuổi: Điều 111 UNCLOS 1982 Quyền đối với khảo cổ và lịch sử phát hiện ở biển: Điều 303 UNCLOS 1982",25]],"pg":[24,25]},{"h":"3.2. Về quyền tài phán của QG ven biển:","lv":3,"b":[["p",103,"- Ngăn ngừa và xử lý những vi phạm đối với các luật và quy định của QG ven biển về:",25],["p",121,"● hải quan;",25],["p",121,"● thuế;",25],["p",121,"● y tế;",25],["p",121,"● nhập cư xảy ra trên lãnh thổ hay trong lãnh hải của mình.",25],["p",103,"3.3. Về quyền chủ quyền, quyền tài phán khác của QG ven biển trong vùng TGLH: TGLH là một bộ phận của vùng ĐQKT, vì vậy, QG ven biển cũng có các quyền chủ quyền, quyền tài phán ở vùng TGLH tương tự ở vùng ĐQKT.",25],["p",103,"(Xem Đ.56 UNCLOS, Đ.14K1 Luật Biển VN)",25],["p",103,"Quyền chủ quyền , quyền tài phán ở vùng TGLH tương tự ở vùng",25],["p",103,"ĐQKT.",25],["p",139,"Điều 14 Luật Biển VN 2012.",25],["p",103,"Chế độ pháp lý của vùng tiếp giáp lãnh hải 1. Nhà nước thực hiện quyền chủ quyền, quyền tài phán QG và các quyền khác quy định tại Điều 16 của Luật này đối với vùng tiếp giáp lãnh hải.",25],["p",106,"2. Nhà nước thực hiện kiểm soát trong vùng tiếp giáp lãnh hải nhằm ngăn ngừa và trừng trị hành vi vi phạm pháp luật về hải quan, thuế, y tế, xuất nhập cảnh xảy ra trên lãnh thổ hoặc trong lãnh hải Việt Nam.",26],["p",72,"Quyền tài phán về hành chính: Điều 10 NĐ 162/2013",26],["p",72,"Quyền chủ quyền về kinh tế: tương tự như vùng ĐQKT",26],["p",72,"Các quyền đối với tài nguyên sinh vật",26],["p",90,"✓ Quyền ấn định khối lượng đánh bắt (61.1)",26],["p",90,"✓ Quyền thi hành các biện pháp bảo tồn và quản lý tài nguyên sinh vật (61.2)",26],["p",90,"✓ Quyền ấn định số dư của khối lượng cho phép đánh bắt (62.2)",26]],"pg":[25,26]},{"h":"4. VÙNG ĐẶC QUYỀN KINH TẾ","lv":2,"b":[["i","lb26_1.jpg",26,837,627],["i","lb27_1.jpg",27,951,591]],"pg":[26,27]},{"h":"4.1. Khái niệm","lv":3,"b":[["p",107,"“Vùng đặc quyền kinh tế” (Exclusive Economic Zone) là vùng biển nằm tiếp liền phía ngoài lãnh hải, có chiều rộng không quá 200 hải lý tính từ đường cơ sở trở ra. (Điều 55, 57 UNCLOS 1982)",27],["p",72,"Ranh giới phía trong của vùng đặc quyền kinh tế trùng với ranh giới phía",27],["p",72,"trong của đường tiếp giác lãnh hải ( ranh giới phía trong tiếp giáp lãnh hải",27],["p",72,"là ĐCSở.)",27],["p",67,"Vì tiếp giáp lãnh hải là 1 phần của ĐQKT -> quyền của TGLH thuộc về ĐQKT ( Đ33) Quốc gia muốn xác lập quyền về vùng ĐQKT thì phải đưa ra tuyên bố công khai thì mới được xác lập. Trường hợp TLĐ kéo dài 200 hải lý thì nó trung với VĐQKT, nếu kéo 350 hải lý (phụ thuộc đường đẳng sâu) thì có trường hợp bên dưới là thêm lục địa nhưng bên trên lại là biển quốc tế.",27]],"pg":[27,27]},{"h":"4.2. Vùng đặc quyền kinh tế của Việt Nam","lv":3,"b":[["p",103,"Luật Biển VN 2012 “Điều 15. Vùng đặc quyền kinh tế Vùng đặc quyền kinh tế là vùng biển tiếp liền và nằm ngoài lãnh hải Việt Nam, hợp với lãnh hải thành một vùng biển có chiều rộng 200 hải lý tính từ đường cơ sở”.",27],["p",85,"⇒ Nếu quốc gia không tuyên bố xác lập ( tuyên bố công khai về",27],["p",103,"vùng thêm đặc quyền kinh tế của mình) thì đó là vùng biển quốc",27],["p",103,"tế => Đặc quyền kinh tế muốn có thì phải có sự tuyên bố, xác",27],["p",103,"lập vùng đặc quyền kinh tế",27],["p",102,"Note : để dễ nhớ",28],["p",102,"Vùng nước lịch sử là vùng nước khai thác, sử dụng vùng nước đó lâu dài, công khai và được các nước khác công nhận.",28],["p",67,"vùng nội thủy mới dùng vùng nước lịch sử",28],["p",67,"danh nghĩa lịch sử liên quan đến đường cơ sở.",28],["p",67,"Còn lãnh hải thì không danh nghãi lịch sử, ngoại lệ gì để mở rộng hơn về vùng lãnh hải",28]],"pg":[27,28]},{"h":"4.3. Quy chế pháp lý : học tới đây","lv":3,"b":[["i","lb28_1.jpg",28,1093,729],["p",103,"Bao gồm:",28],["p",85,"- Quyền của quốc gia ven biển",28],["p",121,"+ Quyền kinh tế",28],["p",121,"+ Quyền tài phán",28],["p",85,"- Quyền và nghĩa vụ của các quốc gia khác",28],["p",85,"CSPL: Đ55 UNCLOUS 1982; Đ16 LB 2012.",28],["p",139,"Vùng đặc quyền về kinh tế là một vùng nằm ở phía ngoài lãnh hải và tiếp liền với lãnh hải, đặt dưới chế độ pháp lý riêng quy định trong phần này, theo đó các quyền và quyền tài phán của quốc gia ven biển và các quyền và quyền tự do của các quốc gia khác đều do các quy định thích hợp của Công ước điều chỉnh. (Điều 55 Công ước 1982)",28],["p",139,"Vùng đặc quyền về kinh tế không được mở rộng ra quá 200 hải lý kể từ đường cơ sở dùng để tính chiều rộng lãnh hải. (Điều 57)",28],["p",139,"Vùng tiếp giáp lãnh hải là 1 bộ phận của vùng đặc quyền kinh tế",29],["p",139,"“Tiếp liền với lãnh hải” Đ55 vậy ranh giới phía trong của nó tiếp giáp với ranh giới phía trong của đường tiếp giáp lãnh hải.",29],["p",139,"Đặc quyền kinh tế tức các quyền về kinh tế chỉ dành riêng cho nước ven biển, lần đầu tiên được ghi nhận trong UNCLOS.",29],["p",139,"Muốn có phải tuyên bố xác lập chứ nó không đương nhiên xuất hiện.",29],["p",139,"Trước công ước 1982 thì chưa được có quy định nào là quyền đặc quyền kinh tế",29],["p",139,"Từ vùng lãnh hải trở đi thì đều xác định từ đường cơ sở, không áp dụng các ngoại lệ như các vùng từ đường cơ sở tính vào như yếu tố lịch sử, văn hóa,...",29],["p",99,"Ngoại lệ điều 33: quốc gia ven biển cũng được quyền hưởng các đặc quyền khác so với…",29]],"pg":[28,29]},{"h":"4.3.1. Quyền của quốc gia ven biển","lv":3,"b":[["p",103,"Quyền tài phán là để bảo vệ cho quyền kinh tế.",29],["p",102,"UNCLOS 1982 “Điều 56: Các quyền, quyền tài phán và các nghĩa vụ của QG ven biển trong vùng ĐQKT”. Có quyền tài phán nên khi lắp đặt ống dẫn ngầm làm ảnh hưởng đến vùng biển của họ thì họ có quyền xử lý",29],["p",85,"- Quyền kinh tế: K1 Đ56",29],["p",121,"+ “Các quyền thuộc chủ quyền về việc thăm dò khai thác, bảo tồn và quản lý các tài nguyên thiên nhiên, sinh vật hoặc không sinh vật, của vùng nước bên trên đáy biển, của đáy biển và lòng đất dưới đáy biển, cũng như về những hoạt động khác nhằm thăm dò và khai thác vùng này vì mục đích kinh tế”",29],["p",121,"● Đối với TN sinh vật:",29],["p",157,"○ Đánh bắt cá/hải sản nói chung, quốc gia có quyền tự đánh giá khả năng đánh bắt. Số lượng cá dư cho phép bắt có thể giao cho quốc gia không được hưởng lợi đánh bắt nhưng việc tuyên bố có dư cá ngoài biển hay không thì là của quốc gia đó, khá khó cho quốc gia thiệt thòi khác có thể hưởng lợi.",29],["p",139,"+ các hoạt động khai thác, đánh bắt cá, hải sản nói chung. Theo quy định công ước thì quốc gia tự mình định giá tổng khối lượng cho phép đánh bắt, đánh giá khả năng đánh bắt thực tế, ấn định số dư cho phép đánh bắt (số lượng dư: nhỏ hơn số lượng cá được phép đánh bắt.)",29],["p",157,"○ Quốc gia ven biển có chủ quyền hoàn toàn và trọn vẹn đối với các nguồn hải sản ở ĐQKT",29],["p",157,"○ Tàu thuyền nước ngoài muốn đánh bắt cá ở vùng ĐQKT phải xin phép, và tuân thủ các điều kiện do quốc gia ven biển đặt ra ( loại cá, kích cỡ, thời gian, đóng lệ phí bao nhiêu phần trăm, nộp tỉ lệ bao nhiêu phần trăm khai thác). Dạng có giấy phép đánh bắt có thời hạn và chi phí",30],["p",157,"○ Nếu quốc gia ven biển có khả năng kỹ thuật đánh bắt hết toàn bộ sản lượng cá thì có thể giữ độc quyền khai thác từ chối không cho các nước khác đánh bắt ở đây",30],["p",157,"○ Quốc gia ven biển có quyền quy định về các vấn đề sau: việc cấp giấy phép; thuế; chủng loại đánh bắt, số lượng đánh bắt; mùa vụ và khu vực đánh bắt; tuổi, cỡ và các loại sinh vật có thể được đánh bắt",30],["p",157,"- Tàu cá phải bật định vị hành trình, phải ghi lại số liệu đánh bắt",30],["p",121,"● Vấn đề đánh bắt cá",30],["p",157,"○ Quốc gia ven biển có quyền quy định về các vấn đề sau:",30],["p",229,"■ Việc cấp giấy phép",30],["p",229,"■ Thuế",30],["p",229,"■ Chủng loại đánh bắt, số lượng đánh bắt",30],["p",229,"■ Mùa vụ và khu vực đánh bắt",30],["p",229,"■ Tuổi, cỡ và các loại sinh vật có thể được đánh bắt",30],["p",229,"■ (khoản 4 điều 62)",30],["p",121,"● TN không sinh vật:",30],["p",121,"Tài nguyên không sinh vật : dầu mỏ, khí đốt, nước biển, các chất thành phần trng nước biển",30],["p",99,"+ bao gồm tài nguyên không sinh vật của vùng nước bên trên đáy biển, đáy biển và lòng đất dưới đáy biển",30],["p",99,"+ QCVB tự mình khai tahsc cho phép các quốc gia khác thác dưới sự kiểm soát của mình",30],["p",121,"● Đối với các hoạt động khác nhằm mục đích kinh tế:",30],["p",99,"+ bất kì hoạt động nào nhằm thăm dò, khai thác vùng này vì mục đích kinh tế Ví dụ: sản xuất năng lượng từ nước, hải lưu và gió",30],["p",157,"○ Bao gồm tài nguyên k sinh vật của vùng nước bên trên đáy biển, đáy biển và lòng đất dưới đáy biển",30],["p",157,"○ QCVB tự mình khai thác cho phép các quốc gia khai thác khai thác dưới sự kiểm soát của mình",30],["p",121,"● Hoạt động khác:",30],["p",157,"○ Bất kỳ hoạt động nào nhằm thăm dò, khai thác vùng này vì mục đích kinh tế",30],["p",157,"○ Vd: sản xuất năng lượng từ nước, hải lưu và gió.",31],["p",121,"● Các biện pháp bảo đảm thực hiện quyền chủ quyền của QG ven biển đối với tài nguyên thiên nhiên trong vùng ĐQKT",31],["p",139,"○ “ĐIỀU 73. Thi hành các luật và quy định của quốc gia ven biển",31],["p",85,"- Quyền tài phán: K2 Đ56, Đ60, 107, 108, K5 Đ210, Đ211, 207,208 (jurisdiction) theo đúng những quy định thích hợp của Công ước về việc:",31],["p",103,"i. Lắp đặt và sử dụng các đảo nhân tạo, các thiết bị và công trình;: đ60",31],["p",103,"ii. Nghiên cứu khoa học về biển; Thì phải được sự đồng ý của quốc gia ven biển và tuân thủ theo pháp luật nước đấy",31],["p",90,"- Quốc gia ven biển có quyền không cho phép thực hiện NCKH nếu gây ảnh",31],["p",108,"hưởng tài nguyên; sử dụng hoặc đưa chất độc hại vào môi trường biển;",31],["p",139,"Những vụ việc tràn dầu, gây ô nhiễm, vv gây phương hại đến các quốc gia ven biển thì họ có quyền tài phán đối với tàu thuyền đang gắn cờ của quốc gia đó.",31],["p",139,"CSPL: K2 Đ45 UNCLOS: phải tính đến các quyền của quốc gia khác và hđ phù hợp với công ước",31]],"pg":[29,31]},{"h":"K1Đ73 UNCLOS","lv":2,"b":[["p",103,"iii. Bảo vệ và gìn giữ môi trường biển; Các tàu thuyền mà gây ô nhiễm (tai nạn xảy ra làm tràn dầu) ra vùng biển thuộc đặc quyền kinh tế => quốc gia ven biển có quyền xử lý (…Điều 56 –tiếp…) c) Các quyền và các nghĩa vụ khác do Công ước quy định. 2. Trong vùng đặc quyền về kinh tế, khi thực hiện các quyền và làm các nghĩa vụ của mình theo Công ước, QG ven biển phải tính đến các quyền và nghĩa vụ của các QG khác và hành động phù hợp với Công ước. 3. Các quyền có liên quan đến đáy biển và lòng đất dưới đáy biển nêu trong điều này được thực hiện theo đúng Phần VI.”",31],["p",99,"=> Ngoài 3 lĩnh vực này thì không thuộc quốc gia ven biển xử lý mà thuộc",31],["p",64,"quốc gia mà con tàu mang quốc tịch",31],["p",85,"● Đối với quốc giá không có biển và bất lợi về địa lý: Đ69, 70",31],["p",121,"- Hđ khai thác số dư của khối lượng cá cho phép đều dựa vào thỏa thuận bằng việc ký hiệp ước với quốc gia đó. Quốc gia ở thế “chủ động” sẽ là chủ thể có quyền báo số lượng dư đó mà không có ai kiểm tra, kí hay không tùy thuộc vào họ và các điều khoản như loại cá, vùng nước, thời gian cũng do họ đề ra.",31],["p",102,"Quốc gia bất lợi về địa lý: bản thân người thân phụ thuộc rất lớn vào việc",32],["p",67,"khai thác tài nguyên biển đó, nhưng tài nguyên biển đó quá ít không đủ => quốc",32],["p",67,"gia bất lợi về mặt địa lý có quyền yêu cầu quốc gia bên cạnh ven biển khai thác số",32],["p",67,"lượng cá dư ( thông qua đuqt và thỏa thuận) => phụ thụooc vào quốc gia có dư",32],["p",67,"( có thể có dư nhưng thông báo là không có dư, không ký vào đuqt,…)",32],["p",103,"Nghĩa vụ của QG ven biển trong vùng ĐQKT của mình",32],["p",121,"● Nghĩa vụ tôn trọng và bảo đảm các quyền của các QG khác trong vùng ĐQKT của mình mà UNCLOS quy định (Vd: Quyền tự do hàng hải/Tự do hàng không/Tự do đặt dây cáp, ống dẫn ngầm) (Điều 56 khoản 1c và 2; Điều 58)",32],["p",121,"● Nghĩa vụ bảo tồn các nguồn lợi sinh vật (Điều 61)",32],["p",121,"● Nghĩa vụ bảo đảm quyền của các quốc gia không có biển (Điều 69); Quyền của các QG bất lợi về mặt địa lý (Điều 70)",32],["p",121,"● ...",32],["p",103,"Quyền của quốc gia không có biển và bất lợi về địa lý Các quốc gia không có biển hoặc bất lợi về địa lý có quyền tiến hành các hoạt động khai thác số dư của khối lượng cá cho phép đánh bắt trong vùng đặc quyền kinh tế của quốc gia ven biển, thông qua các điều ước quốc tế hoặc các thỏa thuận có liên quan (69, 70 Công ước)",32],["i","lb32_1.jpg",32,1099,556]],"pg":[31,32]},{"h":"4.3.2. Quyền và nghĩa vụ của Quốc gia khác trong vùng ĐQKT của QG ven biển","lv":3,"b":[["p",103,"- CSPL: Điều 58 và 87 UNCLOS Các quyền tự do mà nước ngoài được thực hiện trong vùng ĐQKT của QG ven biển:",32]],"pg":[32,32]},{"h":"1. Tự do hàng hải","lv":3,"b":[],"pg":[32,32]},{"h":"2. Tự do hàng không","lv":3,"b":[],"pg":[32,32]},{"h":"3. Tự do lắp đặt dây cáp ống dẫn ngầm (IF…)","lv":3,"b":[["p",121,"Đ58, 87 UNCLOS về quyền và nghĩa vụ của các quốc gia",32],["p",121,"Vùng trời phía trên vùng đặc quyền kinh tế là vùng quốc tế chứ k phải quốc gia",33],["p",121,"Tự do hàng hải: thích đi nhanh, chậm, đi vòng quanh vùng đặc quyền kinh tế đều được, chỉ cần không gây phương hại đến quốc gia có vùng ĐQKT đó.",33],["p",121,"Tự do hàng không: vùng trời phía trên đặc quyền kinh tế (vùng trời quốc tế. vì vùng trời quốc gia là ở mặt đất + lãnh hải) thì các Phương tiện hàng không vẫn phải tuân thủ chặt chẽ về quy định đã được đề ra, không được bay cao, thấp, nhanh, chậm theo ý thích mà k phải vì bất kỳ một tác động ngoại cảnh như thời tiết nào cả; Và chỉ bay 1 đường cố định đã được vạch sẵn",33],["p",121,"Tự do đặt dây cáp ống dẫn ngầm ( đ87) ( công trình) : nếu xảy ra các thiệt hại (kể cả thiệt hại cho các quốc gia khác đang đặt dây cáp, ống dẫn ngầm ở đây) thì quốc gia có vùng ĐQKT này đều có quyền tài phán.",33],["p",99,"Các Quốc gia tự do đặt dây cáp và ống dẫn ngầm tư do ( công trình)",33],["p",64,"nhưng có quy định về việc Quốc gia ven biển có quyền tài phán đảo nhân",33],["p",64,"tạo va thiết bị công trình. (?) 2 quyền này có sự trái nhau không ?",33],["p",85,"⇒ Quyền tài phán là sự lý vi phạm. nếu có quyền tự do … thì cứ quyền tự",33],["p",103,"do lắp đặt . nhưng trong quá trình có vi phạm và gây ra thiệt hịa thì quốc",33],["p",103,"gia ven biển có quyền xử lý.",33],["p",85,"⇒ Vd: trong quá trình lắp đặ ống dẫn ngầm thì phải tuân thủ điều kiển",33],["p",103,"chuyên môn an toàn, chống trường hợp gây ra ô nhiễm môi trường.",33],["p",103,"nhưung trong quá trình lắp đặt thì k đáp ứng đu rđiều kiện , gây ra ô",33],["p",103,"nhiễm thì sẽ bị quốc gia ven biển xử phạt",33],["p",85,"⇒ 2 quyền anỳ không mâu thuẫn với nhau",33],["p",121,"về quyền và nghĩa vụ của các quốc gia",33],["p",103,"Chỉ cần đi qua không gây hại hay lợi dụng các quyền tự do để nhằm mục đích khác thì k được. Quốc gia ven biển khai thác các tài nguyên thiên nhiên nằm ngoài 200 hải lý kể từ đường cơ sở thì phải nộp các khoản đóng góp bằng tiền hoặc hiện vật (82)",33],["p",103,"Khoản đóng góp ở đ82 ÁP DỤNG VỚI CÁC QUỐC GIA CÓ THỀM LỤC ĐỊA MỞ RỘNG CÒN TRONG 200 hải lý thì không cần.",33],["p",139,"Quyền khai thác số dư tài nguyên sinh vật trong vùng ĐQKT của QG ven biển CSPL: Điều 62 khoản 2 QGVB xác định có số dư --> cho phép QG khác tham gia đánh bắt thông qua điều ước quốc tế, ưu tiên cho QG không có biển (Đ.69) và quốc gia bất lợi về mặt địa lý (Đ.70) trong cùng khu vực.",34],["p",139,"Liên hệ Quy chế pháp lý của vùng ĐQKT của VN Điều 16 Luật Biển Việt Nam 2012",34],["p",144,"Điều 16. Chế độ pháp lý của vùng đặc quyền kinh tế 2. Nhà nước tôn trọng quyền tự do hàng hải, hàng không; quyền đặt dây cáp, ống dẫn ngầm và hoạt động sử dụng biển hợp pháp của các quốc gia khác trong vùng đặc quyền kinh tế của Việt Nam theo quy định của Luật này và điều ước quốc tế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên, không làm phương hại đến quyền chủ quyền, quyền tài phán quốc gia và lợi ích quốc gia trên biển của Việt Nam. Việc lắp đặt dây cáp và ống dẫn ngầm phải có sự chấp thuận bằng văn bản của cơ quan nhà nước có thẩm quyền của Việt Nam.",34],["p",103,"Nghĩa vụ:",34],["p",103,"Tôn trọng các quyền của quốc gia ven biển Muốn nghiên cứu khoa học thì phải được sự đồng ý của QGVB",34]],"pg":[32,34]},{"h":"5. THỀM LỤC ĐỊA","lv":2,"b":[],"pg":[34,34]},{"h":"5.1. Khái niệm","lv":3,"b":[["p",85,"• Thềm lục địa của quốc gia ven biển bao gồm đáy biển và lòng đất dưới đáy biển nằm bên ngoài lãnh hải của quốc gia ven biển kéo dài cho đến bờ ngoài của rìa lục địa hoặc đến cách đường cơ sở dùng để tính chiều rộng lãnh hải là 200 hải lý khi bờ ngoài của rìa lục địa ở khoảng cách gần hơn. Trong trường hợp bờ ngoài của rìa lục địa kéo dài vượt quá 200 hải lý tính từ đường cơ sở thì thềm lục địa của quốc gia ven biển cũng không được vượt quá 350 hải lý tính từ đường cơ sở hoặc không được vượt quá 100 hải lý tính từ đường đẳng sâu 2500m”",34],["p",85,"• (Điều 76, Công ước 1982)..",34],["i","lb35_1.jpg",35,981,765],["p",102,"(UNCLOS, Điều 76: “Định nghĩa thềm lục địa”) Thềm lục địa bờ biển thì là khác.",35],["p",102,"Theo điều 77 khoản 3: cần tuyên bố j cả như ĐQKT (Đ75 K3) => nguyên tắc đất thống trị biển Thêm lục địa chất",35],["p",121,"- Phần bắt đầu ngập dưới nước được gọi là thềm lục địa. Địa hình sẽ bắt đầu nghiêng xuống cho đến khi đạt một khoảng độ cao 300m từ bề mặt nước đến mặt đất dưới nước sẽ kết thúc thềm lục địa, sau đó 3.000m - 4.000m dốc xuống được gọi là bờ lục địa. “Bờ ngoài của rìa lục địa” ( vài chục m – 500km) được lấy mốc là phần rãnh nứt đầu tiên cắt ngang bờ lục địa aka bờ lục địa kết thúc",35],["p",121,"- Nếu thềm lục địa tự nhiên hẹp quá thì có thể lấy tối đa 200 hải lý kể từ bờ ngoài của rìa lục địa Đọc thêm (Đ76 UNCLOS)",35],["p",121,"- Vị trí bờ ngoài của rìa lục địa => điểm tiếp giáp của rìa lục địa với đại dương Thềm lục địa của quốc gia ven biển bao gồm đáy biển và lòng đất dưới đáy biển nằm bên ngoài lãnh hải của quốc gia ven biển kéo dài cho đến bờ ngoài của rìa quốc gia hoặc đến cách đường cơ sở dùng để tính chiều rộng lãnh hải… Thềm lục địa của Việt Nam (Điều 17 Luật Biển 2012): là vùng đáy biển và lòng đất",35],["p",72,"dưới dáy biển, tiếp liền và nằm ngoài lãnh hải của Việt Nam, trên toàn bộ phần kéo",35],["p",72,"dài tự nhiên của lãnh thổ đất liền, các đảo và quần đảo…………….",35],["p",67,"Tổng kết :",36],["p",85,"+ Ranh giới phía trong của thềm lục địa là ranh giới phía ngoài lãnh hải",36],["p",85,"+ Ranh giới phái ngoài của thềm lục đại là bề ngoài của rìa lục địa",36],["p",85,"+ Nếu nhỏ hơn 200 hải lý thì được quyền lấy đến 200 hải lý",36],["p",85,"+ Nếu bờ ngoài cảu rềm lục địa rôgnj hơn 200 hải lý thì theo nguyên tắc chung là rộng đến đầu lấy đến đó nhưng có giới hạn không được vượt quá 350 hải lý từ đương cơ sở hoặc không được vượtq áu 100 hải lý tính từ đường đẳng sau 25000m ( tức là tính 2500 m từ đương đẳng sau lấy thêm 100 hải lý nữa) ( cái nào có lợi hơn thì áp dụng cái đó",36],["p",85,"+ Cspl : điều 76 Công ước 1982 Nếu đáy biển sâu thì áp dụng đường cơ sở Nếu đấy biển thoai thỏa ra rất xa mới đạt được 25000m thì tốt nhất lấy 100 hải lý có lợi hơn",36]],"pg":[34,36]},{"h":"5.2. Cách xác định bề rộng Thềm lục địa","lv":3,"b":[["p",85,"● Ranh giới phía trong của thềm lục địa là ranh giới phía ngoài lãnh hải",36],["p",85,"● Ranh giới phía ngoài của thềm lục địa là bờ ngoài của rìa lục địa",36],["i","lb36_1.jpg",36,1093,381],["i","lb37_1.jpg",37,949,775],["i","lb38_1.jpg",38,1095,890],["i","lb39_1.jpg",39,1018,913],["p",102,"Theo Điều 76 UNCLOS 1982, chiều rôṇ g của TLĐ có thể được xác lâp̣ theo hai giới hạn sau đây:",39],["p",121,"○ Thứ nhất, nếu TLĐ của QG ven biển có chiều rôṇ g hẹp hơn hoăc̣ bằng 200 hải lý tính từ ĐCS thì QG ven biển tuyên bố TLĐ của mình rôṇ g 200 hải lý; (về mặt thực tế thì tính cả đáy đại dương",39],["p",121,"○ Thứ hai, nếu TLĐ của QG ven biển rôṇ g hơn 200 hải lý tính từ ĐCS đến bờ ngoài của rìa lục địa thì chiều rôṇ g TLĐ không vượt quá 350 hải lý hoăc̣ bằng 100 hải lý tính từ đường đẳng sâu 2500m (K5 Đ 76).",39],["p",139,"Đường đẳng sau: là nối tất cả các điểm 2500m lại với nhau để ra được đường này",39],["p",85,"● K3 Đ77",39],["p",121,"- Vùng ĐQKT chỉ có quyền đối với tài nguyên",39],["p",121,"- Còn thềm lục địa đương nhiên thuộc hoàn toàn về quốc gia đó. (toàn quyền về chủ quyền)",39],["p",121,"○ Đường ĐQKT có thể trùng với thềm lục địa tùy vào cách xác định thềm lục địa của quốc gia, phải có văn bản phân định rõ để tránh tranh chấp xảy ra do các quyền của 2 vùng nước này khác nhau.",39],["p",121,"● Sau khi xác định chính xác các tọa độ xác định…",39],["p",103,"Tính chất pháp lý Thềm lục địa đương nhiên thuộc về quốc gia mà k cần bất kỳ sự tuyên bố chiếm hữu thật sự hay danh nghiac nào (k3-77 công ước 1982)",40],["p",103,"Thềm lục địa của VN Điều 17 Luật Biển Việt Nam 2012 (đọc)",40],["p",102,"Điều 4 khoản 4 Luật Biên giới quốc gia 2003",40],["p",108,"4. Thềm lục địa là đáy biển và lòng đất dưới đáy biển thuộc phần kéo dài tự nhiên của lục địa mở rộng ra ngoài lãnh hải cho đến bờ ngoài của rìa lục địa mà Việt Nam là quốc gia ven bờ có quyền chủ quyền, quyền tài phán được xác định theo Công ước của Liên hợp quốc về Luật biển năm 1982, trừ trường hợp điều ước quốc tế giữa Cộng hoà xã hội chủ nghĩa Việt Nam và các quốc gia hữu quan có quy định khác.",40],["p",67,"Đối với đặc quyền kinh tế và thềm lục địa Đặc quyền kinh tế chỉ có quyền kinh tế, quyền về tài nguyên trong khu đặc quyền thôi, chứu không tất cả quyền ( giống nhưu quyène đối với tài sản trên đất, tài sản còn đất đai thuộc nhà nước)",40],["p",67,"Thẩm lục địa thì có quốc gia có toàn quyền đối với thềm đó luôn, quyền thêm lục địa trong thềm lục địa trong đó ( tất cả các quyền)",40],["p",67,"( quyền của đặc quyền kinh tế hẹp hơn so với thềm lục địa)",40],["p",67,"Đường ĐQKT có thể trùng với thềm lục đại tùy vào cách xác định thềm lục địa của quốc gia, phải có văn bản phân định rõ để tranh chấp xảy ra do các quyền của 2 vùng nước này khác nhau.",40],["p",102,"Quyền và nghĩa vụ của quốc gia ven biển",40],["i","lb40_1.jpg",40,1099,461],["p",138,"Thực hiện các quyền chủ quyền đối với thềm lục địa trong việc thăm dò, khai thác các tài nguyên thiên nhiên (điều 77)",40],["p",139,"Đặc quyền cho phép và điều chỉnh việc khoan ở thềm lục địa với bất kì mục đích nào Tiến hành học áp dụng và quy định thể thức điều kiện xây dựng khai thác use các đảo nhân tạo Có quyền tài phán đối với dây cáp và ống dẫn ngầm được đạt hoặc use trong khuôn khổ của việc thăm dò thềm lục địa của mình hoặc của việc khai thác các đảo nhân tạo, các thiết bị hay công trình thuộc quyền tài phán của quốc gia này (điều 79, khoản 4)",41],["p",90,"Quyền của quốc gia ven biển: khoản 4 Điều 79",41],["p",85,"• Thực hiện các quyền chủ quyền đối với thềm lục địa trong việc thăm dò, khai thác các tài nguyên thiên nhiên (Điều 77)",41],["p",85,"• Đặc quyền cho phép và điều chỉnh việc khoan ở thềm lục địa với bất kỳ mục đích nào. (Điều 81)",41],["p",85,"• Tiến hành hoặc áp dụng các biện pháp thích hợp để bảo vệ môi trường",41],["p",85,"• Xây dựng, cho phép và quy định thể thức, điều kiện xây dựng, khai thác, sử dụng các đảo nhân tạo (Điều 80)",41],["p",85,"• Có quyền tài phán đối với dây cáp và ống dẫn được đặt hoặc sử dụng trong khuôn khổ của việc thăm dò thềm lục địa của mình, hoặc của việc khai thác các đảo nhân tạo, các thiết bị hay công trình thuộc quyền tài phán của quốc gia này. (Điều 79, Khoản 4).",41],["p",90,"✓ Nghiên cứu khoa học về biển: Đ 246",41],["p",90,"✓ Khoan ở thềm lục địa: Đ81",41],["p",90,"✓ Bảo vệ và giữ gìn môi trường biển: Đ 214, 216 Nghĩa vụ của nước ven biển",41],["p",85,"• Không được cản trở các quyền tự do của các quốc gia khác trong vùng nước phía trên và vùng trời phía trên vùng nước đó. (Điều 78).",41],["p",85,"• Không được cản trở các quốc gia khác đặt dây cáp và ống dẫn ngầm trên thềm lục địa trừ trường hợp để ngăn ngừa và hạn chế ô nhiễm do ống dẫn ngầm gây ra.",41],["p",103,"( Điều 79)",41],["p",85,"• Quốc gia ven biển khai thác các tài nguyên thiên nhiên nằm ngoài 200 hải lý kể từ đường cơ sở thì phải nộp các khoản đóng góp bằng tiền hoặc hiện vật. (Điều 82).",41],["p",90,"✓ Nếu thềm lục địa rộng hơn 200 hải lý thì phải xác định rõ tọa độ, báo cáo",41],["p",108,"thông tin về các ranh giới ngoài cho Ủy ban ranh giới thềm lục địa (CLCS)",41],["p",102,"Khoản 8 Điều 76",41],["p",90,"- Đến ngày 13/05/2009, nếu quốc gia nào không đăng ký mở rộng thềm lục",41],["p",108,"địa thì không có quyền khai thác thềm lục địa mở rộng",41],["p",90,"- Việt Nam đã đăng ký mở rộng thềm lục địa vào ngày 07/05/2009",42],["p",90,"✓ Có nghĩa vụ đóng góp về việc khai thác tài nguyên thiên nhiên không sinh",42],["p",108,"vật ở thềm lục địa nằm ngoài 200 hải lý: khoản 1 Điều 82",42],["p",90,"- Mức đóng góp: khoản 2 Điều 82",42],["p",90,"- Các khoản đóng góp này sẽ được phân chia công bằng, tính đến lợi ích và",42],["p",108,"nhu cầu của các quốc gia đang phát triển : khoản 4 Điều 82",42],["p",90,"✓ Khi thực thi quyền, quốc gia ven biển không được làm ảnh hưởng chế độ",42],["p",108,"pháp lý vùng nước bên trên hay vùng trời bên trên vùng nước này; không",42],["p",108,"gây thiệt hại đén các quyền và các tự do khác: Điều 78",42],["p",64,"- quyền và nghĩa vụ của quốc gia khác",42],["p",67,"cspl: Điều 78 : quyền và nghãi vụ cảu các quốc gia khác",42],["p",67,"động vật thuộc lớp nước phía trên : cá sấu, tôm, bạch tuột ( tự bơi mặc dù làm tổ",42],["p",67,"ở dánh biển)",42],["p",67,"động vật dưới đấy biển: trai, … chứ không chru động tự bơi được.",42],["p",67,"Theo Đ78 CƯ 1982.",42],["p",157,"- Tự do hàng hải",42],["p",157,"- Tự do hàng hông",42],["p",157,"- Tự do lắp đặt dây cáp và ống dẫn ngầm",42],["p",157,"- Tự do đánh bắt cá và NCKH đối với lớp nước phá trên năm ngoài vùng ĐQT Nghĩa vụ :",42],["p",85,"• Tôn trọng các quyền chủ quyền của quốc gia ven biển đối với khu vực thềm lục địa của họ.",42],["p",85,"• Khi đặt các dây cáp và ống dẫn ngầm, các quốc gia phải tính đến các dây cáp và ống dẫn ngầm đã được đặt trước đó. Cần chú ý không làm phương hại đến khả năng sửa chữa các đường dây cáp và ống dẫn ngầm đó.(Điều 79, Khoản5)",42]],"pg":[36,42]},{"h":"5.3. Quy chế pháp lý của thềm lục địa","lv":3,"b":[["p",102,"5.3.1. Quyền chủ quyền, quyền tài phán và nghĩa vụ của QG ven biển đối với TLĐ của mình",42],["p",85,"● Theo Điều 77 UNCLOS 1982: Quyền xây dựng, cho phép và quy định thể thức, điều kiện xây dựng, khai thác, sử dụng các đảo nhân tạo (Điều 80)",42],["p",139,"Các quốc gia có thể bồi lấp, xây dựng các công trình gắn liền với đáy biển để phục vụ cho kinh tế an ninh xã hội như giàn khoan, trên giàn khoan có thể thuần túy là dàn khoan hoặc hơn nữa là nhà ở, khu sinh hoạt cố định",43],["p",85,"● Quyền tài phán đối với dây cáp và ống dẫn được đặt hoặc sử dụng trong khuôn khổ của việc thăm dò TLĐ của mình, hoặc của việc khai thác các đảo nhân tạo, các thiết bị hay công trình thuộc quyền tài phán của QG này. (Đ.79, K.4).",43],["p",102,"Đ78, 79, 82 Khoản đóng góp ở đ82 ÁP DỤNG VỚI CÁC QUỐC GIA CÓ THỀM LỤC ĐỊA MỞ RỘNG CÒN TRONG 200 hải lý thì không cần. Đóng góp chỉ áp dụng với nước các phát triển; các nước kém phát triển thì không nhưng cần phải thêm điều kiện là chuyên phải nhập khẩu các loại khoáng sản bên ngoài.",43],["p",139,"Đ78: tự do đánh bắt cá và nghiên cứu khoa học đối với lớp dưới phía trên thì lcú này sẽ là khoảng 150 hải lý khi thềm lục địa rộng hơn đường ĐQKT (350 hải lý - 200 hải lý)",43],["p",102,"Dây cáp thì thoải mái nhưng nếu xây thêm trục đỡ thì nó sẽ liền quan đến quyền chủ quyền của quốc gia đó.",43],["p",85,"● Quyền tài phán về viêc̣ khoan ở TLĐ (Đ.81);",43],["p",85,"● Quyền tài phán trong lĩnh vực bảo vê ̣và giữ gìn môi trường biển (Đ79 K2);",43],["p",85,"● Quyền đào đường hầm ở TLĐ (Đ. 85)",43],["p",67,"Đảo: Đ121 UNCLOS thì khi nào có có chủ quyền quốc gia thì mới có đầy đủ các vùng biển",43]],"pg":[42,43]},{"h":"3.3 Thềm lục địa","lv":3,"b":[["p",103,"Khái niệm thềm lục địa được nêu đầu tiên trong Tuyên bố ngày 28/9/1945 của Tổng thống Mỹ Truman tuyên bố về quyền tài phán của Mỹ đối với các nguồn tài nguyên thiên nhiên của đáy biển và lòng đất dưới đáy biển. Được ghi nhận trong Công ước Geneva 1958 về thềm lục địa Phán quyết của Tòa án quốc tế trong vụ tranh chấp về thềm lục địa biển Bắc năm 1969 (Continental shelf case).",43],["i","lb44_1.jpg",44,1046,693],["p",103,"Thềm lục địa pháp lý Thềm lục địa của quốc gia ven biển bao gồm đáy biển và lòng đất dưới đáy biển nằm bên ngoài lãnh hải của quốc gia ven biển kéo dài cho đến bờ ngoài của rìa lục địa hoặc đến cách đường cơ sở dùng để tính chiều rộng lãnh hải là 200 hải lý khi bờ ngoài của rìa lục địa ở khoảng cách gần hơn. Trong trường hợp bờ ngoài của rìa lục địa kéo dài vượt quá 200 hải lý tính từ đường cơ sở thì thềm lục địa của quốc gia ven biển cũng không được vượt quá 350 hải lý tính từ đường cơ sở hoặc không được vượt quá 100 hải lý tính từ đường đẳng sâu 2500m”",44],["p",67,"(Điều 76, Công ước 1982).",44],["i","lb44_2.jpg",44,817,518],["p",103,"Quyền và nghĩa vụ của quốc gia ven biển Thực hiện các quyền chủ quyền đối với thềm lục địa trong việc thăm dò, khai thác các tài nguyên thiên nhiên (Điều 77) Đặc quyền cho phép và điều chỉnh việc khoan ở thềm lục địa với bất kỳ mục đích nào.",45],["p",67,"(Điều 81) Tiến hành hoặc áp dụng các biện pháp thích hợp để bảo vệ môi trường Xây dựng, cho phép và quy định thể thức, điều kiện xây dựng, khai thác, sử dụng các đảo nhân tạo (Điều 80) Có quyền tài phán đối với dây cáp và ống dẫn được đặt hoặc sử dụng trong khuôn khổ của việc thăm dò thềm lục địa của mình, hoặc của việc khai thác các đảo nhân tạo, các thiết bị hay công trình thuộc quyền tài phán của quốc gia này. (Điều 79, Khoản 4).",45],["p",103,"Nghĩa vụ của nước ven biển Không được cản trở các quyền tự do của các quốc gia khác trong vùng nước phía trên và vùng trời phía trên vùng nước đó. (Điều 78). Không được cản trở các quốc gia khác đặt dây cáp và ống dẫn ngầm trên thềm lục địa trừ trường hợp để ngăn ngừa và hạn chế ô nhiễm do ống dẫn ngầm gây ra.( Điều 79) Quốc gia ven biển khai thác các tài nguyên thiên nhiên nằm ngoài 200 hải lý kể từ đường cơ sở thì phải nộp các khoản đóng góp bằng tiền hoặc hiện vật. (Điều 82).",45],["p",103,"Các vấn đề bảo vệ mt biển Nghề đánh bắt cá là nghề quan trọng để cung cấp thực phẩm cho con người Chủ yếu diễn ra hoạt động trên mt biển Ảnh hưởng đến môi trường biển hoặc hiện tượng khí hậu tiêu cựcVấn đề bảo vệ môi trường biển. Hoạt động lưu chuyển hàng hóa chủ yếu vẫn diễn ra trên đường biển Sự thay đổi khí hậu.",45],["p",103,"1967 có vụ tràn dầu, các quốc gia đã rút kinh nghiệm nên đã thảo thuận CƯ 1982 phần XII để xác định nguồn gây ô nhiễm. Đối vs tàu chạy bằng năng lượng hạt nhân, phóng xạ hay chất thải nguy hại thì quốc gia có quyền ngăn lại kiểm tra trước khi nó “đi qua không gây hại” Mang tài liệu để chứng minh nguồn gốc, để quốc gia nắm rõ đó là chất gì vì nếu chất thải tràn ra thì họ có thể khắc phục ngay chứ k cần tìm hiểu ngay từ đầu r mới tìm cách khắc phục.",45],["p",67,"=> thông qua cơ chế CƯ 1982 đã có sự hợp tác vĩ mô",45],["p",67,"Các nguồn gây ô nhiễm",45],["p",85,"- Đất liền 207: xả trực tiếp chất thải lỏng, rắn chưa qua xử lý",45],["p",85,"- Tàu thuyền 211: nạo vét, sơn sửa, rò rỉ, tai nạn, tràn dầu, sử dụng hóa chất rên tàu, cũng phát thải khí thải",46],["p",85,"- Không khí 212:",46],["p",67,"… Ô nhiễm từ đất liền Hầu hết các vấn đề gây ô nhiễm hiện nay thì thường xuất phát từ đất liền và thường từ chất thải của con người Gồm chất thải rắn, lỏng. Thường là chất thải k qua xử lý được đổ ra sông r đổ ra biển, nếu như chất thải rắn thì chưa phân rải được thì nó sẽ gây ảnh hưởng nghiêm trọng với mt biển đó Rác thải ven biển quá nhiều có thể ảnh hưởng đến du lịch, hoặc thông thường hoạt động khai thác hải sản, khai thác muối sẽ dùng nước biển ven bờ, mà do ô nhiễm thì cũng sẽ ảnh hưởng đến chất lượng của các sản phẩm này (muối biển hiện tại sẽ k còn hoàn toàn là tinh khiết khi nó bị nhiễm các hạt vi nhựa trong đó)",46],["p",67,"=> sẽ quy định về trách nhiệm của các quốc gia ven biển hoặc các nước có cảng",46],["p",103,"Ô nhiễm từ tàu thuyền Hoạt động của các tàu thuyền đều có thể gây ô nhiễm mt biển => khi tàu đi trên biển thì có các hoạt động, các hoạt động này sẽ có các chất thải được xả trực tiếp ra biển Tàu đắm, tràn dầu,... khí thải nhà kính đi lại nhiều thì cũng khiến nước biển nóng lên",46],["p",103,"Ô nhiễm từ không khi Có thể bao gồm:",46],["p",85,"● Những hoạt động liên quan đến tàu thuyền đi lại trên biển",46],["p",85,"● Các loại khí thải",46],["p",85,"● Vấn đề về phát thải khí thải cacbonic trong mt biển Những trường hợp các tàu rủi ro gây tràn dầu thì nước của tàu đó cũng phải có trách nhiệm phối hợp với nước ven biển",46]],"pg":[43,46]},{"h":"2. ĐẢO NHÂN TẠO VÀ THIẾT BỊ CÔNG TRÌNH","lv":3,"b":[],"pg":[58,58]},{"h":"2.1. Đảo nhân tạo","lv":3,"b":[["p",102,"Khái niệm ĐNT là 1 nền tảng cố định vĩnh viễn hoặc tạm thời do con người tạo nên Đặc điểm",58],["p",157,"+ Là công trình nhân tạo",58],["p",157,"+ Xây dựng cố định vĩnh viễn trên nền của đáy biển bằng các vật liệu tự nhiên như đất đá cát hoặc bê tông",58],["p",157,"+ Không thể di dời, di chuyển được",58],["p",157,"+ Được bao quanh bởi nước và thường xuyên nổi trên biển khi thủy triều lên cao",58],["p",157,"+ Là nơi sinh sống của dân cư hoặc sử dụng nhằm mục đích phát triển kinh tế (thăm dò, khai thác tài nguyên, tìm kiếm, cứu hộ, cứu nạn, dự báo thời tiết, sân bay, bến cảng…)",58],["p",157,"+ Không có các vùng biển mà chỉ có vùng an toàn tối đa 500m tính từ mép ngoài của đảo (Điều 60 Khoản 5)",58],["p",102,"Quy chế pháp lý Nội thủy lãnh hải Vùng đặc quyền kinh tế, thềm lục địa Biển quốc tế - vùng LƯU Ý: Điều 60 khoản 8 Điều 60 Khoản 8: Các đảo nhân tạo, các thiết bị và công trình không được hưởng quy chế của các đảo. Chúng không có lãnh hải riêng và sự có mặt của chúng không có tác động gì đối với việc hoạch định ranh giới lãnh hải, vùng đặc quyền về kinh tế hoặc thềm lục địa. Vùng an toàn của đảo nhân tạo là 500m tính từ mét ngoài nhô ra xa nhất của đảo nhân tạo. ( không được mở rộng chủ quyền, quyền tài phán của mình vượt quá phạm vi này) Đảo nhân tạo dù được xây dựng quy mô như thế nào, nhằm mục đích gì thì nó cũng không có quy chế pháp lý tương tự như đảo tự nhiên",58],["i","lb59_1.jpg",59,893,676],["p",102,"Khi xây dựng đảo nhân tạo thì các vấn đề phát sinh trên đảo đó thì thuộc quyền tài phán của quốc gia xây dựng đảo nhân tạo đó",59]],"pg":[58,59]},{"h":"ĐẶC ĐIỂM CỦA ĐẢO NHÂN TẠO","lv":2,"b":[["p",102,"UNCLOS k có định nghĩa đảo nhân tạo là gì mà chỉ nêu ra đặc điểm của nó DƯỚI BIỂN THÌ Chỉ có 1 vùng an toàn rộng 500m tính từ ngoài nhô ra ca nhất của đảo (k được mở rộng chủ quyền, quyền tài phán)",59]],"pg":[59,59]},{"h":"2.2. Thiết bị công trình","lv":3,"b":[["p",102,"“Công trình” (installation): là “bất kỳ cấu trúc cố định hoặc nổi và bất kỳ phần gắn liền nào của nó được sử dụng vào các hoạt động:",59],["p",103,"(i) các bộ phận thăm dò ngoài khơi cố định hoặc di động;",59],["p",103,"(ii) các bộ phận sản xuất bao gồm các bộ phận có vị trí động;",59],["p",103,"(iii) các hệ thống kho bãi ngoài khơi bao gồm các tàu thuyền sử dụng cho mục đích đó;",59],["p",103,"(iv) các cảng phục vụ việc bốc dỡ và hệ thống vận chuyển các sản phẩm được chiết xuất như các ống dẫn ngầm;",59],["p",103,"(v) hệ thống máy móc gắn liền với chung và các thiết bị nhằm mục đích bốc xếp, sản xuất, lưu trữ và tiêu hủy các chất được lấy lên từ đáy biển và lòng đất dưới đáy biển",59],["p",102,"(Nghị định thư 1994 về Bảo vệ Địa Trung Hải chống lại ô nhiễm do việc thăm dò và khai thác trên thềm lục địa, đáy biển và lòng đất dưới thềm lục địa)",59],["p",85,"Hệ thống kho bãi: lưu trữ khoáng sản, dầu mỏ được hút lên",60],["p",85,"Tất cả công trình nối kết hợp với nhau dể khai thác, sản xuất để hút khoáng sản, dấu",60],["p",103,"mỏ để hút lên….",60],["p",85,"Nhưng thiết bị công trình nhằm mục đích khai thác, sản xuất đầy biển, thêm lục địa và",60],["p",103,"lòng đất dưới thềm lục địa mà thôi",60],["p",103,"Chỉ sử dụng trong việc khai thác dưới đáy biển như giàn khoan, các bộ phận thăm dò; hệ thống sản xuất như mũi khoan. Thường liên tưởng đến các giàn khoan, có thể gắn cố định dưới đáy biển hoặc các tàu thăm dò, hệ thống kho bãi ngoài khơi.",60],["p",102,"Đặc điểm Là các công trình và thiết bị do con người xây dựng, lắp đặt và sử dụng trên biển",60],["p",85,"● Vd: các giàn khoan (di động hoặc không)",60],["p",85,"+ Có sự gắn kết vật chất với đáy biển một cách trực tiếp hoặc gián tiếp, ổn định hoặc tạm thời",60],["p",85,"+ Có thể cố định hoặc di động",60],["p",85,"+ Có thể được lắp đặt trên đất liền, ven bờ hoặc ngoài khơi",60],["p",85,"+ Có quy chế pháp lý điều chỉnh theo pháp luật quốc gia ven biển và pháp luật quốc tế",60],["p",85,"+ Nhằm nhiều mục đích khác nhau, trong đó chủ yếu là vì mục đích kinh tế, dân sự",60],["p",67,"Có thể là mục đích quân sự nữa, có thể điều chỉnh theo pháp luật quốc gia ven biển, pháp luật quốc tế",60],["p",85,"VD: dàn khoang gắn cố định trực tiếp cũng có thể dàn khoang di động ( TQ đưa dàn",60],["p",103,"khoang 981 là dàn khoang vào VN)",60],["p",102,"Quy chế pháp lý Đối với quốc gia ven biển",60],["p",103,"-Trong nội thủy và lãnh hải (Điều 21(1)(b), 25(2))",60],["p",102,"Quốc gia ven biển có quyền tài phán. Mọi hoạt động khai thác, nghiên cứu,… tài nguyên thiên nhiên là của quốc gia ven biển Bất kỳ hoạt độn lắp đặt các thiết bị công trình, …thì quốc gia ven biển có quyền đàm phán Nếu xảy ra vấn dề quy phạm khi lắp đặt,… thì cũng thuộc quyền quyết định của quốc gia ven biển",60],["p",103,"-Trong vùng đặc quyền kinh tế và thềm lục địa",60],["p",103,"-Quyền tài phán về việc lắp đặt và sử dụng (Điều 56(1)(b), 60(1)…(7); 79(4) và 80,…)",60],["p",103,"-Quyền đối với vấn đề bảo vệ môi trường biển (Đ208)",61],["p",103,"-Quyền đối với vấn đề nghiên cứu khoa học biển (Đ246)",61],["p",103,"Đặc quyền kinh tế không nằm trong chủ quyền quốc gia nhưng ít nhất vẫn đụn chạm dến tài nguyên của họ nên vẫn phải xin phép",61],["p",103,"Nước ven biển có quyền cho phép hoặc k cho phép,",61],["p",67,"Đối với quốc gia khác Nghĩa vụ tôn trọng đối với các quyền và nghĩa vụ của quốc gia ven biển Đảm bảo tôn trọng các quyền tự do biển cả Đối với đáy đại dương: thì phải có sự đồng ý cảu cơ quan quyền lực vùng",61],["p",85,"Đảo nhân taọ, thiết bị công trình không là căn cứ xác định tiếp giáp lãnh hải, đặc",61],["p",103,"quyền kinh tế,…",61],["p",67,"Trong vùng nội thủy, lãnh hải",63],["p",85,"- Quy định đối với tàu thuyền nước ngoài:",63],["p",85,"- - đánh bắt hải sản vi phạm quyền đi qua k gây hại Đ19/1/i",63],["p",85,"- Quốc gia ven biển có quyền ngăn ngừa những vi phạm các luật và quy định của mình liên quan đến việc đánh bắt Đ21.1.e",63],["p",103,"Ngoài cảnh sát biển thì nước ta còn có các đội kiểm ngư hỗ trợ việc này.",63],["p",103,"K chỉ để ngư dân đánh bắt kiếm lời mà còn là cách thể hiện rằng VN có quyền ở vùng biển này nên nhà nước phải tích cực hỗ trợ các ngư dân đánh bắt",63],["p",67,"Việc đánh bắt cá tại các khu vực tại VN nhưng Trung Quốc lại ra các lệnh cấm đánh bắt cá",63],["p",103,"Hoạt động đánh bắt cá thì các quốc gia có thể tự mình đặt ra quy định để thực hiện dựa trên chủ quyền và quyền chủ quyền của mình. Các tàu thuyền có thể đánh bắt trên vùng biển của quốc gia khác, xảy ra khi có sự cấp phép của quốc gia nơi có vùng biển đó chứ k phải là thứ đơn phương mà quốc gia khác có thể thực hiện Đánh bắt ở vùng nội thủy (mình quốc gia được toàn quyền quy định vi tính tuyệt đối) và lãnh hải (vì tính hoàn toàn và đầy đủ nên chỉ có việc đi qua k gây hại chứ còn việc đánh bắt vẫn có sự toàn quyền)",63],["p",67,"Các quốc gia có các vùng biển thuộc chủ quyền => quy định trong pháp luật quốc gia",63],["p",85,"● Đánh bắt cá",63],["p",85,"● Hoạt động đánh bắt cá được tiến hành ở:",63],["p",121,"○ Vùng biển thuộc chủ quyền",63],["p",121,"○ Vùng biển thuộc quyền chủ quyền",63],["p",121,"○ Vùng biển quốc tế Tính chất chủ quyền của nội thủy là tuyệt đối Nước lãnh hải => thuộc quyền hoàn toàn và đầy đủ",63],["p",103,"Tàu đó k có sự đánh bắt hải sản mà k có sự đồng ý của các quốc gia ven biển Các tàu kiểm sát biển hoặc tàu kiểm ngư thị phải theo dõi những tàu có dấu hiệu nghi ngờ những tàu khác ở đây Ngoài việc quy định về khu vực cấm đánh bắt thì cũng có thể quy định về mùa vụ cấm đánh bắt Đ19 CƯ 1982: Tàu có hđ đánh bắt hải sản mà k có sự đồng ý Nếu có ranh giới giáp ranh giữa hai vùng biển thì hai bên có sự thỏa thuận để cùng đánh bắt. Có nơi quy định về mùa vụ đánh bắt.",63],["p",103,"Vấn đề đánh bắt cá",64],["p",85,"● Quốc gia ven biển có chủ quyền hoàn toàn và trọn vẹn đối với các nguồn hải sản ở ĐQKT.",64],["p",85,"● Tàu thuyền nước ngoài muốn đánh bắt cá ở vùng đặc quyền kinh tế phải xin phép, và tuân thủ các điều kiện do quốc gia ven biển đặt ra.",64],["p",85,"● Nếu quốc gia ven biển có khả năng kỹ thuật đánh bắt hết toàn bộ sản lượng cá thì có thể: giữ độc quyền khai thác; từ chối không cho các nước khác tham gia khai thác.",64],["p",85,"● Quốc gia ven biển có quyền quy định về các vấn đề sau:",64],["p",85,"● Việc cấp giấy phép",64],["p",85,"● Thuế",64],["p",85,"● Chủng loại đánh bắt, số lượng đánh bắt",64],["p",85,"● Mùa vụ và khu vực đánh bắt",64],["p",85,"● Tuổi, cỡ và các loại sinh vật có thể được đánh bắt (Khoản 4 Điều 62)",64],["p",67,"Đăng ký đánh bắt ở đâu thì chỉ được đánh bắt ở đó theo luật VN, nếu cùng biển đó chung thì có thể thỏa thuận",64],["p",103,"Tài nguyên không sinh vật Bao gồm tài nguyên không sinh vật của vùng nước bên trên đáy biển, đáy biển và lòng đất dưới đáy biển. QGVB tự mình khai thác hoặc cho phép các quốc gia khác khai thác dưới sự kiểm soát của mình",64],["p",103,"Các hoạt động khác nhằm mục đích kinh tế Bất kỳ hoạt động nào nhằm thăm dò, khai thác vùng này vì mục đích kinh tế Ví dụ: sản xuất năng lượng từ nước, hải lưu và gió…",64],["p",103,"Quyền tài phán",65],["i","lb65_1.jpg",65,1099,526],["p",103,"Quyền của quốc gia không có biển và bất lợi về địa lý Các quốc gia không có biển hoặc bất lợi về địa lý có quyền tiến hành các hoạt động khai thác số dư của khối lượng cá cho phép đánh bắt trong vùng đặc quyền kinh tế của quốc gia ven biển, thông qua các điều ước quốc tế hoặc các thoả thuận có liên quan. (Điều 69, 70 Công ước).",65],["i","lb66_1.jpg",66,1099,801]],"pg":[59,66]}]},{"t":"Khu vực sử dụng chung","s":"Biển quốc tế, Vùng (đáy đại dương); kênh đào và eo biển quốc tế","pg":"tr.46–56, 61–63","g":[{"h":"Sơ đồ tóm tắt chương","lv":2,"b":[["f","sd_lb4.svg",720,440,"Sơ đồ: khu vực sử dụng chung"],["p",72,"Sơ đồ tự lập từ bài giảng và UNCLOS 1982, chưa đối chiếu toàn văn.",0]]},{"h":"A. BIỂN QUỐC TẾ","lv":2,"b":[],"pg":[46,46]},{"h":"3.2.1.1. Khái niệm","lv":3,"b":[["p",102,"Biển quốc tế (Biển cả) là những vùng biển không nằm trong vùng đặc quyền kinh tế, lãnh hải, nội thuỷ của một QG nào cũng như không nằm trong vùng nước quần đảo của QG quần đảo. (Trích phần VII, mục 1, Điều 86, UNCLOS 1982)",46],["p",72,"Vùng biển quốc tế là tất cả các vùng biển nằm ngoài vùng đặc quyền kinh tế của",46],["p",72,"Việt Nam và các quốc gia khác, không bao gồm đáy biển và lòng đất dưới đáy biển. (khoản 2 Điều 3 Luật Biển 2012)",46],["p",103,"Quy chế pháp lý Nguyên tắc tự do biển cả (Đ.87 UNCLOS)",47],["p",102,"BQT được để ngỏ cho tất cả các QG có biển hay không có biển đều bình đẳng và tự do trong việc sử dụng biển. Điều 89 UNCLOS 1982: Không một quốc gia nào có thể đòi đặt 1 cách bất hợp pháp 1 bộ phận nào đó của biển cả thuộc vào chủ quyền của mình",47],["i","lb47_1.jpg",47,761,654],["p",103,"Tính bất hợp pháp của những yêu sách về chủ quyền đối với biển cả Đ89. Tính bất hợp pháp của những yếu sách về chủ quyền đối với biển cả “Không 1 quốc gia nào có thể đòi đặt 1 cách hợp pháp 1 bộ phận nào đó của biển cả thuộc vào chủ quyền của mình”",47],["p",103,"Các nước có TLĐ rộng 350 hải lý thì phía dưới đáy biển có thể giao với vùng biển quốc tế khi xét đến yếu tố như đường đẳng sâu.",47],["i","lb48_1.jpg",48,899,587],["p",102,"6 quyền tự do cơ bản:",48],["p",85,"- Tự do hàng hải là tự do tối đa: vận tốc, tuyến đường, chỉ cần k đụng chạm ai là được",48],["p",85,"- Hàng không: vùng trời quốc tế, các phương tiện bay đều có quyền đi vào",48],["p",85,"- Tự do lắp đặt: về cáp quang, đường ống vận chuyển dầu khí, … nếu có liên quan đến đáy đại dương thì phải liên kết với cơ quan quyền lực vùng, ngoài ra k đc đụng chạm với công trình đã tồn tại từ trước",48],["p",85,"- Đánh bắt: hợp lý, k mang tính chất tận diệt",48],["p",85,"- Nghiên cứu khoa học: k phải xin phép nhưng phải tuân thủ quy định chung của công ước Theo K. 2 Đ. 87, mỗi quốc gia khi thực hiện các quyền tự do này phải :",48],["p",121,"- tính đến lợi ích của việc thực hiện quyền tự do trên biển cả của các quốc gia khác,",48],["p",121,"- các quyền được Công ước thừa nhận liên quan đến hoạt động trong “Vùng”.",48],["p",85,"- Theo Đ. 88 thì biển cả được sử dụng vào những mục đích hòa bình. Quy chế pháp lý của tàu thuyền hoạt động trên biển quốc tế Quy định đối với tàu thuyền",48],["p",85,"• Tàu thuyền có quốc tịch của quốc gia mà chúng được phép treo cờ (Đ90,91)",48],["p",85,"• Tất cả các tầu thuyền trên Biển quốc tế đều có địa vị pháp lý ngang nhau.",48],["p",85,"• Chỉ được phép hoạt động dưới cờ của một quốc gia nhất định.",48],["p",85,"• Không được thay đổi cờ trong một chuyến đi hay trong một dịp đậu lại,",48],["p",85,"• Ngoại lệ: chuyển giao thật sự quyền sở hữu hay có thay đổi đăng ký (K. 1 Đ. 92)",48],["p",85,"• Chỉ chịu sự tài phán của quốc gia mà tàu mang cờ Quyền và nghĩa vụ của quốc gia mà tàu treo cờ",48],["p",85,"• Quyền quy định các điều kiện cho phép tàu mang quốc tịch của nước mình (Đ. 91)",48],["p",85,"• Thực sự thực hiện thẩm quyền tài phán và kiểm soát đối với tàu mang cờ (Đ. 94. 1)",48],["p",85,"• Thực hiện các biện pháp cần thiết đối với tàu mang cờ để đảm bảo an toàn trên biển (Đ. 94. 3,4,5)",49],["p",67,"Quyền miễn trừ của tàu thuyền : Đ95,96 UNCLOUS 1982.",49],["p",85,"• Tàu quân sự",49],["p",85,"• Tàu nhà nước sử dụng vào mục đích phi thương mại",49],["p",67,"Nguyên tắc quyền tài phán của nhà nước mà tàu mang quốc tịch",49],["p",85,"- Điều 91, 92, 94, 97 UNCLOS 1982",49],["p",85,"- Điều 3, Điều 56 Luật Hàng hải 2015",49]],"pg":[46,49]},{"h":"- BLHS 2015 (2017)","lv":2,"b":[["p",85,"Tàu chiến, tàu nhà nước phi thương mại hưởng quyền miễn trừ hoàn toàn về tài",49],["p",85,"phán của bất kỳ quốc gia nào ngoài quốc gia tàu mang cờ: Điều 95, 96",49]],"pg":[49,49]},{"h":"UNCLOS 1982","lv":2,"b":[["p",85,"Nghĩa vụ giúp đỡ: Điều 98 UNCLOS",49],["p",103,"Hợp tác để ngăn ngừa và trừng trị hành vi chuyên chở nô lệ ,",49],["p",103,"buôn bán ma túy , phát sóng không được phép trên biển quốc",49],["p",103,"tế",49],["p",72,"- Mọi nô lệ ẩn náu ở trên một chiếc tàu đều được tự do ngay tức khắc: Điều 99",49],["p",72,"- Điều 100 – Điều 107 UNCLOS 1982: quy định các vấn đề pháp lý liên quan đến",49],["p",72,"việc trấn áp hành vi cướp biển",49],["p",90,"✓ Khi tàu chiến, tàu nhà nước đang bị thủy thủ đoàn/phi hành đoàn chiếm và",49],["p",108,"gây ra hành vi cướp biển: được coi là phương tiện cướp biển cho đến khi nào",49],["p",108,"nó còn ở dưới quyền kiểm soát của người gây ra hành vi cướp biển. (Đ",49],["p",108,"102,103). Như vậy, sẽ xem đây là hành động của tàu, phương tiện bay tư",49],["p",108,"nhân, không được hưởng quyền miễn trừ hoàn toàn.",49],["p",90,"✓ Điều kiện thi hành bắt giữ phương tiện cướp biển: tàu chiến, phương tiện",49],["p",108,"bay quân sự hoặc các phương tiện khác mang dấu hiệu chứng tỏ rõ ràng là",49],["p",108,"một CQNN và được tiến hành nhiệm vụ này. (Điều 107)",49],["p",90,"✓ Nghĩa vụ hợp tác chống buôn bán ma túy: Điều 108",49],["p",90,"✓ Nghĩa vụ hợp tác để trấn áp hành vi phát sóng trái phép",49],["p",72,"- Nghĩa vụ giúp đỡ người tị nạn trên biển (Điều 98)",50],["p",72,"- Nghĩa vụ đối với dây cáp hay ống dẫn ngầm ở biển quốc tế (Điều 87, Điều 112,",50],["p",72,"113, 114, 115)",50],["p",72,"- Nghĩa vụ tuân thủ phần VI (Điều 87)",50],["p",67,"Một số vấn đề trên biển quốc tế",50],["p",85,"● Tàu không quốc tịch",50],["p",85,"● Chuyên chở nô lệ (Đ. 99)",50],["p",85,"● Buôn bán chất ma túy (Đ. 108)",50],["p",85,"● Phát sóng trái phép (Đ. 109)",50],["p",121,"○ Các cuộc phát thanh và vô tuyến truyền hình nhằm vào quảng đại quần chúng; phát đi từ một chiếc tàu hay thiết bị ở biển cả vi phạm các quy chế quốc tế (trừ việc phát các tín hiệu cấp cứu)",50],["p",85,"- Những quốc gia có quyền tài phán",50],["p",121,"○ Quốc gia mà chiếc tàu phát sóng mang cờ",50],["p",121,"○ Quốc gia nơi thiết bị đăng ký",50],["p",121,"○ Quốc gia mà người đó là công dân",50],["p",121,"○ Quốc gia mà ở đó thu được các cuộc phát sóng",50],["p",121,"○ Quốc gia có các đài thông tin, vô tuyến được phép đã bị nhiễu do các cuộc phát sóng đó",50],["p",85,"● Cướp biển (Đ. 100-105)",50],["p",121,"○ Hành động trái phép dùng bạo lực hoặc bắt giữ, hoặc cướp phá chống lại một tàu hoặc phương tiện bay, người hoặc của cải trên tàu và phương tiện bay đó (Điểm a, Điều 101);",50],["p",121,"○ Hành động tham gia có tính chất tự nguyện vào việc sử dụng một chiếc tàu hay một phương tiện bay, khi người tham gia biết từ những sự việc rằng chiếc tàu hay phương tiện bay đó là một tàu hay phương tiện bay cướp biển (Điểm b, Điều 101);",50],["p",121,"○ Hành động nhằm mục đích xúi giục người khác phạm những hành động xác định ở các điểm nêu trên hay phạm phải với chủ định là dễ dàng cho hành động đó.",50],["p",139,"(Điểm c, Điều 101).",50],["p",121,"○ Địa điểm xảy ra hành vi: vùng biển quốc tế hoặc những khu vực không thuộc thẩm quyền tài phán của bất kỳ quốc gia quốc gia nào.",50],["p",103,"Hạn chế của định nghĩa theo UNCLOS 1982",50],["p",85,"● Chỉ áp dụng đối với vùng biển quốc tế.",50],["p",85,"● Việc chuẩn bị phạm tội đã cấu thành tội phạm hay chưa?",50],["p",85,"● Mục đích cướp biển có phải là dấu hiệu bắt buộc hay không?",50],["p",102,"Tội cướp biển phải diễn ra ở trên vùng biển quốc tế vì các quốc gia có quy định về tội danh khác nhau (lỗ hổng pháp luật)",50],["p",102,"Cướp có vũ trang chống lại tàu thuyền với cướp biển có tính chất giống nhau nhưng vũ trang thì diễn ra ở vùng biển tài phán Các tòa án của quốc gia bắt giữ có thể công bố các hình phạt cũng như các biện pháp áp dụng đối với tàu, oh tiện bay hay của cải,trừ những người lương thiện trong cuộc (có thể trực tiếp trừng trị)",51],["p",103,"Định nghĩa của ReCAAP 2004 Điều 1 ReCAAP 2004 ngoài quy định về cướp biển tương tự như UNCLOS 1982 còn bổ sung thêm hành vi “cướp có vũ trang chống lại tàu thuyền” với bản chất giống với cướp biển, chỉ khác là địa điểm xảy ra hành vi có thể ở cả vùng biển thuộc quyền tài phán của các quốc gia, Hành động cướp biển của một tàu chiến hay một tàu, phương tiện bay nhà nước hay phi hành đoàn nổi loạn làm chủ hành động của tàu hay phương tiện bay tư nhân.",51],["p",103,"Chủ thể thực hiện việc bắt giữ:",51],["p",121,"- Tàu chiến hay phương tiện bay quân sự,",51],["p",121,"- Tàu thuyền hay phương tiện bay khác của một cơ quan Nhà nước và được giao nhiệm vụ này",51],["p",103,"Nghĩa vụ chống cướp biển (Điều 105) Mọi quốc gia ở biển cả, hay ở bất cứ nơi nào khác không thuộc quyền tài phán của bất kỳ quốc gia nào, đều có thể bắt giữ: Chiếc tàu hay một phương tiện bay đã trở thành cướp biển, Chiếc tàu hay một phương tiện bay bị chiếm đoạt sau một hành động cướp biển và đang nằm trong tay bọn cướp biển, và Người và tài sản ở trên con tàu hay phương tiện bay đó.",51],["p",139,"Các tòa án của quốc gia bắt giữ có thể công bố các hình phạt cũng như các biện pháp áp dụng đối với chiếc tàu, phương tiện bay hay của cải, trừ những người lương thiện trong cuộc.",51],["p",85,"● Quyền khám xét (Đ. 110)",51],["p",121,"○ Tàu quân sự có quyền khám xét một tàu nước ngoài nếu chiếc tàu này không phải là tàu được hưởng quyền miễn khi có những lý do đúng đắn để nghi ngờ rằng tàu đó:",51],["p",157,"■ Tiến hành cướp biển",51],["p",157,"■ Chuyên chở nô lệ:",51],["p",157,"■ phát sóng không được phép: Đ109 Các cuộc phát thanh vô tuyến truyền hình nhằm vào quảng đại quần chúng phát đi từ một chiếc tàu hay thiết bị ở biển cả vi phạm các quy chế quốc tế (trừ việc phát các tín hiệu cấp cứu)",51],["p",193,"• là cuộc phát thanh, vô tuyến truyền hình ở các tần số khác nhau, chỉ trong phạm vi giới hạn của giấy phép của thiết bị đó . các quốc gia phải giám sát việc phát sống ảnh hưởng tới hòa bình, an ninh quốc phòng của các quốc gia ( đ 109) => nếu dẫn tới hậu qảu nghiêm trọng : phá đi hạ tầng của các quốc giá, tuyền ruyền gây ảnh hưởng tới an ninh quốc phòng của các quốc gia nào đó",51],["p",193,"● Có thể phá các cơ sở hạ tầng, sóng rađa",52],["p",193,"● Tuyên truyền các thông tin bất lợi cho các quốc gia liên quan",52],["p",157,"■ Không có quốc tịch: : không treo cờ, dấu hiệu đăgf ký trên tàu không xác định được . phải đăng ký sở đăng bạ thế giới. nếu có dấu hiệu về vấn đề quốc tịch ( ký hiệu không đúng về thông tin mà tổ chức hàng hải thế giới cung cấp )",52],["p",157,"■ Cùng quốc tịch với chiếc tàu chiến nhưng treo cờ nước ngoài hay từ chối treo cờ của mình",52],["p",121,"○ Thủy thủ trên tàu nổi loạn thì nó được coi là hành vi tư nhân (thuyền tư nhân)\\",52],["p",121,"○ Tàu quân sự chỉ có thể khám xét các tàu dân sự",52],["p",157,"■ Mặc dù tất cả tàu thuyền các nước đều có địa vị như nhau, nhưng tàu quan sự được troa quyền nhiều hơn tàu dân sự ( miễn trừ, quyền khám xét tàu nước ngoài,…)",52],["p",157,"■ Tàu quân sự chỉ khám xét được tàu dân sự ( tàu dân sự bất kỳ nước nào )",52],["p",85,"● Quyền truy đuổi (Đ. 111 UNCLOS và Đ41 LBVN)",52],["p",121,"○ Tiến hành khi quốc gia ven biển có lý do đúng đắn cho rằng chiếc tàu này đã vi phạm các luật và quy định của quốc gia đó",52],["p",157,"■ nếu ở biển quốc tế thì phải xác định nó xâm phạm lợi ích kinh tế, đăc quyền của các quốc gia ven biển",52],["p",121,"○ Hành vi được cho là vi phạm luật pháp của 1 quốc gia thì phải diễn ra ở nội thủy, lãnh hải, tiếp giáp lãnh hải. Vậy nên khi tàu vi phạm chạy ra khỏi lãnh hải thì quyền truy đuổi sẽ chỉ là của tàu công vụ.",52],["p",157,"■ Trong vùng tiếp giáp lãnh hải, lãnh hải, nội thủy của quốc gia đó",52],["p",157,"■ Đụng chạm đến lợi ích kinh tế với qg ven biển hoặc những đặc quyền kinh tế của quốc gia đó",52],["p",157,"■ Phải chứng minh nó ảnh hưởng thế nào với các quốc gia ven biển",52],["p",121,"○ Quyền truy đuổi chỉ có thể thực hiện bởi:",52],["p",157,"■ Các tàu quân sự",52],["p",157,"■ Các phương tiện bay quân sự: có thể kết hợp với các tàu thực hiện quyền truy đuổi.",52],["p",157,"■ Các tàu hay phương tiện bay của cơ quan Nhà nước và được phép làm việc này",53],["p",85,"● Vd: một số tàu cảnh sát có thể được giao trách nhiệm truy đuổi, tàu mang tính chất ( tàu hải gián : k phải tàu quân đội mà nó chỉ có quyền gián sát biển nhưng nó có thể được giao trách nhiệm truy đuổi)",53],["p",121,"○ Việc truy đuổi được tiến hành khi tàu nước ngoài (một trong những chiếc xuồng của nó):",53],["p",144,"+ Đang ở trong nội thủy hay vùng nước quần đảo;",53],["p",144,"+ Đang ở trong lãnh hải hay tiếp giáp lãnh hải của quốc gia truy đuổi",53],["p",144,"+ ở trong các vùng đặc quyền kinh tế với điều kiện là nó vi phạm trong đặc quyền kinh tế",53],["p",144,"+ quyền truy đuổi xâuts phát từ lãnh thổ quốc gia : có thẻ bắt nếu nó vượt qua lãnh hải, tiếp giáp lãnh hải thì quyền truy đuổi vẫn có quyền tiếp tục, truy đuổi phải được diễn ra một cách liên tục",53],["p",144,"+ Nếu các tàu thực hiện trong nội thủy thì sau khi ra khỏi lãnh hải thì vẫn được phép thực hiện việc truy đuổi dó vì nguyên tắc phải liên tục không ngắt quãng (có thể thay phiên nhau)",53],["p",157,"o Việc truy đuổi không gián đoạn",53],["p",121,"○ Có thể do nhiều tàu, phương tiện bay thực hiện liên tục, không ngắt quãng; => các tàu phải tiến hành phối hợp tiếp nối với nhau để truy đuổi tàu đó. Tàu bên mình hết nguyên liệu dừng lại thì có tàu, phương tiện khác tiếp tục",53],["p",121,"Vd: hết nhiên liệu thì phải có tàu khác tiếp tục truy đuổi",53],["p",121,"○ Phương tiện bay truy đuổi phải liên tục đến khi có phương tiện bay khác tiếp tục việc truy đuổi",53],["p",121,"○ Việc truy đuổi nếu không gián đoạn thì có thể tiếp tục ở ngoài ranh giới lãnh hải hay tiếp giáp lãnh hải nếu chiếc tàu bị truy đuổi đã vi phạm các quy định của quốc gia ven biển áp dụng trong đặc quyền kinh tế hay thềm lục địa",53],["p",175,"Việc truy đuổi này vượt qua cảng biển quốc tế, thềm lục địa, đặc quyền kinh tế: có thể ra ngoài biên giới quốc gia. ( ra ngoài biển quốc tếò) nếu nó được tiến hành liên tục không ngắt quãng",53],["p",175,"Nếu nó đến lãnh hải quốc gia khác thì việc truy đuổi chấm dứt",53],["p",121,"○ Việc truy đuổi bắt đầu khi chiếc tàu truy đuổi, biết một cách chắc chắn rằng:",53],["p",157,"■ Chiếc tàu bị đuổi, hoặc một trong những chiếc xuồng của nó hoặc các phương tiện đi biển khác hoạt động thành tốp và dùng chiếc tàu bị truy đuổi làm tàu mẹ đang ở trong ranh giới của lãnh hải, tiếp giáp lãnh hải, đặc quyền kinh tế hay ở trên thềm lục địa",53],["p",157,"■ Việc truy đuổi tiến hành sau khi chiếc tàu truy đuổi đã phát tín hiệu nhìn hoặc nghe bắt nó dừng lại ở một cự ly cần thiết để chiếc tàu kia có thể nhận biết được",54],["p",157,"■ Việc truy đuổi chấm dứt khi chiếc tàu bị truy đuổi đi vào lãnh hải của quốc gia mà nó thuộc quyền hoặc đi vào lãnh hải của một quốc gia khác.",54],["p",157,"■ Quyền truy đuổi này có thể từ bất cứ con tàu nào, có thể tách từ tàu mẹ để chạy trốn",54]],"pg":[49,54]},{"h":"II , ĐÁY ĐẠI DƯƠNG","lv":2,"b":[["p",108,"1, Khái niệm",54],["p",72,"Điều 1 khoản 1 và phần XI UNCLOS 1982",54],["p",72,"Đáy đại dương là đáy biển và lòng đất dưới đáy biển nằm bên ngoài giới hạn thẩm",54],["p",72,"quyền tài phán của quốc gia.",54],["p",103,"2, Chế độ pháp lý đáy đại dương",54]],"pg":[54,54]},{"h":"Phần XI UNCLOS 1982 (Điều 136 – Điều 191)","lv":2,"b":[["p",72,"Điều 136: Di sản chung của loài người",54],["p",72,"Điều 137: Chế độ pháp lý của vùng và các tài nguyên của nó",54],["p",90,"✓ Không 1 quốc gia nào và không một tự nhiên nhân hay pháp nhân nào có thể",54],["p",108,"chiếm đoạt bất cứ 1 phần nào đó của vùng và tài nguyên của nó.",54],["p",90,"✓ Cơ quan quyền lực đáy đại dương (Điều 156 – Điều 185)",54],["p",72,"Điều 140: Lợi ích của loài người",54],["p",90,"✓ Các hoạt động trong vùng được tiến hành…. là vì lợi ích của toàn thể loài",54],["p",108,"người, không phụ thuộc vào vị trí của các quốc gia….",54],["p",90,"✓ Cơ quan quyền lực bảo đảm phân chia công bằng, trên cơ sở không phân",54],["p",108,"biệt đối xử…",54],["p",72,"Điều 141: Sử dụng vùng vào những mục đích hòa bình",54],["p",72,"Điều 143: Việc nghiên cứu khoa học biển",54],["p",72,"Các điều 145, 146, 147, 149",54]],"pg":[54,54]},{"h":"B. VÙNG","lv":2,"b":[["p",103,"Là toàn bộ đáy biển và lòng đất dưới đáy biển nằm bên ngoài các vùng biển thuộc quyền tài phán của quốc gia\" – đáy đại dương (K. 1 Đ. 1)",55]],"pg":[55,55]},{"h":"1. Quy chế pháp lý của Vùng","lv":3,"b":[["p",85,"● Vùng và tài nguyên của vùng là di sản chung của nhân loại: nhấn mạnh ở yếu tố này (cần được bảo tồn) k thể bị khai thác tự do",55],["p",85,"● Các quốc gia có biển hay không có biển hoàn toàn bình đẳng trong việc sử dụng và bảo vệ vùng. Đ 141",55],["p",85,"● Việc chiếm hữu hoặc áp đặt chủ quyền của bất kỳ quốc gia này đối với một phần hoặc toàn bộ vùng đều là bất hợp pháp (Điều 136, 137 UNCLOS 1982)",55],["p",85,"● Không một quốc gia nào có thể đòi hỏi thực hiện chủ quyền hay các quyền chủ quyền đối với một phần nào đó của vùng hoặc đối với tài nguyên của vùng đ 137 k1",55],["p",85,"● Các hoạt động trong vùng được tiến hành vì lợi ích của toàn thể loài người và vào mục đích hòa bình đ 140,141",55],["p",85,"● Tất cả các di vật khảo cổ và lịch sử được tìm thấy trong vùng đều được bảo tồn hay nhượng lại vì lợi ích của toàn thể loài người.",55],["p",85,"● Các hoạt động trong vùng cũng phải tôn trọng các quyền lợi chính đáng của quốc gia ven biển",55],["p",85,"● Việc thăm dò, khai thác tài nguyên của vùng được tiến hành thông qua một cơ quan quyền lực quốc tế – Cơ quan quyền lực Vùng.",55],["p",85,"● Cơ quan này bảo đảm những phân chia công bằng, trên cơ sở không phân biệt đối xử với những lợi ích tài chính và các lợi ích kinh tế khác do những hoạt động tiến hành trong vùng thông qua bộ máy của mình và định ra các quy tắc, thủ tục nhằm ngăn ngừa, hạn chế, chế ngự môi trường biển, bảo tồn các tài nguyên thiên nhiên.",55],["p",85,"● Sử dụng Vùng vì mục đích hòa bình (Điều 140, 141)",55],["p",102,"Hoạt động trong vùng chỉ được thực hiện vì mục đích hòa bình và vì mục đích của toàn thế loài người=> phục vụ cho sự phát triển của khoa học, bảo tồn các giá trị ls Các hoạt động trong vùng phải tôn trọng các quốc gia ven biển Nếu có đụng chạm đến đáy biển thì phải có sự thống nhất với cơ quan quyền lực vùng mới được coi là hợp pháp",55]],"pg":[55,55]},{"h":"2. Cơ quan quyền lực vùng","lv":3,"b":[["p",85,"● Cơ quan quyền lực vùng: cơ quan được thành lập theo quy định của phần XI Công ước. Tất cả các quốc gia thành viên của quốc gia thành viên đều là thành viên của cơ quan quyền lực vùng.",55],["p",85,"● Đại hội đồng",55],["p",85,"● Hội đồng",55],["p",85,"● Ban thư ký",56],["p",85,"● Xí nghiệp",56],["p",121,"- Việc thăm dò, khai thác tài nguyên của vùng được tiến hành thông qua một cơ quan quyền lực quốc tế – Cơ quan quyền lực Vùng.",56],["p",121,"- Cơ quan này bảo đảm những phân chia công bằng, trên cơ sở không phân biệt đối xử với những lợi ích tài chính và các lợi ích kinh tế khác do những hoạt động tiến hành trong vùng thông qua bộ máy của mình và định ra các quy tắc, thủ tục nhằm ngăn ngừa, hạn chế, chế ngự môi trường biển, bảo tồn các tài nguyên thiên Là tổ chức chuyên môn LHQ nhưng nó không là cơ quan trực thuộc của LHQ. Vì:",56],["p",85,"⇒ Nó hoạt động chuyên môn cụ thể, nó cam kết với lhq là thực hiện mục tiêu của lhq trong các lĩnh vực . nó thỏa thuận với lhq cùng thực hiện mục tiêu chung nào đó với lhq trong lĩnh vực cụ thể nào đó. Thường là thành viên của LHQ cũng là thành viên của tổ chức chuyên môn LHQ.",56],["p",72,"Đối với phân vùng, xí nghiệp hoặc tư nhân tham gia vào hoạt động kahi thác quản lý tài nguyên trong vùng có thể đưa ra vụ kiện tòa án quốc tế luật biển. Tòa án quốc tế luật biển cũng xét xử đối với tranh chấp trong vùng Xí nghiệp này là do cơ quan quyền lực vùng thành lập ra.",56]],"pg":[55,56]},{"h":"KÊNH ĐÀO QUỐC TẾ","lv":2,"b":[],"pg":[61,61]},{"h":"1. Đặc điểm","lv":3,"b":[["p",106,"Đặc điểm:",61],["p",67,"-Do con người tạo ra, nối liền các vùng biển dùng cho hàng hải quốc tế",61],["p",67,"-Thường nằm trên lãnh thổ của 1 quốc gia",61],["p",67,"-Do luật quốc gia hoặc các điều ước quốc tế quy định Nhưng khu vực do vị trí địa lý đặc biệt, eo đất hẹp nên xây đào để nối liền các vùng biển dành cho hàng hải.",61],["p",67,"K hoàn toàn đồng nhất với việc đi qua k gây hại.",61],["p",67,"Kênh đào Suez:",61],["p",85,"- Thuộc Ai Cập",61],["p",85,"- Nối địa trung hải với vịnh Suez (1 nhánh của biển đỏ)",61],["p",85,"- Chiều dài 195 km, sâu 16,5 -17m, rộng 120-150m, chỗ hẹp nhất 60m",61],["p",85,"- Khởi công xây dựng 25/4/1859",61],["p",85,"- Khánh thành 17/11/1869",61],["p",85,"- Đóng cửa 1 lần từ 1967-=1975",61],["p",85,"- Tàu chở dầu 250.000 trấn có thể qua lại",61],["p",85,"- Mở rộng năm 2014, rút ngắn thời gian đi qua từ 22-11 giờ.",61],["p",103,"Muốn đi qua thì ngoài không gây hại còn phải nộp các khoản phí để cơ quan có thẩm quyền thực hiện việc lưu thông hàng hải trên vùng đó có trật tự.",61],["p",103,"Kênh đào Panama Kênh đào Kiel",62]],"pg":[61,62]},{"h":"EO BIỂN QUỐC TẾ","lv":2,"b":[["p",67,"Bao gồm:",62],["p",103,"-Eo biển nằm giữa vùng biển của một hoặc hai quốc gia",62],["p",103,"-Eo biển nằm giữa các vùng biển quốc tế Eo biển nằm giữa biển quốc tế Các quốc gia xác định vùng biển xong rồi ( xác định đặc quyền kinh tế rồi) và đoạn hẹp ở giữa được coi là biển quốc tế => eo biển ở đó được coi là eo biển quốc tế",62],["p",103,"Có quy chế đặc biệt riêng, nó có thể nằm giữa vùng biển của hai nước hoặc nằm giữa vùng biển của một nước. Điều này xảy ra tùy vào độ rộng của vùng nước ấy và cách xác định vùng biển của họ ntn. Nếu vùng nước hẹp thì việc eo biển nó sẽ giao nhau còn nếu vùng nước rộng thì eo biển không đụng chạm ai cả",62],["p",81,"Quy chế pháp lý",62],["p",85,"- Tàu thuyền và phương tiện bay đều được hưởng quyền quá cảnh trên eo biển quốc tế mà không bị cản trở (Điều 38 CULB 1982).",62],["p",85,"- “Quá cảnh” : là việc thực hiện quyền tự do hàng hải và tự do hàng không với mục đích duy nhất là đi qua liên tục và nhanh chóng. Gần như là đi qua k gây hại",62],["p",85,"- Trong khi thực hiện quyền quá cảnh, các tàu thuyền và phương tiện bay (Điều 38 CULB 1982):",62],["p",85,"- Đi qua hay bay qua không chậm trễ.",62],["p",85,"- Không được đe dọa hay dùng vũ lực chống lại chủ quyền, toàn vẹn lãnh thổ hay độc lập chính trị của các quốc gia ven eo biển quốc tế và kênh đào quốc tế.",62],["p",85,"- Không được có hoạt động nào khác ngoài những hoạt động cần cho sự quá cảnh liên tục và nhanh chóng theo phương thức đi bình thường, trừ trường hợp bất khả kháng hoặc nguy cấp.",62],["p",85,"Nghĩa vụ: nhân đạo quốc tế. khi mà biết trong biển có mìn mà không thông báo",62],["p",81,"Trong vùng thuộc chủ quyền Quốc gia ven biển được quyền tiến hành mọi hoạt động liên quan đến khai thác, quản lý hay bảo tồn nguồn tài nguyên Có chủ quyền tuyệt đối trong việc:",62],["p",85,"- Thăm dò, khai thác",62],["p",85,"- Bảo tồn quản lý",62],["p",85,"- Xây dựng luật và quy định",62],["p",85,"- Xử lý vi phạm",62]],"pg":[62,62]}]},{"t":"Phân định và giải quyết tranh chấp","s":"Phân định biển; các biện pháp giải quyết tranh chấp, ITLOS, trọng tài","pg":"tr.66–84","g":[{"h":"Sơ đồ tóm tắt chương","lv":2,"b":[["f","sd_lb5.svg",720,388,"Sơ đồ: phân định biển và giải quyết tranh chấp"],["p",72,"Sơ đồ tự lập từ bài giảng và UNCLOS 1982, chưa đối chiếu toàn văn.",0]]},{"h":"PHÂN ĐỊNH BIỂN","lv":2,"b":[],"pg":[66,66]},{"h":"1. Khái quát về phân định biển","lv":3,"b":[["p",67,"Phân định biển là quá trình hoạch định ranh giới phân chia vùng biển giữa các quốc gia đối diện hoặc liền kề nhằm mục đích xác định biên giới biển hoặc đường phân chia các vùng biển thuộc quyền chủ quyền của mỗi bên phù hợp với các quy định của luật quốc tế",66],["p",67,"Phân định biển thường được tiến hành bằng con đường thoả thuận",66],["p",67,"Các bên liên quan có thể thoả thuận:",66],["p",89,"- Lựa chọn hình thức đàm phán để cùng phân định biển, hoặc",66],["p",89,"Lựa chọn một bên thứ ba như toà án hoặc trọng tài quốc tế đứng ra phân định biển. Đ287",66],["p",67,"Trong nhiều trường hợp phân định biển trở thành một tranh chấp quốc tế",66],["p",90,"✓ Phân định biển bao gồm:",66]],"pg":[66,66]},{"h":"(1) Phân định lãnh hải và nội thủy (biên giới biển)","lv":3,"b":[],"pg":[66,66]},{"h":"(2) Phân định Đặc quyền kinh tế, Thềm lục địa (ranh giới biển)","lv":3,"b":[],"pg":[67,67]},{"h":"2. Phân định biên giới quốc gia trên biển","lv":3,"b":[["p",103,"Phân định biển giới quốc gia trên biển là phân định ranh giới nội thủy và lãnh hải giữa các quốc gia đối diện hoặc liền kề nhau.",67],["p",103,"Phương pháp:",67],["p",139,"-Phương pháp đường trung tuyến cách đều; hoặc",67],["p",139,"- Thoả thuận về một giải pháp phân định khác trên cơ sở tính đến các yếu tố như danh nghĩa lịch sử hoặc hoàn cảnh đặc biệt",67],["p",103,"Là đường mà tất cả các điểm nằm trên đường đó đều cách đều các điểm gần nhất của đường cơ sở dùng để tính chiều rộng lãnh hải của các quốc gia",67],["p",103,"Áp dụng trong trường hợp các quốc gia có bờ biển tiếp liền hoặc đối diện nhau",67],["p",103,"Phải xem xét một cách thích đáng đến những hoàn cảnh cụ thể để đạt được một kết quả công bằng",67],["p",67,"(Điều 15 UNCLOS 1982)",67],["p",67,"Quy tắc chung: CƯ k cụ thể mà xét đến yếu tố để lưu ý trong thực tiễn vd theo TQQT",67],["p",67,"LƯU Ý: k phải lúc nào cũng phải chia đôi mà còn phụ thuộc vào yếu tố như lịch sử, hoàn cảnh thực tiễn/đặc biển nhưng CƯ k có định nghĩa nào là HCĐB.",67],["p",102,"Hoàn cảnh đặc biệt Theo thực tiễn quốc tế phân định lãnh hải và vùng tiếp giáp:",67],["p",103,"Hình dạng bất thường của bờ biển;",67],["p",103,"Sự hiện diện của các đảo;",67],["p",103,"Tuyến đường và luồng hàng hải.",67],["p",103,"Theo thực tiễn phân định => dựa vào hình dạng thất thường của bờ biển, do sự hiện diện của các đảo. Các vấn đề về danh nghĩa ls => người dân ven biển đó có đời sống phụ thuộc hẳn vào biển => nếu chia đều thì sẽ tác động trực tiếp đến người dân ở đó Tại khu vực có tồn tại có tuyến đường hàng hải quốc tế => lưu ý lại việc đi lại của tàu thuyền, nếu chia theo đường trung tuyến cách đều thì dễ phạm vào quyền lợi của tàu thuyền Thực tế thì VN chiếm đến 53% ở vịnh bắc bộ còn TQ chỉ chiếm 47%.",67],["p",103,"Đây là vịnh nằm nội bộ trong VN và TQ, có yếu tố liên quan đến lịch sử, sự hiện diện của các đảo mà khiến diện tích có thể thay đổi",67],["p",103,"Hđ phân định biên giới chỉ xảy ra khi cần phân định nội thủy và lãnh hải thôi (gọi là đg biên giới quốc gia trên biển)",67],["p",103,"Còn trường hợp ranh giới ngoài lãnh hải => phân định biên giới trên biển Phân định các quyền chủ quyền của qg => phân định đặc quyền kinh tế Các nước có thể đối diện liền kề với nhau thì các bên có thể thỏa thuận phân định nhau còn nêu cách xa thì có thể tự tuyên bố nhưng tránh việc xâm phạm đến quyền chủ quyền của nước khác và ranh giới vùng biển quốc tế. VN có đg biên giới trên biển với Campuchia và TQ thôi. Thái lan, maylay, indo vẫn có phân định biển nhưng là vùng đặc quyền ktế và thềm lục địa. Phân định đặc quyền kinh tế/ thềm lục địa nhưng k đủ diện tích => cần có sự phân định biển (đường đó k gọi là đường biên gưius mà chỉ là đường phân định quyền th)",68],["p",102,"3. Phân định các vùng biển thuộc quyền chủ quyền giữa các quốc gia ( Đ 74, Đ83)",68],["p",103,"Là phân định vùng đặc quyền kinh tế và thềm lục địa giữa các quốc gia Nguyên tắc chung Việc hoạch định ranh giới vùng ĐQKT (TLĐ) giữa các quốc gia có bờ biển nằm tiếp liền hoặc đối diện nhau được thực hiện bằng con đường thỏa thuận để đi đến một giải pháp công bằng.",68],["p",103,"Áp dụng đường trung tuyến cách đều nhưng chủ yếu vẫn thực hiện bằng con đường thỏa thuận",68],["p",102,"Nếu các nước có tranh chấp thì sẽ áp dụng theo luật chung, bằng con đường tài phán, có thể đàm phán hoặc hòa giải",68],["p",102,"Quá trình phân định có thể kéo dài cho nên theo quy định Đ74, trong tgian chờ đợi đg phân định thì các bên có thể đưa ra các dàn xếp tạm thời, thực hiện hđ phân chia lợi ích để làm giảm căng thẳng (không vì thế mà nhường bộ nhau hay là đang nhường quyền chủ quyền)",68],["p",102,"Nếu các quốc gia cùng là UNCLOS 1982 nhưng lại có kí 1 ĐƯ riêng thì theo thứ tự ưu tiên thì họ sẽ áp dụng cái ĐƯQT mà họ đã ký riêng với nhau",68],["p",102,"Các bên có thể thỏa thuận để đi đến 1 giải pháp công bằng",68],["p",103,"Nếu không đi tới được một thỏa thuận trong một thời gian hợp lý, các quốc gia hữu quan sử dụng các thủ tục nêu ở phần XV.",68],["p",103,"Các quốc gia hữu quan có thể áp dụng các dàn xếp tạm thời có tính chất thực tiễn và để không phương hại hay cản trở việc ký kết các thỏa thuận dứt khoát trong giai đoạn quá độ này.",68],["p",103,"Khi một điều ước đang có hiệu lực giữa các quốc gia hữu quan, các vấn đề liên quan đến việc hoạch định ranh giới vùng ĐQKT (TLĐ) được giải quyết theo đúng điều ước đó.",68],["p",103,"Điều 74 UNCLOS 1982",68],["p",106,"Giải pháp công bằng",68],["p",103,"Giải pháp công bằng không được quy định cụ thể trong Công ước",68],["p",103,"Tương tự phân định trung tuyến cách đều, nhưng phải tính đến yếu tố liên quan và áp dụng linh hoạt về quy định phân định.",69],["p",103,"Thực tiễn áp dụng: các quốc gia phải xem xét tất cả các yếu tố liên quan trong khu vực phân định và áp dụng linh hoạt các quy định về phân định",69],["p",102,"Các yếu tố liên quan Các đặc điểm địa lý, địa mạo, địa chất (Hình thái bờ biển, sự hiện diện của các đảo…);",69],["p",103,"Sự hiện diện của mỏ tài nguyên;",69],["p",103,"Tỷ lệ giữa chiều dài bờ biển và diện tích thềm lục địa;",69],["p",103,"Sự hiện diện của đảo;",69],["p",103,"Điểm mút biên giới đất liền: điểm này có thể dùng để bắt đầu vẽ đường phân định biển",69],["p",103,"Sự hiện diện của các đường đặc nhượng hay đường cấp phép thăm dò, khai thác dầu khí hay các tài nguyên khác;",69],["p",103,"Yếu tố quốc gia bất lợi về địa lý: 1 quốc gia cũng tiếp giáp biển ít, các đặc điểm tự nhiên k đảm bảo để cung cấp nguồn thủy sản mà người dân cần,",69],["p",103,"Lợi ích kinh tế, chính trị, an ninh;",69],["p",103,"Truyền thống đánh cá;",69],["p",103,"Giao thông hàng hải;",69],["p",103,"Yếu tố văn hoá;",69],["p",103,"Các quyền lợi chính đáng khác, v.v…",69],["p",67,"VD: VN vs Philip, VN có chủ quyền vs Trường Sa nhưng 1 số đảo trường sa (phía tây) lại nằm trong vùng đặc quyền kinh tế với philip, nhưng đến giờ thì bên lãnh đạo vẫn chưa thể đàm phán với nhau => nhạy cảm. Có sự hiện diện của mỏ tài nguyên => nếu như 2 nước đối diện nhau lại tồn tại 1 mỏ dầu khí => không thể phân chia 1 đường cụ thể => nếu k phân chia được thì mỏ bị đóng băng luôn Các vấn đề phân chia thềm lục địa, nước nào có chiều dài đường biển dài hơn thì thềm lục địa lớn hơn => căn cứ vào thềm lục địa, VN có chiều dài bờ biển dài hơn thì không thể chia đôi được (theo nguyên tắc đất thống trị biển) TAQT đã áp dụng điều này để hóa giải tranh chấp giữa Đức, ai đó…",69],["p",67,"Sự hiện diện đường đặc nhựa/ đường cấp phép?? VN với Cam có tồn tại 1 đường R => đường R đó là đường biên giới theo sự nhận định của nhiều người nhưng thật ra 2 bên vẫn chưa chia được Thời kỳ thuộc pháp, chính quyền bảo hộ cam và chính quyền VN có tranh chấp hàng hải, thu thuế các tài thuyền => toàn quyền đông dương brevie đã vẽ 1 đường cắt từ hà tiên, qua",69],["p",67,"TQ và trao quyền thu thuế và kiểm soát hàng hải đối với vùng biển tây nam là thuộc cam còn đông bắc là thuộc về chính quyền của VN. Trong quyết định đó lại không chỉ ra việc phân định biển mà chỉ chỉ ra phạm vi thẩm quyền của các nước.",70],["p",67,"=> nó chỉ trao quyền cho các bên quản lý tàu thuyền đi lại và thu thuế => nó là về mặt hành chính th. sau này chính quyền 2 bên thay đổi và chấm dứt hiệu lực rồi Các yếu tố bất lợi về mặt địa lý => quốc gia có khu vực tiếp giáp với biển k đủ đảm bảo để cung cấp người dân nhưng dân ở đó thì dựa rất nhiều vào kinh tế trên biển Phân chia vịnh bắc bộ => có ngư trường truyền thống của 2 bên => phải ký 1 thỏa thuận về khai thác nghề cá chung giữa 2 nước",70],["p",103,"Yếu tố văn hóa => người dân có nghi thức nhất định được tiến hành ở các uvf biển => phải tôn trọng",70],["p",102,"Dàn xếp tạm thời Đ74 Bao gồm các thỏa thuận như hợp tác cùng thăm dò, khai thác, bảo vệ tài nguyên môi trường “Dàn xếp tạm thời” không được ảnh hưởng đến kết quả phân định => là 1 giải pháp tạm thời để giải quyết tạm thời mâu thuẫn, để đạt được nhu cầu kinh tế trước mắt giữa các bên th, trong thgian đó vẫn phải tiếp tục đàm phán. Việc bên này hoặc bên kia nhân nhượng về một khía cạnh nào đó để đạt được “dàn xếp tạm thời” không có nghĩa là từ bỏ lập trường của mình và công nhận lập trường của bên kia.",70],["p",67,"Một “dàn xếp tạm thời” không có nghĩa chấm dứt đàm phán phân định.",70],["p",103,"Dàn xếp tạm thời là gì? => không phải ngày 1 ngày 2 mà đưa ra đường phân định luôn => công ước khuyến khích các bên có thể áp dụng cá các biện pháp tạm thời",70],["p",103,"Vd: Khi chúng ta tuyên bố về đường cơ sở là 200 hải lý, malaysia cx v => xuất hiện chồng lấn => 2009 đã có thỏa thuận dàn xếp tạm thời => cùng khai thác chung mỏ dầu khí ở vùng chồng lấn. => k phải là kết quả của việc phân định mà chỉ là sự thiện chí.",70],["p",67,"Có dàn xếp tạm thời để giải bớt căng thẳng giữa các bên Đây được coi là nền tảng để thể hiện cái sự thiện chí giữa các bên => tạo được bước đà để tiến tới phân định rõ ràng Nội thủy phải xin phép trước, vì lý do nhân đạo thì vừa đi vừa xin phép cx được vd như rủi ro thiên tai, gặp tai nạn",70],["p",103,"VN, TL, có chung thềm lục địa nên khi chia ra họ chỉ cần chia nửa chỗ bị chồng lấn là đc k cần xét đến yếu tố khác.",70],["p",67,"VN, Indo: vùng ĐQKT lại có quan điểm khác nhau cụ thể là mốc xuất phát của đường trung tuyến cách đều.",70],["p",67,"Đảo cồn cỏ, chúng ta vẫn chưa thỏa thuận đc để phân chia tiếp ĐQKT và TLĐ với TQ",70],["i","lb71_1.jpg",71,1039,779],["p",103,"Việc TQ tuyên bố đường lưỡi bò đã xâm phạm đến vùng ĐQKT của nước ta (đường này k có tranh chấp nào vã đã được công nhận) nên nước ta không có cuộc đàm phán nào để thỏa thuận đường lưỡi bò.",71],["p",67,"Khu vực thái lan ko đủ khoảng cách => xác định đqkt và tld là 400 hl từ đường cơ sở=> có vùng chồng lấn",71],["p",67,"Các đảo hai bên có sự đan xen với nhau, đảo phú quốc gần cam, nên các bên thỏa thuận phối hợp quản lý chung nhưng vẫn chưa có sự phân chia rõ ràng, vẫn còn nhập nhằng",71],["i","lb72_1.jpg",72,1099,725],["p",103,"Đảo phú quốc nó nghiêng về cam hơn, trong khi đảo của cam thì lại hướng về vn hơn vì nó liên quan đến việc xác định ranh giới rõ ràng => chỉ thỏa thuận sẽ cùng nhau quản lý chung th",72],["p",103,"Tình hình chiến tranh 1973-74 thì các nước đã có sự chiếm đoạt các đảo, cho đến nay",72],["p",103,"Cơ chế giải quyết tranh chấp của UNCLOS 1982",72]],"pg":[67,72]},{"h":"1. Khái quát tranh chấp về biển","lv":3,"b":[["p",103,"Tranh chấp quốc tế về biển là những bất đồng, xung đột giữa các chủ thể của luật quốc tế trong quá trình xác lập và phân định chủ quyền, quyền chủ quyền và quyền tài phán của quốc gia đối với các vùng biển theo quy định của luật biển quốc tế Liên quan đến CPQT.",72],["p",103,"CHỦ THỂ: quốc gia ( chủ yếu là quốc gia độc lập, có chủ quyền) , tổ chức quốc tế về biển, tổ chức nông lương liên hợp quốc liên quan đến hđ đánh bắt cá, TC hàng hải QT, hàng không … Được thành lập hợp pháp theo unclos.",72],["p",103,"Vd như tổ chức/xí nghiệp được thành lập để đảm bảo an ninh cho 1 hđ khai thác trên biển, nhưng phần thứ 11 thì cơ quan quyền lực vùng có thể thành lập cơ quan để đại diện cho họ và tgia vào cả các tranh chấp luôn. => xí nghiệp là chủ thể thuộc đối tg điều chỉnh của CPQT.",72],["p",103,"1 tập đoàn, 1 DN mang quốc tịch mà tổ chức đó đăng ký có hđ khai thác trên biển; họ có thể đkí để đứng ra giải quyết việc tranh chấp xảy ra => tranh chấp tư, NHƯNG nếu quốc gia đó có ‘đáp lại’ bằng việc nhân danh bảo hộ công dân của nước mình thì lúc này tranh chấp tư trở thành tranh chấp công.",73],["p",103,"VỀ NỘI DUNG:",73],["p",90,"✓ Chủ quyền quốc gia, thực thi quyền chủ quyền, quyền tài phán và các quyền",73],["p",108,"khác đối với các vùng biển",73],["p",90,"✓ Quy chế pháp lý của các thực thể địa lý trên biển",73],["p",90,"✓ Trong các lĩnh vực hàng hải, hàng không, xây dựng đảo nhân tạo và thiết bị",73],["p",108,"công trình, NCKH, bảo vệ môi trường biển, khai thác, bảo vệ, sử dụng, quản",73],["p",108,"lý tài nguyên biển",73],["p",103,"VỀ KHÁCH THỂ: là chủ quyền, quyền chủ quyền, quyền tìa phán và các quyền, tự do khác của quốc gia đối với các vùng biển đã được UNCLOS 1982 quy định.",73],["p",102,"Đặc trưng của hệ thống giải quyết tranh chấp theo UNCLOS",73]],"pg":[72,73]},{"h":"(1) Bao gồm các biện pháp thủ tục giải quyết cũ và mới, lần đầu UNCLOS 1982","lv":3,"b":[["p",72,"ghi nhận đó thủ tục của ITLOS, Trọng tài và Trọng tài đặc biệt.",73]],"pg":[73,73]},{"h":"(2) Cơ chế mặc định là thủ tục Trọng tài (Phụ lục VII UNCLOS 1982)","lv":3,"b":[["p",102,"Phân loại tranh chấp biển",73],["p",85,"● Dựa vào tính chất vụ tranh chấp có tranh chấp chính trị và tranh chấp pháp lý.",73],["p",121,"○ Tranh chấp pháp lý : phát sinh từ hành vi vi phạm, luật cấm mà lại làm, luật yêu cầu mà k làm. Tranh chấp về việc giải thích pháp luật và áp dụng. => Dựa vào luật QT là GQ được.",73],["p",121,"○ Tranh chấp chính trị: các bên đưa ra sức mạnh/lợi ích/đg lối/chính sách của chính trị để chi phối đến tiến trình giải quyết tranh chấp. Nếu đề cao chính trị thì giá trị pháp lý sẽ bị hạ thấp (giống đường lưỡi bò của TQ)",73],["p",85,"● Dựa vào chủ thể tranh chấp có tranh chấp giữa các quốc gia với nhau và tranh chấp giữa các quốc gia với các tổ chức quốc tế về biển (Mục 5, phần XI của Công ước 1982 về luật Biển",73],["p",85,"● Dựa vào lĩnh vực tranh chấp: tranh chấp chủ quyền, tranh chấp quyền chủ quyền, tranh chấp liên quan đến quyền khai thác các tài nguyên thiên nhiên, nghiên cứu khoa học, bảo vệ và giữ gìn môi trường biển…",73],["p",85,"● Tranh chấp về vấn đề chủ quyền với các vùng biển nội thủy, vùng nước",73],["p",103,"quần đảo, lãnh hải, các đảo và quần đảo",73],["p",85,"● Tranh chấp về quyền chủ quyền và quyền tài phán với các vùng tiếp giáp",74],["p",103,"lãnh hải, đặc quyền kinh tế, thềm lục địa",74],["p",85,"● Tranh chấp về các quyền và tự do khác trên biển",74],["p",85,"● Tranh chấp về giải thích, áp dụng luật biển",74],["p",67,"Các bên đề cao vấn đề pháp lý thì có thể dễ dàng hơn",74],["p",102,"Các tranh chấp về biển thuộc đối tượng điều chỉnh của UNCLOS 1982",74],["p",103,"Các tranh chấp liên quan đến việc giải thích hoặc áp dụng Công ước 1982 về Luật Biển (Điều 286 Công ước)",74],["p",67,"Vấn đề xác định chủ quyền giữa các đảo thì CƯ thì k quy định (đã viết)",74],["p",103,"Chủ quyền, quyền chủ quyền, quyền tài phán; hđ hàng hải, khai thác đánh bắt cá, BVMT, xd đảo nhân tạo, công trình; nghiên cứu khoa học.",74],["p",67,"CƯ k đề cập đến việc xác lập chủ quyền của các đảo ntn mà chỉ nêu đặc điểm đảo nào thì có thềm lục địa, ĐQKT mà thôi. Nguyên tắc xác lập chủ quyền vs đảo là nguyên tắc sự thật.",74],["p",67,"Có thể đưa ra các tòa khác như các tòa có thẩm quyền chung th. chứ tòa của 1982 thì sẽ là tòa riêng biệt (không giải quyết được)",74],["p",67,"TQ đưa ra được đứt khúc 9 đoạn thì có giải quyết bằng UNCLOS 1982 không? Được, vì trường hợp này là TQ nó đưa ra sai? và CƯ có quy định các cơ chế mà TQ đã xâm phạm vì vậy…",74],["p",67,"Cướp biển => thường xảy ra ở vùng biển quốc tế => nếu xảy ra ở vùng biển thuộc chủ quyền thì nó sẽ không nằm trong phạm vi của công ước vì CƯ không điều chỉnh",74],["p",103,"2. Các biện pháp giải quyết tranh chấp theo Công ước 1982 về Luật Biển",74],["p",102,"Các biện pháp mang tính ngoại giao",74],["p",67,"Thương lượng ngoại giao ( đàm phán) điều 283 Công ước 1982 về Luật Biển => NGOÀI RA NẾU CÁC BÊN K THỂ ĐÀM PHÁN để GQ thì việc đàm phán vẫn được thực hiện để chọn phương pháp khác. Trao đổi quan điểm.",74],["p",102,"Cụ thể không có luật, là dựa vào sự đàm phán của các bên th. (thể thức, cấp, thời gian đều tự do)",74],["p",102,"Lưu ý: có 1 số nguyên tắc chi phối buộc các bên phải tuân thủ để có thể đàm phán được",74],["p",85,"● Không được dùng việc đàm phán để can thiệp vào nội bộ của nhau",74],["p",85,"● Phải có thiện chí",74],["p",85,"● Phải tôn trọng chủ quyền của nhau",75],["p",85,"+ Đàm phán không thiện chí trah chấp thì tranh chấp rất khó để giải quyết",75],["p",85,"+ Nó quan trọng nhất, luôn được nêu ra đầu tiên. Vì :",75],["p",85,"+ Nếu trực tiếp giải quyết thương lượng với nhau thì nó sẽ có nhiều ưu điểm hơn so với các biện pháp khác. o Nhanh: nếu có thiện chí chỉ cần vài ba buổi đàm phán là giải quyết xong. Còn đưa ra tòa thì phảigiải quyết theo thủ tục tố tụng. tốn gần 3-5 năm => vì thế nên tiết kiệm về mặt thời gian o Tiết kiệm chi phí: tốn tiền chi phí đi lại, tổ chức đàm phán. Chỉ phí rẻ hơn so với biện pháp khác. còn biện pháp khác thì tốn án phí, tốn tiền đầu tư đầu tư chi phí điều tra, thu thập tài liệu, đầu tư về luật sư… o Đàm phán thì các bên tự mình giải quyết vụ tranh chấp với nhau thì bảo mật thông tin -> không đặt ra vấn đề bên nào thắng bên nào thua. Các bên cùng với nhau đạt được lợi ích công bằng, không bên nào thắng bên nào thua -> duy tri mối quan hệ tốt đẹp o Giúp cho các bên duy trì mối quan hệ tốt đẹp so với các cơ quan tài phán o Chủ động tiến trình tranh chấp mà không phụ thuộc vào bên thứ ba nào cả -> đảm bảo lợi ích tốt nhất quốc gia mình",75],["p",67,"Hoà giải (Điều 284, Phụ lục V Công ước 1982 về Luật Biển) =>",75],["p",121,"• Áp dụng trong trường hợp 2 bên đều đồng ý áp dụng biện pháp này (Do các bên tranh chấp thoả thuận về việc cùng áp dụng biện pháp hòa giải này )",75],["p",85,"- Một số vụ tranh chấp bắt buộc phải áp dụng hòa giải bắt buộc (nếu tranh chấp thuộc điều 297, 298 CƯ thì chỉ cần ít nhất 1 bên yêu cầu thì việc hòa giải phải được diễn ra)",75],["p",102,"Nếu 1 bên đề nghị, yêu cầu thủ tục hòa giải thì bắt buộc áp dụng thủ tục hòa giải dù bên kia có đồng ý hay không thì thủ tục hòa giải được tiến hành ủy ban hòa giải được thành lập, tiến trành hòa giải….",75],["p",102,"Tranh chấp đ 297,298: là những tranh chấp theo quy định công ước thì không bắt buộc đưa ra tòa án quốc tế…, tòa án quốc tế về luật biển… nếu không đươc sự đồng ý của 2 bên , những tranh chấp khá là nhạy cảm ( tranh chấp về vịnh lịch sử, quân sự,.. -> nếu giải quyết k thỏa đáng thì ảnh hưởng đến hòa bình an ninh quốc tế nói chung) , nên không thể đơn phương đưa ra tòa án quốc tế về luật biển,…",75],["p",85,"⇒Đưa ra kết luận hòa giải : kiến nghị chứ không bắt buộc áp dụng ( để các bên xích lại gần nhau, các bên nếu thấy hợp lý thì áp dụng)",75],["p",121,"• Cơ cấu của Uỷ ban hoà giải : PHỤ LỤC V",75],["p",139,"+ Thành phần: 5 uỷ viên được các bên lựa chọn trong danh sách các hoà giải viên của LHQ Bên đề nghị thủ tục hòa giải : chọn 2 người ( 1 trong 2 người là công dân của chính họ)",75],["p",102,"Bên đề nghị hủ tục hòa giải : chọn 2 người ( 1 trong 2 người là công dân của chính họ) 2 bên lựa chọn 1 người là người thứ năm ( của nước thứ 3) là chủ tịch ủy ban hòa giải)",75],["p",102,"Nếu không cử hòa giải viên thì tổng thư ký lhq sẽ cử thay cho họ",75],["p",139,"+ Tổng thư ký LHQ tiến hành bổ nhiệm các hoà giải viên theo sự lựa chọn của các bên (Điều 3, Phục lục V) ( nắm giữ danh sách hòa giải viên)",75],["p",102,"UB đc thành lập thì thủ tục đc tiến hành => tự thỏa thuận => k TT đc thì LHQ tự đề ra VAI TRÒ UBHG: lắng nghe các bên (gặp mặt từng bên hoặc các bên), nêu ra đề nghị giúp các bên giải quyết KL HG: quan điểm các bên, hướng giải quyết, quyền lợi nghĩa vụ của các bên, … Trong 12 tháng thì UB phải lập ra 1 bản báo cáo gửi cho tổng thư ký LHQ ( TRONG PHỤ LỤC V)",76],["p",102,"Tiến hành thủ tuc hòa giải sau khi bổ nhiệm",76],["p",85,"- Thỏa thuận",76],["p",85,"- Nếu k có thỏa thuận thì ủy ban hòa giải tự quy định thủ tục hòa giải của mình Vài trò uy ban hòa giải: lắng nghe ý kiến của các bênm trao ođỏi quan điểm với các bên, gặp mặt tiếp xúc trực tiếp với các bên, để lắng nghe trao đổi để tư vấn cho cbác bên để đưa ra giải quyết tranh chấp ( ở giữa trung gian để giỉa quyết tranh chấp ) Thông quan kết luận hòa giải (nq hòa giải( : phân tích luận giải của ủy viên hòa giải và dự kiến giải quyết tranh chấp Gửi kết quả báo cáo và các bên : Đ8 PHỤ LỤC V",76],["p",85,"- Đồng ý: giải quyết xong rồi mới kết thúc",76],["p",85,"- Các bên trả lời không đồng ý hòa giả: thỉ ủy ban hòa giải giải tán",76],["p",85,"- Kết thúc sau 3 tháng cho các bên mà các bên k trl thì thủ tục hòa giải giải tán và kết thúc 9",76],["p",85,"- Thủ tục vẫn có thể tiếp tục nếu thuộc trường hợp sau đây:",76],["p",121,"+ Các bên chấp nhận KLHG => UBHG tiếp tục giải quyết tranh chấp đã được nêu trong KLHG => UBHG mới giải tán sau khi GQ õng vụ tranh chấp",76],["p",121,"+ UBHG gửi mà các bên k đồng ý/bác bỏ => UBHG tự động giải tán.",76],["p",121,"+ UBHG gửi KL mà các bên im lặng => thủ tục sẽ kết thúc sau 3 tháng sau khi gửi KLHG.",76],["p",102,"Sau khi gửi báo cáo, tùy thuộc vào sự phản ứng của các bên xem có nên kết thúc hay ko",76],["p",67,"Do các bên tranh chấp thoả thuận Một số vụ tranh chấp bắt buộc phải thực hiện thủ tục hoà giải: Các tranh chấp liên quan đến quy định tại Điều 297, 298 Công ước (Điều 11, Mục 2, Phụ lục V)",76],["p",67,"K1 Đ33 Hiến chương LHQ, CƯ có nêu ra các biện pháp hòa bình được ưu tiên (nó bao gồm chứ k chỉ tức là vẫn còn các biện pháp các) 2 nhóm: BPGQTC tính ngoại giao và tài phán Áp dụng các biện pháp hòa bình tương tự như hiến chương LHQ, các biện pháp bao gồm nhưng k chỉ trong các biện pháp quy định TC chuyên môn phải báo cáo về các vấn đề",76],["p",67,"Khác nhau:",76],["p",67,"Ngoại giao: thủ tục tiến hành theo thủ tục ngoại giao, có thể giao cho cơ quan thứ 3 thực hiện. => kết luận GQ k mang tính bắt buộc mà chỉ mang tính khuyến nghị. Đàm phán (thương lượng ngoại giao), trung gian, hòa giải (Điều tra => chỉ mang tính ngoại giao vì nó chỉ mang tính khuyến nghị)",76],["p",67,"Tài phán: BPGQTC theo trình tự thủ tục TT tư pháp (HĐXX, tiến trình TT như phiên tòa TT tranh tụng, phiên nghị án => phán quyết có giá trị bắt buộc aka bản án hoặc phán quyết NHƯNG CƯ lại k đầy đủ bằng HC LHQ )",77],["p",67,"CƯ 1982 đưa ra cả 2 con đường, tuy nhiên nó không đầy đủ như LHQ => gồm ngoại giao và hòa giải Trong CƯ chỉ có đàm phán và hòa giải mà thôi, k có trung gian như HCLHQ.",77],["p",67,"Biện pháp mang tính tp => thành lập 3 cơ quan tp => tòa án quốc tế về luật biển, tòa trung gian về luật biển, tòa trọng tài đb",77],["p",103,"Cơ cấu của Uỷ ban hoà giải Thành phần: 5 uỷ viên được các bên lựa chọn trong danh sách các hoà giải viên của LHQ Tổng thư ký LHQ tiến hành bổ nhiệm các hoà giải viên theo sự lựa chọn của các bên (Điều 3, Phục lục V)",77],["p",103,"Thủ tục hoà giải",77],["p",85,"● Uỷ ban hoà giải tự quy định thủ tục của mình, trừ khi các bên có thoả thuận khác (Điều 4, Phụ lục V)",77],["p",85,"● Uỷ ban hoà giải lắng nghe các bên trình bày nội dung vụ tranh chấp",77],["p",85,"● Nêu ra các đề nghị giúp các bên đạt được một giải pháp cho vụ tranh chấp",77],["p",85,"● Trong vòng 12 tháng sau khi được thành lập, uỷ ban hoà giải phải lập báo cáo gửi Tổng thư ký LHQ và tất cả các bên trong vụ tranh chấp (Điều 7, Phụ lục V)",77],["p",85,"● Thủ tục hoà giải kết thúc khi tranh chấp được giải quyết, hoặc một trong các bên bác bỏ các khuyến nghị trong báo cáo hoặc sau 3 tháng từ ngày gửi báo các cho các bên",77],["p",102,"Các biện pháp tài phán",77],["p",67,"Giải quyết tranh chấp tại Toà án quốc tế về Luật Biển ( Phụ lục VI)",77]],"pg":[73,77]},{"h":"1. Khái quát","lv":3,"b":[["p",103,"Được thành lập từ ngày 18/10/1996 Trụ sở tại Hamburg, Đức Ngôn ngữ sử dụng: tiếng Anh và tiếng Pháp Có quy chế như một tổ chức chuyên môn của LHQ",77],["p",85,"• Giải quyết tranh chấp tại Toà án quốc tế về Luật Biển (Phụ lục VI) Cơ quan tài phán hoàn toàn đúng bản cahát của nó( giải quyết trình tự thủ tục tổ tụng) và kết luận mang tính bắt buộc LHQ có 6 cơ quan chuyên môn LHQ, là bộ phận trực thuộc của LHQ ( Tòa án quốc tế về luật biển là tổ chức chuyên môn lhq là tổ chức quốc tế độc lập, nó có thỏa thuận cam kết với lhq với đuqt rằng thực hiện mục tiêu của lhq trong các vấn đề của lhq, nó không là tổ chức chuyên môn lhq; tòa án",77],["p",85,"• Giải quyết tranh chấp tại Toà trọng tài quốc tế về Luật Biển (Phụ lục VII) Cơ quan tài phán hoàn toàn đúng bản cahát của nó( giải quyết trình tự thủ tục tổ tụng) và kết luận mang tính bắt buộc",78],["p",85,"• Giải quyết tranh chấp tại Toà trọng tài đặc biệt (Phụ lục VIII) Thủ tục tìa phán: phiên tòa, trọng tài viên …-> nhưng kết luận lại mang tính chất kiến nghị chứ không bắt buộc",78]],"pg":[77,78]},{"h":"2. Thành phần của toà án","lv":3,"b":[["p",103,"Bao gồm 21 thẩm phán, do các quốc gia thành viên Công ước bầu ra Nhiệm kỳ của các thẩm phán là 9 năm Các bên có thể bổ sung các thẩm phán adhoc Các thẩm phán được hưởng đầy đủ các quyền ưu đãi và miễn trừ Số thành viên tối thiểu để tiến hành xét xử là 11",78],["p",103,"Tổ chức liên chính phủ được thành lập tại Phụ lục VI UNCLOS (quy tắc bầu, tư cách thẩm phán, tlâp HĐXX)",78]],"pg":[78,78]},{"h":"3. Các viện chuyên môn","lv":3,"b":[["p",103,"Viện giải quyết các tranh chấp liên quan đến đáy biển (Điều 14, Phục lục VI Các viện đặc biệt (Điều 15 Phụ lục VI)",78]],"pg":[78,78]},{"h":"4. Ban thư ký","lv":3,"b":[["p",103,"Là cơ quan hành chính thường trực của toà, đảm nhiệm các công việc hành chính, ngoại giao... cho toà án",78]],"pg":[78,78]},{"h":"5. Thẩm quyền","lv":3,"b":[["p",103,"Giải quyết các vụ tranh chấp giữa các quốc gia theo đúng Công ước : loại tranh chấp đưa ra đúng quy định của công ước.",78],["p",103,"Đưa ra các kết luận tư vấn pháp lý trong trường hợp có một điều ước quốc tế liên quan đến tôn chỉ, mục đích của Công ước Nhiệm kỳ 9 năm, k có cơ chế thay đổi thành phần của tòa",78],["p",85,"- Loại tranh chấp tòa có thẩm quyền",78],["p",102,"+ Vụ tranh chấp liênq uan giải thích áp dụng của công ước",78],["p",102,"+ Các bên có quyền đưa tranh chấp ra tòa, và các bên đồng ý thẩm",78],["p",67,"quyền của tòa, thì tòa mới có thẩm quyền giải quyết ( phải có đồng ý các bên",78],["p",67,"tranh chấp)",78],["p",102,"Đồng ý này không là đồng thuận đưa",78],["p",102,"Cách thức chấp nhận tòa án quốc tế, lhq: không nhất thiết phải là đồng",78],["p",67,"thuận đưa ra tòa thì mới là đồng ý, mà có thể",78],["p",106,"+ chấp thuận trước ( các bên cùng thỏa thuận, phát sinh mối quan hệ",79],["p",67,"với nhau dù tranh chấp chưa xảy ra đồng ý thẩm quyền xét xử của tòa ; nếu",79],["p",67,"sau này tranh chấp thật thì 1 bên khởi kiện dù bên kia không đồng ý thì cũng",79],["p",67,"được coi là chấp thuận; hoặc mối bên cũng tuyên bố đơn phương ( A tuyên",79],["p",67,"bố là tòa án giải quyết tranh chấp… bên B cũng có tuyên bố … và cùng phạm",79],["p",67,"vi hiệu lực ( tcùng 1 loại tranh chấp) thì sau này dù có 1 bên đồng ý , bên còn",79],["p",67,"lại khộng đồng ý thì vẫn được coi là chấp nhận)",79],["p",102,"+ chấp thuận sau thẩm quyền của tòa ( có 2 trường hợp: sau khí xảy ra",79],["p",67,"các bên thống nhất là tranh chấp đưa ra tòa ( thỏa thuận thịnh cầu tòa; ….)",79],["p",85,"- Cách thức giải quyết phù hợp chứ, chính xác theo quy định hay chưa",79],["p",85,"• Đưa ra các kết luận tư vấn pháp lý trong trường hợp có một điều ước quốc tế liên quan đến tôn chỉ, mục đích của Công ước -> không mang tính bắt buọc mà chỉ tư vấn, tham khảo Nếu hai nước là thành viên của công ước ký điều ước ( thỏa thuận) nào đó mà trái với công ước",79],["p",67,"-> vẫn được miễn sao k trái với nguyênt ắc cơ bản của luật quốc tế.",79],["p",67,"Mà nếu có trái thì cũng chỉ đưa ra kết luận mang tính kiến nghị, miễn không trái nguyên tắc cơ bản của luật quốc tế thì các bên có thể không quan tâm đến kết luận tư vấn",79],["p",103,"6. Quyền đưa tranh chấp ra trước toà : Đ20 phụ lục VI)",79],["p",103,"Các quốc gia thành viên Công ước đương nhiên là thành viên của toà Các thực thể khác : các tổ chức quốc tế, các pháp nhân, thể nhân và các xí nghiệp được quy định tại phần XI của Công ước cũng có thể yêu cầu toà xem xét các tranh chấp liên quan đến Vùng (đáy đại dương)",79],["p",67,"Tại sao có sự xuất hiện của các thể nhân Theo quy định p11 của CỨ => có quy định các thế nhân này được quyền quản lý vùng => họ cũng có quyền nếu có tranh chấp (nếu tranh chấp khác thì họ sẽ k được quyền Theo quy định phần thứ xi, có thể thành lập … để quản lý phần khác nhau đối với đáy đại dương này.",79],["p",102,"Còn tòa án công lý LHQ : chỉ xét xử đối với các quốc gia, còn thực thể như cá nhân,. Tổ chức thì k Còn tòa án quốc tế về luật biển thì có thể thực hiện xét xử đối với tư cách của quốc gia, thự cthể khác( liên quan đến vùng)",79]],"pg":[78,79]},{"h":"7. Thủ tục tố tụng","lv":3,"b":[["p",85,"● Các bên nộp đơn kiện lên tòa án cùng tất cả các hồ sơ cần thiết thông qua Ban thư ký",79],["p",103,"+ Báo cáo cho hội đồng thẩm phán",80],["p",103,"+ Gửi hồ sơ cho bị kiện",80],["p",103,"+ Gửi bản sao đơn kiện",80],["p",103,"+ Sao y bản chính gửi cho tất cả các quốc gia là thành viên của công ước -> họ có thể có bằng chứng, chứng cứ thực hiện giải quyết dễ dàng hơn, để họ xem xét vụ tranh chấp có liên quan tới mình hay không, họ có thể biết được đó là hình thức báo cáo",80],["p",85,"● Các thủ tục bổ trợ (tiền tố tụng)",80],["p",103,"+ Chưa xét xử về mặt nội dung, chỉ xem xét các vấn đề để chuẩn bị chon xét xử: xem xét tư cách của bên thứ ba,…",80],["p",85,"● Tòa tiến hành xét xử về mặt nội dung",80],["p",121,"+ Theo thủ tục nói hoặc thủ tục viết",80],["p",121,"+ Thủ tục viết: xem xét về mặt thủ tục giất tờ, hồ sơ -> bị vong lục, phẩn bị vong lục",80],["p",121,"+ Bản Bị phong lục",80],["p",121,"+ Phản bị vong lục",80],["p",85,"• Toà nghị án và ra phán quyết theo đa số thành viên có mặt : Có giá trị hiệu lực ngay với các bên, có giá trị chung thẩm ( k có kháng cáo, kháng nghị)",80],["p",85,"● Phán quyết của tòa mang tính bắt buộc đối với các bên tranh chấp Gần giống với TA công lý quốc tế",80],["p",85,"+ Các bên thống nhất gửi đơn lên tòa để gq gọi là “thỏa thuận thỉnh cầu”, lúc này k có nguyên-bị nào hết Ngược lại, nếu có 1 bên khởi kiện thì có 1 bên nguyên và bị đơn",80],["p",85,"+ Ban thư ký nhận đơn cùng hồ sơ -> báo cáo HĐTP -> gửi đơn kiện cho bên bị kiện (nếu có)",80],["p",85,"+ Sao y đơn kiện cho các nước thành viên khác để họ xem xét xem có liên quan đến họ hay k (họ là thành viên nên sẽ được quyền biết tòa đang nhận vụ việc nào, dù họ k liên quan thì có thể họ có bằng chứng để giúp đỡ)",80],["p",85,"+ Tiến hành thủ tục bổ trợ (tiền tố tụng): tòa có thẩm quyền hay k trong trường hợp kiện đơn phương (bên bị đơn k đồng ý thì phải chứng minh việc có tq); đơn kiện có nhiều yêu cầu thì có thể tách đơn kiện để giải quyết hoặc bên cạnh đó là hợp nhất vụ kiện; các nước khác có nhu cầu tham gia -> tòa xem xét về tư cách tham gia (nguyên-bị-ng liên quan)",80],["p",85,"+ Xét xử về mặt nd:",80],["p",121,"+ theo thủ tục viết (qtrình các bên gửi hồ sơ để tòa xem xét, nếu các bên cùng gửi đơn yêu cầu gq thì tự hẹn giờ để nộp cùng lúc cho tiện).",80],["p",157,"- Bị vong lục: ghi nhận đầy đủ các vấn đề của các bên, các bằng chứng chứng cứ giấy tờ thực tế mà 2 bên đã chuẩn bị. Phải chuẩn bị đầy đủ chi tiết các vấn đề của mỗi bên, yêu sách là gì chính sách mà họ muốn là gì (càng chi tiết càng tốt)",80],["p",157,"- Phản bị vong lục: là phản biện lại bản bị vong lục của bên kia => đều sao y bản chính và lưu lại chỗ tòa.",80],["p",121,"+ thủ tục nói (tổ chức các phiên tòa), các TP đều tgia HĐXX. Điều khiển tòa là chánh án -> phó chánh án -> TP lớn tuổi nhất. Các bên cử đại diện để tranh tụng.",81],["p",121,"+ Xét thấy có thể chấm dứt tranh tụng và tiến hành nghị án để ra phán quyết XX công khai nhưng nghị án kín => dự thảo phán quyết được thông qua (quan điểm của từng TP đều được đính kèm theo phán quyết) = cách bổ phiếu quá bán (có thể bỏ phiếu trắng)",81],["p",67,"Nếu kết quả 50/50 thì theo chánh án (Chánh án luật bất thành văn thì bắt buộc không được bỏ phiếu trắng)",81],["p",85,"+ Phán quyết: bắt buộc, là chung thẩm Phụ lục VI UNCLOS chỉ dừng ở đây ( nhược điểm: k có cơ chế cưỡng chế thực thi)",81],["p",103,"=> Nếu bên kia k thực hiện phán quyết -> gửi đơn ra HĐ bảo an LHQ để cưỡng chế => nên thực tế họ thích đưa ra TACLQT để gq hơn vì nó có cái này.",81],["p",103,"Tất cả các nước khác đều nhận được đơn kiện, vì sao? Vì có thể để họ xem xét xem vụ tranh chấp này có liên quan tới mình hay không, nếu có thì họ cũng có quyền tham gia. Vì tòa xét xử công khai Nếu 1 bên gửi đơn kiện còn bên kia k đồng ý thì sao?",81],["p",67,"Phán quyết quan trọng hầu hết sẽ đưa ra tòa án công lý quốc tế luôn",81],["p",67,"Giải quyết tranh chấp tại Toà trọng tài quốc tế về Luật Biển (Phụ lục VII)",81],["p",103,"1. Cơ sở pháp lý: Phụ lục VII Công ước 1982 về Luật Biển",81]],"pg":[79,81]},{"h":"2. Thành phần - tổ chức của toà trọng tài","lv":3,"b":[["p",85,"● Mỗi quốc gia thành viên cử 4 trọng tài có kinh nghiệm về những vấn đề biển",81],["p",85,"● Gửi danh sách đến Tổng thư ký để tập hợp các trọng tài viên lập thành một bản danh sách lớn.",81],["p",85,"● Khi phát sinh tranh chấp, các bên thoả thuận lựa chọn 5 trọng tài viên thành lập toà trọng tài (Điều 3 Phụ lục VII)",81],["p",121,"- Bên khởi kiện chọn 1 TTV đầu tiên, bị kiện chọn 1 TTV tiếp theo (2 ng này có thể là cdân của họ)",81],["p",121,"- 3 TTV còn lại thì là thỏa thuận lựa chọn (phải là cdân của nước thứ 3). Nếu k cử thì Chánh án chọn thay.",81],["p",67,"Đây chỉ là cơ chế thường trực chứ k phải trụ sở thường trực.",81],["p",103,"Trường hợp Phi kiện TQ => Phi cùng trọng tài thống nhất chọn Nga hoặc Hà Lan, ban thư ký được chọn sẽ là Lahay sẽ hỗ trợ giúp về mặt hình chính vì nơi được chọn để GQ đã có sẵn ban thư ký. Tòa theo phụ lục 7 chỉ là trụ sở thường trực th",81],["p",67,"Đây là tòa được công ước rất ưu tiên",81],["p",103,"3. Xác lập thẩm quyền của Toà trọng tài ((Điều 287 Công ước)",82],["p",85,"● Khi các bên tranh chấp thoả thuận k4 đ 287",82],["p",85,"● Khi một quốc gia thành viên tham gia vụ tranh chấp mà không được một tuyên bố còn hiệu lực bảo vệ thì được xem là đã chấp nhận thủ tục trọng tài k3 đ 287",82],["p",85,"● Nếu các bên không chấp nhận cùng một thủ tục để giải quyết tranh chấp thì vụ tranh chấp sẽ giải quyết theo thủ tục trọng tài k5 đ 287 (Điều 287 Công ước)",82],["p",67,"Nếu 1 nước k chấp nhận nhưng họ tham gia công ước thì tòa vẫn có quyền xử, vì khi tham gia vào công ước thì họ cũng đã chấp nhận trước là tòa có quyền xử r",82],["p",67,"Những giới hạn áp dụng của mục 2 => nếu là tranh chấp tại 297, 298 thì chỉ khi 2 bên đều nói rõ với tòa thì tòa mới xử??????",82]],"pg":[81,82]},{"h":"4. Trình tự thủ tục","lv":3,"b":[["p",85,"● Do các bên tự thoả thuận (Điều 5, Phụ lục VII)",82],["p",85,"● Nếu các bên không có thoả thuận, toà sẽ tự quy định",82],["p",85,"● Nếu toà xét thấy đơn kiện có cơ sở thực tế và lý lẽ thì toà trọng tài sẽ xử và ra phán quyết",82],["p",85,"● Việc vắng mặt hay không trình bày lý lẽ của một bên không cản trở quá trình tố tụng của toà Tương tự tòa quốc tế về luật biển.",82],["p",67,"Việc 1 bên k tham gia vào tiến trình xét xử có nghĩa họ đã từ bỏ quyền lợi của mình và nó cũng k ảnh hưởng gì đến việc gq vụ việc. But, họ có thể kháng cáo.",82]],"pg":[82,82]},{"h":"5. Giá trị hiệu lực của Phán quyết","lv":3,"b":[["p",67,"Phán quyết của Toà có giá trị hiệu lực bắt buộc đối với các bên trong vụ tranh chấp, trừ khi các bên có thoả thuận thủ tục kháng cáo (Điều 11, Phục lục VII)",82],["p",67,"Giải quyết tranh chấp tại Toà trọng tài đặc biệt (Phụ lục VIII)",82],["p",103,"Thành phần của tòa:",82],["p",67,"bao gồm các chuyên viên ở mỗi lĩnh vực nhất định do các bên tranh chấp cử",82],["p",67,"Tổ chức liên chính phủ được thành lập tại Phụ lục VI UNCLOS (quy tắc bầu, tư cách thẩm phán, tlâp HĐXX)",82],["p",103,"Thẩm quyền:",82],["p",67,"Tiến hành điều tra, xác minh nguồn gốc vụ tranh chấp, đưa ra các khuyến nghị giải quyết -=> k có tính bắt buộc.",82],["p",67,"Thủ tục là tố tụng nhưng kết luận lại chỉ mang tính khuyến nghị => nửa nạc nửa mỡ, chẳng phải tòa quốc tế mà cũng chẳng phải trọng tài.",83],["p",103,"Các vụ việc thuộc thẩm quyền điều tra, xác minh của toà",83],["p",103,"Đánh bắt hải sản",83],["p",103,"Bảo vệ và giữ gìn môi trường biển",83],["p",103,"Nghiên cứu khoa học biển",83],["p",103,"Hàng hải",83],["p",67,"(Phụ lục VIII Công ước 1982 về Luật biển)",83],["p",67,"Chương trình phát triển và BVMT của LHP sẽ đảm nhận",83],["p",103,"Giá trị của các khuyến nghị",83],["p",67,"Chỉ mang tính chất tham khảo, không có giá trị bắt buộc",83],["p",67,"Đ287: K3",83],["p",67,"Tòa trọng tài đặc biệt: tức phán quyết mang tính bắt buộc",83],["p",67,"==============================",83],["p",67,"Lưu ý làm bài: chỉ có 75 phút",83],["p",67,"6 NĐ, 1 LT nên phân bổ hợp lý.",83],["p",67,"LT thì chỉ mang tính chất LT thuần túy, k có đặt trường hợp hay đánh đố.",83],["p",102,"Ghi chú thêm:",83],["p",102,"Nghị quyết của đại hội đồng không có quyền bắt buộc mà chỉ có tác động lớn",83],["p",67,"đến các nước",83],["p",102,"Chỉ có nghị quyết của Hội đồng bảo an thi mới có quyền bắt buộc",83],["p",102,"Nếu bờ biển phức tạp quá ( nhiều đảo ) thì không áp dụng theo cách bình",83],["p",67,"thường (ngân nước thủy triều xuống thấp nhất) mà Nối các điểm nhô ra xa nhất của",83],["p",67,"biển rồi hình thành nên đường cơ sở ....",83],["p",102,"Nếu đường cơ sở bình thuơ gf thì ngấn nước thủy triều xuống thấp nhất",83],["p",85,"⇒ Hình thành cách thức đường cơ sở mới, hoàn thiện hơn với các đặc điểm khác",84],["p",103,"nhau",84]],"pg":[82,84]}]}];
